namespace App\Http\Resources\Admin;

use Illuminate\Http\Request;
use Illuminate\Http\Resources\Json\JsonResource;

class PriceListResource extends JsonResource
{
    /**
     * Transform the resource into an array.
     *
     * @return array<string, mixed>
     */
    public function toArray(Request $request): array
    {
        return [
            'id' => $this->id,
            'name' => $this->name,
            'type' => $this->type,
            'customer' => $this->whenLoaded('customer', fn () => $this->customer ? [
                'id' => $this->customer->id, 'name' => $this->customer->name,
            ] : null),
            'customer_group' => $this->whenLoaded('customerGroup', fn () => $this->customerGroup ? [
                'id' => $this->customerGroup->id, 'name' => $this->customerGroup->name, 'code' => $this->customerGroup->code,
            ] : null),
            'branch' => $this->whenLoaded('branch', fn () => $this->branch ? [
                'id' => $this->branch->id, 'name' => $this->branch->name,
            ] : null),
            'currency' => $this->currency,
            'starts_at' => $this->starts_at,
            'ends_at' => $this->ends_at,
            'priority' => $this->priority,
            'is_active' => $this->is_active,
            'items_count' => $this->whenCounted('items'),
            'created_at' => $this->created_at,
        ];
    }
}<?php

declare(strict_types=1);

namespace App\Console\Commands;

use App\Enums\QuotationStatus;
use App\Enums\WholesalePaymentNoticeStatus;
use App\Models\Quotation;
use App\Models\WholesalePaymentNotice;
use App\Notifications\StaffRecipients;
use App\Notifications\WholesaleDeskNotification;
use App\Services\SettingService;
use App\Services\Wholesale\WholesaleOutbox;
use Illuminate\Console\Command;
use Illuminate\Support\Facades\Notification;

/**
 * Escalates quotation requests and payment notices exceeding SLA review thresholds to staff.
 */
class EscalateStaleWholesale extends Command
{
    protected $signature = 'wholesale:escalate-stale';

    protected $description = 'Alert sales when a quote or payment notice waits past its SLA';

    public function handle(SettingService $settings, WholesaleOutbox $outbox): int
    {
        $quoteHours = max(1, (int) $settings->get('ai_wholesale_quote_sla_hours', 24));
        $noticeHours = max(1, (int) $settings->get('ai_wholesale_notice_sla_hours', 24));
        $quotes = Quotation::query()
            ->where('status', QuotationStatus::Requested)
            ->where('updated_at', '<=', now()->subHours($quoteHours))
            ->count();
        $notices = WholesalePaymentNotice::query()
            ->where('status', WholesalePaymentNoticeStatus::PendingReview)
            ->where('created_at', '<=', now()->subHours($noticeHours))
            ->count();
        if ($quotes === 0 && $notices === 0) {
            return self::SUCCESS;
        }
        $day = now((string) config('app.business_timezone', 'Africa/Cairo'))->toDateString();
        $message = "تصعيد: {$quotes} عروض تجاوزت {$quoteHours} ساعة، و{$notices} إشعارات تجاوزت {$noticeHours} ساعة.";
        $recipients = StaffRecipients::withAnyPermission(['quotations.price']);
        if ($recipients->isNotEmpty()) {
            Notification::send($recipients, new WholesaleDeskNotification('wholesale_escalation', $message, []));
        }
        $outbox->queue("staff-escalation:{$day}", 'staff_whatsapp', null, 'staff_escalation', ['message' => $message], deliver: true);

        return self::SUCCESS;
    }
}<?php

declare(strict_types=1);

namespace App\Console\Commands;

use App\Enums\QuotationStatus;
use App\Models\Quotation;
use App\Services\QuotationService;
use Illuminate\Console\Command;
use Throwable;

/**
 * Transitions priced quotations past their validity window to expired status.
 */
class ExpireQuotations extends Command
{
    protected $signature = 'quotations:expire';

    protected $description = 'Expire priced quotations whose valid_until date has passed';

    public function handle(QuotationService $quotations): int
    {
        $expired = 0;
        Quotation::query()
            ->where('status', QuotationStatus::PricedByAdmin)
            ->whereNotNull('valid_until')
            ->whereDate('valid_until', '<', now()->toDateString())
            ->orderBy('id')
            ->each(function (Quotation $quotation) use ($quotations, &$expired): void {
                try {
                    $quotations->expire($quotation);
                    $expired++;
                } catch (Throwable $e) {
                    report($e);
                }
            });

        $this->info("Expired {$expired} quotations.");

        return self::SUCCESS;
    }
}<?php

declare(strict_types=1);

namespace App\Console\Commands;

use App\Enums\OrderStatus;
use App\Events\OrderBecameOverdue;
use App\Models\Order;
use App\Models\OutboundMessage;
use Illuminate\Console\Command;

/**
 * Detects unpaid wholesale credit orders past their due date and triggers overdue notifications.
 */
class MarkWholesaleOverdue extends Command
{
    protected $signature = 'wholesale:mark-overdue';

    protected $description = 'Dispatch OrderBecameOverdue once for each unpaid credit order past due_at';

    public function handle(): int
    {
        $marked = 0;
        Order::query()
            ->where('payment_method', 'credit')
            ->where('payment_status', 'unpaid')
            ->where('status', '!=', OrderStatus::Cancelled->value)
            ->whereNotNull('due_at')
            ->where('due_at', '<', now()->startOfDay())
            ->orderBy('id')
            ->each(function (Order $order) use (&$marked): void {
                $due = $order->due_at?->toDateString() ?? '';
                $key = "order-overdue:{$order->id}:{$due}";
                if (OutboundMessage::query()->where('idempotency_key', $key)->exists()) {
                    return;
                }
                OrderBecameOverdue::dispatch($order);
                $marked++;
            });

        $this->info("Marked {$marked} overdue orders.");

        return self::SUCCESS;
    }
}<?php

declare(strict_types=1);

namespace App\Console\Commands;

use App\Enums\QuotationStatus;
use App\Models\OutboundMessage;
use App\Models\Quotation;
use App\Notifications\WholesaleDeskNotification;
use App\Services\Wholesale\WholesaleOutbox;
use Illuminate\Console\Command;

/**
 * Sends quotation expiry reminder notifications to merchants ahead of quote validity deadlines.
 */
class QuoteExpiryReminders extends Command
{
    protected $signature = 'wholesale:quote-expiry-reminders';

    protected $description = 'Remind opted-in traders 48 hours before a priced quotation expires';

    public function handle(WholesaleOutbox $outbox): int
    {
        $sent = 0;
        $until = now()->addDays(2)->toDateString();
        Quotation::query()
            ->with('customer')
            ->where('status', QuotationStatus::PricedByAdmin)
            ->whereNotNull('valid_until')
            ->whereDate('valid_until', '>', now()->toDateString())
            ->whereDate('valid_until', '<=', $until)
            ->orderBy('id')
            ->each(function (Quotation $quotation) use ($outbox, &$sent): void {
                $valid = $quotation->valid_until?->toDateString() ?? '';
                $key = "quote-expiry:{$quotation->id}:{$valid}";
                if (OutboundMessage::query()->where('idempotency_key', $key)->exists()) {
                    return;
                }
                $customer = $quotation->customer;
                $message = "عرض السعر {$quotation->quotation_number} هينتهي يوم {$valid}.";
                $customer?->notify(new WholesaleDeskNotification('quotation_expiring', $message, [
                    'quotation_id' => $quotation->id,
                ]));
                $outbox->queue(
                    $key,
                    'customer_whatsapp',
                    $customer?->id,
                    'quotation_expiring',
                    ['quotation_id' => $quotation->id, 'quotation_number' => $quotation->quotation_number, 'valid_until' => $valid],
                    $outbox->nextContactAt($customer),
                    $outbox->customerAllowsWhatsapp($customer),
                );
                $sent++;
            });

        $this->info("Queued {$sent} quotation expiry reminders.");

        return self::SUCCESS;
    }
}<?php

