export const D = (s) => <span className="num">{s}</span>;import { useState, useEffect, useCallback } from 'react';

export function useApi(fetcher, deps = [], enabled = true) {
  const [state, setState] = useState('loading'); // loading | ready | error
  const [data, setData] = useState(null);
  const [error, setError] = useState(null);
  const [tick, setTick] = useState(0);

  useEffect(() => {
    if (!enabled) return;
    const ctrl = new AbortController();
    setState('loading');
    setError(null);
    Promise.resolve().then(() => fetcher(ctrl.signal))
      .then((d) => { if (!ctrl.signal.aborted) { setData(d); setState('ready'); } })
      .catch((e) => { if (!ctrl.signal.aborted) { setError(e); setState('error'); } });
    return () => ctrl.abort();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [...deps, tick, enabled]);

  const reload = useCallback(() => setTick((t) => t + 1), []);
  return { state, data, error, reload, retry: reload, setData };
}const MB = 1024 * 1024;

export function validateReturnFiles(groups) {
  if (groups.some((files) => files.length > 5)) return 'الحد الأقصى 5 صور للبند.';
  const files = groups.flat();
  if (files.length > 10) return 'الحد الأقصى 10 صور إجمالي.';
  if (files.some((f) => !['image/jpeg', 'image/png', 'image/webp'].includes(f.type))) return 'الأنواع المسموحة JPG / PNG / WebP فقط.';
  if (files.some((f) => f.size > 5 * MB)) return 'الحد الأقصى 5 ميجابايت للصورة.';
  if (files.reduce((sum, f) => sum + f.size, 0) > 25 * MB) return 'إجمالي حجم الصور حتى 25 ميجابايت.';
  return null;
}<?php

declare(strict_types=1);

namespace App\Console\Commands;

use App\Models\Customer;
use App\Services\Wholesale\WholesaleOutbox;
use Illuminate\Console\Command;

/**
 * Enqueues automated monthly account statements for opted-in wholesale customers.
 */
class WholesaleMonthlyStatements extends Command
{
    protected $signature = 'wholesale:monthly-statements';

    protected $description = 'Queue the monthly statement for opted-in wholesale customers';

    public function handle(WholesaleOutbox $outbox): int
    {
        $month = now((string) config('app.business_timezone', 'Africa/Cairo'))->format('Y-m');
        Customer::query()
            ->commercial()
            ->where('status', 'approved')
            ->whereNotNull('whatsapp_opt_in_at')
            ->orderBy('id')
            ->each(function (Customer $customer) use ($outbox, $month): void {
                $outbox->queue(
                    "monthly-statement:{$customer->id}:{$month}",
                    'customer_whatsapp',
                    $customer->id,
                    'customer_statement',
                    ['month' => $month],
                    $outbox->nextContactAt($customer),
                    true,
                );
            });

        return self::SUCCESS;
    }
}<?php

