declare(strict_types=1);

namespace App\Services\Wholesale;

use App\Models\Quotation;

/**
 * Computes deterministic revision hashes for quotation payloads to guarantee optimistic concurrency.
 */
final class QuotationVersion
{
    /**
     * Generates a SHA-256 fingerprint representing the current pricing, quantity, and status state.
     *
     * @param  Quotation  $quotation  Quotation instance to fingerprint.
     * @return string Hex-encoded SHA-256 hash.
     */
    public static function hash(Quotation $quotation): string
    {
        $quotation->loadMissing('items');
        // Sort items by ID to guarantee identical hash calculation across different query orders.
        $items = $quotation->items
            ->sortBy('id')
            ->map(fn ($item) => $item->id.'|'.$item->qty.'|'.$item->offered_unit_price.'|'.$item->requested_target_price)
            ->implode(';');

        // Include status, updated_at, and item payload to invalidate proposals if modified concurrently.
        return hash('sha256', $quotation->status->value.'|'.$quotation->updated_at?->toIso8601String().'|'.$items);
    }
}<?php

declare(strict_types=1);

namespace App\Services\Wholesale;

use App\Enums\QuotationStatus;
use App\Models\OrderItem;
use App\Models\ProductVariant;
use App\Models\Quotation;
use App\Models\StockLevel;
use App\Models\User;
use App\Services\CostAccess;
use App\Services\PricingService;
use App\Services\SettingService;
use Illuminate\Support\Facades\DB;

/**
 * Recommends line item pricing for wholesale quotations based on cost bounds, tier prices, and historical acceptance.
 */
final class QuoteAdvisor
{
    public function __construct(
        private PricingService $pricing,
        private SettingService $settings,
    ) {}

    /**
     * Evaluates quotation line items and suggests optimal pricing based on list prices, costs, and historical rates.
     *
     * @param  Quotation  $quotation  Quotation request requiring line pricing.
     * @param  User|null  $actor  Staff user reviewing the quote (used for cost visibility authorization).
     * @return array{lines: list<array<string, mixed>>, warnings: list<string>} Line suggestions with rationale and warnings.
     */
    public function suggest(Quotation $quotation, ?User $actor): array
    {
        $quotation->loadMissing(['items.variant', 'customer']);
        // Hide cost price when the acting staff user lacks authorization, preventing profit margin leakage.
        $canCost = CostAccess::canView($actor);
        $policy = (string) $this->settings->get('ai_price_below_cost_policy', 'block');
        $variantIds = $quotation->items->pluck('product_variant_id')->filter()->unique()->values()->all();
        $customerId = (int) $quotation->customer_id;

        $stockMap = $this->batchAvailable($variantIds);
        $lastSoldMap = $this->batchLastSold($customerId, $variantIds);
        $acceptanceMap = $this->batchAcceptanceRates($customerId, $variantIds);

        $lines = [];
        foreach ($quotation->items as $item) {
            $variant = $item->variant;
            $qty = (float) $item->qty;
            $resolved = $variant instanceof ProductVariant
                ? $this->pricing->resolve($variant, $quotation->customer, $qty)
                : ['unit_price' => 0.0, 'base_price' => 0.0, 'source' => 'missing'];
            $list = round((float) $resolved['unit_price'], 2);
            $requested = $item->requested_target_price !== null ? round((float) $item->requested_target_price, 2) : null;
            $cost = $canCost && $variant !== null ? round((float) $variant->cost_price, 2) : null;
            $suggested = $list;
            $reason = 'سعر القائمة عند الكمية المطلوبة';
            // Float epsilon (+0.001) avoids rounding jitter when requested price matches unit cost exactly.
            if ($requested !== null && ($cost === null || $requested + 0.001 >= $cost || $policy === 'warn')) {
                if ($requested <= $list) {
                    $suggested = $requested;
                    $reason = 'السعر الذي طلبه التاجر';
                }
            } elseif ($requested !== null && $cost !== null && $requested < $cost && $policy === 'block') {
                $reason = 'السعر المطلوب أقل من التكلفة، والسياسة تمنع النزول تحتها';
            }
            $variantId = (int) $item->product_variant_id;
            $lines[] = [
                'quotation_item_id' => $item->id,
                'sku' => $variant?->sku,
                'list_price' => $list,
                'requested_price' => $requested,
                'suggested_price' => $suggested,
                'cost' => $cost,
                'stock_available' => $stockMap[$variantId] ?? 0.0,
                'last_sold_price' => $lastSoldMap[$variantId] ?? null,
                'acceptance_rate' => $acceptanceMap[$variantId] ?? null,
                'reason' => $reason,
            ];
        }

        return ['lines' => $lines, 'warnings' => []];
    }

    /**
     * @param  list<int>  $variantIds
     * @return array<int, float>
     */
    private function batchAvailable(array $variantIds): array
    {
        if ($variantIds === []) {
            return [];
        }

        // Net available stock excludes both reserved units and damaged inventory.
        return StockLevel::query()
            ->whereIn('product_variant_id', $variantIds)
            ->groupBy('product_variant_id')
            ->selectRaw('product_variant_id, COALESCE(SUM(COALESCE(on_hand, 0) - COALESCE(reserved, 0) - COALESCE(damaged, 0)), 0) as available')
            ->pluck('available', 'product_variant_id')
            ->map(fn ($v) => round((float) $v, 2))
            ->all();
    }

    /**
     * @param  list<int>  $variantIds
     * @return array<int, float>
     */
    private function batchLastSold(int $customerId, array $variantIds): array
    {
        if ($variantIds === []) {
            return [];
        }

        $latestItemIds = OrderItem::query()
            ->join('orders', 'orders.id', '=', 'order_items.order_id')
            ->where('orders.customer_id', $customerId)
            ->whereNotIn('orders.status', ['cancelled', 'draft'])
            ->whereIn('order_items.product_variant_id', $variantIds)
            ->groupBy('order_items.product_variant_id')
            ->selectRaw('MAX(order_items.id) as max_id')
            ->pluck('max_id');

        if ($latestItemIds->isEmpty()) {
            return [];
        }

        return OrderItem::query()
            ->whereIn('id', $latestItemIds)
            ->pluck('unit_price', 'product_variant_id')
            ->map(fn ($price) => round((float) $price, 2))
            ->all();
    }

    /**
     * @param  list<int>  $variantIds
     * @return array<int, float>
     */
    private function batchAcceptanceRates(int $customerId, array $variantIds): array
    {
        if ($variantIds === []) {
            return [];
        }

        // Exclude open/draft quotations from denominator so in-flight negotiations do not depress acceptance rate.
        $rows = DB::table('quotation_items')
            ->join('quotations', 'quotations.id', '=', 'quotation_items.quotation_id')
            ->where('quotations.customer_id', $customerId)
            ->whereIn('quotation_items.product_variant_id', $variantIds)
            ->whereIn('quotations.status', [
                QuotationStatus::Accepted->value,
                QuotationStatus::Rejected->value,
                QuotationStatus::Expired->value,
            ])
            ->selectRaw('quotation_items.product_variant_id, quotations.status, count(*) as c')
            ->groupBy('quotation_items.product_variant_id', 'quotations.status')
            ->get();

        $rates = [];
        $byVariant = $rows->groupBy('product_variant_id');
        foreach ($byVariant as $vId => $statusCounts) {
            $total = (int) $statusCounts->sum('c');
            if ($total > 0) {
                $accepted = (int) ($statusCounts->firstWhere('status', QuotationStatus::Accepted->value)?->c ?? 0);
                $rates[(int) $vId] = round(($accepted / $total) * 100, 1);
            }
        }

        return $rates;
    }
}<?php

declare(strict_types=1);

namespace App\Services\Wholesale;

use App\Services\Ai\ToolOutcome;
use Carbon\Carbon;

/**
 * Evaluates match confidence between merchant-declared payment notices and receipt image OCR fields.
 *
 * Treats OCR output strictly as untrusted data to mitigate image-based prompt injections.
 */
final class ReceiptMatchScorer
{
    /**
     * Calculates confidence score (0-100) based on weighted comparison of payment fields.
     *
     * @param  array{amount: string, reference: string, date: string, bank: string}  $stated  Merchant-submitted notice fields.
     * @param  array<string, mixed>  $read  OCR-extracted fields from receipt image.
     * @return array{score: float, ocr: array<string, mixed>} Score and sanitized, untrusted OCR payload.
     */
    public function score(array $stated, array $read): array
    {
        $amount = $this->money($read['amount'] ?? null);
        $reference = $this->text($read['reference'] ?? null);
        $bank = $this->text($read['bank'] ?? null);
        $sender = $this->text($read['sender'] ?? null);
        $date = $this->date($read['date'] ?? null);

        $score = 0.0;
        // Primary invariant: exact amount match contributes 50% of the total confidence score.
        if ($amount !== null && abs((float) $amount - (float) $stated['amount']) < 0.009) {
            $score += 50;
        }
        // Unique transaction reference match contributes 30% to prevent cross-account misallocation.
        if ($reference !== '' && mb_strtolower($reference) === mb_strtolower(trim($stated['reference']))) {
            $score += 30;
        }
        if ($date !== null) {
            $statedDate = Carbon::parse($stated['date'])->startOfDay();
            // Allow a 1-day tolerance (15%) for interbank transfer cutoff times and weekend clearing delays.
            if (abs($statedDate->diffInDays(Carbon::parse($date)->startOfDay(), true)) <= 1) {
                $score += 15;
            }
        }
        // Substring comparison (5%) accommodates abbreviations and informal bank names (e.g. CIB vs Commercial Int Bank).
        if ($bank !== '' && (mb_stripos($stated['bank'], $bank) !== false || mb_stripos($bank, $stated['bank']) !== false)) {
            $score += 5;
        }

        return [
            'score' => min(100, $score),
            'ocr' => [
                'amount' => $amount,
                // Mark OCR string fields as untrusted to stop downstream LLMs from executing text inside images.
                'reference' => ToolOutcome::untrusted($reference, 80),
                'date' => $date,
                'bank' => ToolOutcome::untrusted($bank, 80),
                'sender' => ToolOutcome::untrusted($sender, 80),
            ],
        ];
    }

    private function money(mixed $value): ?string
    {
        if (is_int($value) || is_float($value)) {
            return number_format((float) $value, 2, '.', '');
        }
        if (! is_string($value) || ! preg_match('/^\d+(\.\d{1,2})?$/', trim($value))) {
            return null;
        }

        return number_format((float) trim($value), 2, '.', '');
    }

    private function text(mixed $value): string
    {
        if (! is_string($value)) {
            return '';
        }

        return ToolOutcome::untrusted($value, 80)['untrusted_text'];
    }

    private function date(mixed $value): ?string
    {
        if (! is_string($value) || ! preg_match('/^\d{4}-\d{2}-\d{2}$/', $value)) {
            return null;
        }

        return $value;
    }
}<?php

declare(strict_types=1);

namespace App\Services\Wholesale;

use App\Jobs\SendOutboundMessage;
use App\Models\Customer;
use App\Models\OutboundMessage;
use Carbon\CarbonInterface;
use Illuminate\Database\UniqueConstraintViolationException;
use Throwable;

/**
 * Persists outbound wholesale customer messages to a database outbox for transactional delivery.
 */
final class WholesaleOutbox
{
    /**
     * Enqueues an outbound notification using idempotency deduplication and opt-in enforcement.
     *
     * @param  string  $key  Idempotency key uniquely identifying this notification event.
     * @param  string  $channel  Delivery channel name (e.g. customer_whatsapp, sms).
     * @param  int|null  $customerId  Recipient customer ID if known.
     * @param  string  $template  Template identifier approved by provider.
     * @param  array<string, mixed>  $payload  Template placeholder variables.
     * @param  CarbonInterface|null  $scheduledFor  Deferred dispatch timestamp if scheduled.
     * @param  bool  $deliver  False when customer lacks opt-in consent to record skipped audit.
     */
    public function queue(
        string $key,
        string $channel,
        ?int $customerId,
        string $template,
        array $payload,
        ?CarbonInterface $scheduledFor = null,
        bool $deliver = true,
    ): void {
        try {
            $message = OutboundMessage::query()->create([
                'customer_id' => $customerId,
                'channel' => $channel,
                'idempotency_key' => $key,
                'status' => $deliver ? 'pending' : 'skipped',
                'template' => $template,
                'payload' => $payload,
                // Mark as skipped when the customer has not explicitly opted into notifications.
                'error' => $deliver ? null : 'no_opt_in',
                'scheduled_for' => $scheduledFor,
            ]);
        } catch (UniqueConstraintViolationException) {
            // Silently drop duplicate idempotency keys to guarantee at-most-once enqueue semantics.
            return;
        }

        if ($deliver) {
            SendOutboundMessage::dispatch($message->id);
        }
    }

    /**
     * Checks if the merchant has granted explicit opt-in consent for WhatsApp communications.
     */
    public function customerAllowsWhatsapp(?Customer $customer): bool
    {
        // Meta Business Policy mandates verified opt-in consent prior to sending unsolicited messages.
        return $customer?->whatsapp_opt_in_at !== null;
    }

    /**
     * Calculates next allowed contact time based on merchant preferred business hours.
     *
     * @param  Customer|null  $customer  Customer with optional preferred_contact_hours settings.
     * @return CarbonInterface Target contact timestamp aligned with business window in local timezone.
     */
    public function nextContactAt(?Customer $customer): CarbonInterface
    {
        $tz = (string) config('app.business_timezone', 'Africa/Cairo');
        $now = now($tz);
        $hours = $customer?->preferred_contact_hours;
        if (! is_array($hours) || ! isset($hours['from'], $hours['to'])) {
            return $now;
        }

        try {
            $from = $now->copy()->setTimeFromTimeString((string) $hours['from']);
            $to = $now->copy()->setTimeFromTimeString((string) $hours['to']);
        } catch (Throwable) {
            return $now;
        }

        if ($now->betweenIncluded($from, $to)) {
            return $now;
        }

        // If outside hours, defer until the opening hour today or the following morning.
        return $now->lt($from) ? $from : $from->copy()->addDay();
    }
}<?php

