namespace Database\Seeders;

use App\Enums\StaffRole;
use Illuminate\Database\Seeder;
use Spatie\Permission\Models\Permission;
use Spatie\Permission\Models\Role;
use Spatie\Permission\PermissionRegistrar;

/**
 * Wholesale portal administrative permissions (quotation pricing and payment notice reviews).
 */
class WholesalePortalPermissionSeeder extends Seeder
{
    public function run(): void
    {
        app(PermissionRegistrar::class)->forgetCachedPermissions();

        $permissions = [
            'quotations.view', 'quotations.price',
            'payment_notices.view', 'payment_notices.approve', 'payment_notices.reject',
            'ai_agent.wholesale',
        ];

        $created = [];
        foreach ($permissions as $permission) {
            $created[] = Permission::firstOrCreate(['name' => $permission, 'guard_name' => 'staff']);
        }

        $superAdmin = Role::firstOrCreate(['name' => StaffRole::SuperAdmin->value, 'guard_name' => 'staff']);
        $superAdmin->givePermissionTo($created);
    }
}import { signedAttachmentUrl, allPages } from '@alfarid/api-client';

export const num = (v) => (v === null || v === undefined || v === '' ? null : Number(v));
export const day = (iso) => (iso ? String(iso).slice(0, 10) : null);
export const calendarDay = (date) => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
export const today = () => calendarDay(new Date());

export function apiError(e) {
  const r = e?.response;
  return {
    status: r?.status,
    message: r?.data?.message || 'حصل خطأ غير متوقع، حاول تاني.',
    fields: r?.data?.errors || {},
    code: r?.data?.code || r?.data?.errors?.code,
  };
}

export async function saveBlob(promise, fallbackName) {
  const res = await promise;
  const signedUrl = await signedAttachmentUrl(res);
  if (signedUrl) {
    const link = document.createElement('a');
    link.href = signedUrl;
    link.rel = 'noreferrer';
    document.body.appendChild(link);
    link.click();
    link.remove();
    return;
  }
  const cd = res.headers?.['content-disposition'] || '';
  const name = /filename="([^"]+)"/i.exec(cd)?.[1] || /filename=([^;\s]+)/i.exec(cd)?.[1] || fallbackName;
  const url = URL.createObjectURL(res.data);
  const a = document.createElement('a');
  a.href = url;
  a.download = name;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 60_000);
}

export const pageMeta = (meta) => ({ page: meta?.current_page ?? 1, pages: meta?.last_page ?? 1, total: meta?.total ?? 0, per: meta?.per_page ?? 15 });

