namespace App\Services\Ai\Wholesale\Tools;

use App\Exceptions\BusinessException;
use App\Models\AiPendingAction;
use App\Models\Customer;
use App\Models\User;
use App\Services\Ai\EntityResolver;
use App\Services\Ai\ProposalBuilder;
use App\Services\Ai\ToolKind;
use App\Services\Ai\ToolOutcome;
use App\Services\Ai\WriteTool;
use App\Services\QuotationService;
use App\Services\SpokenQuantity;

final class CreateQuotationForCustomerTool implements WriteTool
{
    public function __construct(
        private EntityResolver $resolver,
        private ProposalBuilder $proposals,
        private QuotationService $quotations,
    ) {}

    public function name(): string
    {
        return 'create_quotation_for_customer';
    }

    public function kind(): ToolKind
    {
        return ToolKind::Write;
    }

    public function risk(): string
    {
        return 'medium';
    }

    public function permissions(): array
    {
        return ['quotations.price'];
    }

    public function declaration(): array
    {
        return [
            'name' => $this->name(),
            'description' => 'ينشئ عرض سعر باسم تاجر جملة من نص الموظف، ويرسله للتسعير.',
            'parameters' => [
                'type' => 'OBJECT',
                'properties' => (object) [
                    'customer_id' => ['type' => 'INTEGER'],
                    'text' => ['type' => 'STRING'],
                ],
                'required' => ['customer_id', 'text'],
            ],
        ];
    }

    public function prepare(User $actor, array $args): ToolOutcome
    {
        $customer = Customer::query()->find((int) ($args['customer_id'] ?? 0));
        if (! $customer?->isWholesaleApproved()) {
            return ToolOutcome::denied('التاجر لازم يكون جملة أو موزع ومعتمد.', auditable: false);
        }
        $parsed = $this->parseLines($actor, (string) ($args['text'] ?? ''));
        if ($parsed instanceof ToolOutcome) {
            return $parsed;
        }

        return $this->proposals->make(
            $actor,
            $this->name(),
            ['customer_id' => $customer->id, 'items' => $parsed],
            title: 'عرض سعر لـ '.($customer->company_name ?: $customer->name),
            after: ['items' => $parsed],
        );
    }

    public function execute(User $actor, AiPendingAction $action): ToolOutcome
    {
        $customer = Customer::query()->findOrFail((int) $action->args['customer_id']);
        try {
            $draft = $this->quotations->create($customer, [
                'source' => 'admin',
                'items' => $action->args['items'],
            ]);
            $submitted = $this->quotations->submit($draft);
        } catch (BusinessException $e) {
            return ToolOutcome::denied($e->getMessage(), auditable: false);
        }

        return ToolOutcome::result(true, 'اتعمل العرض '.$submitted->quotation_number, [
            'quotation_id' => $submitted->id,
        ]);
    }

    /** @return list<array{product_variant_id: int, qty: float}>|ToolOutcome */
    private function parseLines(User $actor, string $text): array|ToolOutcome
    {
        $parts = preg_split('/\s*(?:,|،|\n| و )\s*/u', trim($text)) ?: [];
        $items = [];
        foreach ($parts as $part) {
            $part = trim($part);
            if ($part === '') {
                continue;
            }
            $qty = SpokenQuantity::parse($part) ?? 1.0;
            $query = trim((string) preg_replace('/\d+(\.\d+)?/u', '', $part));
            $matches = $this->resolver->variants($actor, $query);
            if (count($matches) !== 1) {
                return ToolOutcome::picker([
                    'type' => 'entity_picker',
                    'field' => 'text',
                    'purpose' => 'السطر "'.$part.'" محتاج صنف واحد واضح',
                    'options' => array_slice($matches, 0, 8),
                ]);
            }
            $items[] = ['product_variant_id' => $matches[0]['id'], 'qty' => $qty];
        }
        if ($items === []) {
            return ToolOutcome::denied('اكتب الأصناف والكميات.', auditable: false);
        }

        return $items;
    }
}<?php

declare(strict_types=1);

namespace App\Services\Ai\Wholesale\Tools;

use App\Enums\CustomerStatus;
use App\Enums\QuotationStatus;
use App\Enums\WholesalePaymentNoticeStatus;
use App\Models\Customer;
use App\Models\Quotation;
use App\Models\User;
use App\Models\WholesalePaymentNotice;
use App\Services\Ai\AgentTool;
use App\Services\Ai\ToolKind;
use App\Services\Ai\ToolOutcome;

final class WholesaleInboxTool implements AgentTool
{
    public function name(): string
    {
        return 'wholesale_inbox';
    }

    public function kind(): ToolKind
    {
        return ToolKind::Read;
    }

    public function risk(): string
    {
        return 'low';
    }

    public function permissions(): array
    {
        return ['quotations.view', 'payment_notices.view'];
    }

    public function declaration(): array
    {
        return [
            'name' => $this->name(),
            'description' => 'طابور شغل الجملة: عروض مستنية تسعير، إشعارات مستنية مراجعة، عروض قربت تنتهي، وطلبات تجار جديدة.',
            'parameters' => ['type' => 'OBJECT', 'properties' => (object) []],
        ];
    }

    public function handle(User $actor, array $args): ToolOutcome
    {
        $quotes = [];
        $expiring = [];
        if ($actor->can('quotations.view')) {
            $quotes = Quotation::query()
                ->with('customer:id,name,company_name')
                ->where('status', QuotationStatus::Requested)
                ->orderBy('id')
                ->limit(25)
                ->get()
                ->map(fn (Quotation $q) => [
                    'id' => $q->id,
                    'number' => $q->quotation_number,
                    'customer' => $q->customer?->company_name ?: $q->customer?->name,
                    'waiting_since' => $q->created_at?->toDateTimeString(),
                ])->all();
            $expiring = Quotation::query()
                ->where('status', QuotationStatus::PricedByAdmin)
                ->whereNotNull('valid_until')
                ->whereDate('valid_until', '>', now()->toDateString())
                ->whereDate('valid_until', '<=', now()->addDays(2)->toDateString())
                ->orderBy('valid_until')
                ->limit(25)
                ->get(['id', 'quotation_number', 'valid_until'])
                ->map(fn (Quotation $q) => [
                    'id' => $q->id,
                    'number' => $q->quotation_number,
                    'valid_until' => $q->valid_until?->toDateString(),
                ])->all();
        }

        $notices = [];
        if ($actor->can('payment_notices.view')) {
            $notices = WholesalePaymentNotice::query()
                ->with('customer:id,name,company_name')
                ->where('status', WholesalePaymentNoticeStatus::PendingReview)
                ->orderBy('id')
                ->limit(25)
                ->get()
                ->map(fn (WholesalePaymentNotice $n) => [
                    'id' => $n->id,
                    'number' => $n->notice_number,
                    'customer' => $n->customer?->company_name ?: $n->customer?->name,
                    'amount' => (string) $n->amount,
                    'match_score' => $n->match_score,
                ])->all();
        }

        $applications = Customer::query()
            ->commercial()
            ->where('status', CustomerStatus::Pending)
            ->orderBy('id')
            ->limit(15)
            ->get(['id', 'name', 'company_name', 'created_at'])
            ->map(fn (Customer $c) => [
                'id' => $c->id,
                'name' => $c->company_name ?: $c->name,
                'since' => $c->created_at?->toDateTimeString(),
            ])->all();

        $rows = [];
        foreach ($quotes as $row) {
            $rows[] = ['عرض مستني تسعير', $row['number'], (string) $row['customer'], (string) $row['waiting_since']];
        }
        foreach ($notices as $row) {
            $rows[] = ['إشعار مستني مراجعة', $row['number'], (string) $row['customer'], (string) $row['amount']];
        }
        foreach ($expiring as $row) {
            $rows[] = ['عرض قرب ينتهي', $row['number'], '', (string) $row['valid_until']];
        }
        foreach ($applications as $row) {
            $rows[] = ['طلب تاجر جديد', '#'.$row['id'], $row['name'], (string) $row['since']];
        }

        return ToolOutcome::data([
            'quotations_waiting' => $quotes,
            'notices_waiting' => $notices,
            'quotations_expiring' => $expiring,
            'new_dealer_applications' => $applications,
            'quick_actions' => ['get_quotation', 'get_payment_notice'],
        ], [
            'type' => 'table',
            'quick_actions' => [
                ['label' => 'تفاصيل عرض', 'tool' => 'get_quotation'],
                ['label' => 'تفاصيل إشعار', 'tool' => 'get_payment_notice'],
            ],
            'columns' => ['النوع', 'الرقم', 'التاجر', 'التفصيل'],
            'rows' => $rows,
        ]);
    }
}<?php

declare(strict_types=1);

namespace App\Services\Wholesale;

use App\Enums\WholesalePaymentNoticeStatus;
use App\Models\Customer;
use App\Models\WholesalePaymentNotice;
use Carbon\Carbon;
use Illuminate\Database\Eloquent\Collection;

/**
 * Reconciles parsed bank statement credit transactions against pending wholesale payment notices.
 */
final class BankStatementMatcher
{
    /** @var Collection<int, Customer>|null */
    private ?Collection $cachedCustomers = null;

    /**
     * Classifies statement credit transactions into exact, probable, or unmatched buckets against pending payment notices.
     *
     * @param  list<array{amount: float|string, reference?: string, date?: string, description?: string}>  $rows  Statement rows.
     * @return array{exact: list<array<string, mixed>>, probable: list<array<string, mixed>>, unmatched: list<array<string, mixed>>} Categorized reconciliations.
     */
    public function match(array $rows): array
    {
        $notices = WholesalePaymentNotice::query()
            ->with('customer:id,name,company_name')
            ->where('status', WholesalePaymentNoticeStatus::PendingReview)
            ->get();

        $preparedNotices = $notices->map(fn ($n) => [
            'model' => $n,
            'amount' => number_format((float) $n->amount, 2, '.', ''),
            'reference' => mb_strtolower(trim((string) $n->reference_number)),
            'date' => $n->transfer_date?->copy()->startOfDay(),
        ]);

        $exact = [];
        $probable = [];
        $unmatched = [];
        foreach ($rows as $index => $row) {
            $amount = number_format((float) ($row['amount'] ?? 0), 2, '.', '');
            $reference = mb_strtolower(trim((string) ($row['reference'] ?? '')));
            $date = isset($row['date']) ? Carbon::parse((string) $row['date'])->startOfDay() : null;
            $hit = null;
            $kind = null;
            foreach ($preparedNotices as $prepared) {
                $sameAmount = $prepared['amount'] === $amount;
                $sameReference = $reference !== '' && $prepared['reference'] === $reference;
                $closeDate = $date !== null && abs($date->diffInDays($prepared['date'] ?? $date, true)) <= 1;
                // Exact match requires matching amount, sanitized reference, and date within a 1-day banking window.
                if ($sameAmount && $sameReference && $closeDate) {
                    $hit = $prepared['model'];
                    $kind = 'exact';
                    break;
                }
                // Probable match pairs matching amounts having either identical reference or close date.
                if ($hit === null && $sameAmount && ($sameReference || $closeDate)) {
                    $hit = $prepared['model'];
                    $kind = 'probable';
                }
            }
            $entry = [
                'row' => $index,
                'amount' => $amount,
                'reference' => (string) ($row['reference'] ?? ''),
                'notice_id' => $hit?->id,
                'notice_number' => $hit?->notice_number,
            ];
            if ($kind === 'exact') {
                $exact[] = $entry;
            } elseif ($kind === 'probable') {
                $probable[] = $entry;
            } else {
                $entry['suggestion'] = $this->suggestCustomer((string) ($row['description'] ?? ''));
                $unmatched[] = $entry;
            }
        }

        return ['exact' => $exact, 'probable' => $probable, 'unmatched' => $unmatched];
    }

    /**
     * Fallback lookup: scans statement narration text against customer trade names to suggest sender.
     *
     * @return array{customer_id: int, name: string}|null
     */
    private function suggestCustomer(string $description): ?array
    {
        $description = mb_strtolower(trim($description));
        if ($description === '') {
            return null;
        }
        $customers = $this->cachedCustomers ??= Customer::query()
            ->commercial()
            ->limit(200)
            ->get(['id', 'name', 'company_name']);

        foreach ($customers as $customer) {
            $name = mb_strtolower((string) ($customer->company_name ?: $customer->name));
            if ($name !== '' && str_contains($description, $name)) {
                return ['customer_id' => $customer->id, 'name' => $customer->company_name ?: $customer->name];
            }
        }

        return null;
    }
}<?php

declare(strict_types=1);

namespace App\Services\Wholesale;

use App\Enums\OrderStatus;
use App\Enums\QuotationStatus;
use App\Models\Customer;
use App\Models\Order;
use App\Models\Quotation;
use App\Models\WholesalePaymentNotice;
use Illuminate\Support\Facades\DB;

/**
 * Analytical service for wholesale operational metrics and early-warning intelligence.
 *
 * Generates actionable debt collection rankings, merchant reorder cadence outlooks,
 * quotation acceptance rates, credit increase candidates, and OCR invoice anomalies.
 */
final class WholesaleInsights
{
    /**
     * Ranks overdue credit orders by debt exposure and generates draft Arabic reminders.
     *
     * @return list<array<string, mixed>> Prioritized collection targets sorted by exposure score.
     */
    public function collectionPriorities(): array
    {
        return Order::query()
            ->with('customer:id,name,company_name')
            ->where('payment_method', 'credit')
            ->where('payment_status', 'unpaid')
            ->whereNotNull('due_at')
            ->where('due_at', '<', now())
            ->whereNotIn('status', [OrderStatus::Cancelled])
            ->orderBy('due_at')
            ->limit(30)
            ->get()
            ->map(function (Order $order): array {
                $days = (int) $order->due_at?->diffInDays(now());
                $name = $order->customer?->company_name ?: $order->customer?->name;

                return [
                    'customer' => $name,
                    'order_number' => $order->order_number,
                    'amount' => (string) $order->grand_total,
                    'days_late' => $days,
                    // Debt exposure index: weights outstanding value by days overdue to prioritize large old balances.
                    'score' => round((float) $order->grand_total * max(1, $days), 2),
                    'draft' => "يا {$name}، طلب {$order->order_number} متأخر {$days} يوم. نأكد موعد السداد؟",
                ];
            })
            ->sortByDesc('score')
            ->values()
            ->all();
    }

    /**
     * Identifies wholesale merchants whose elapsed time since last purchase exceeds their historical ordering cadence.
     *
     * @return list<array<string, mixed>> List of merchants overdue for restocking.
     */
    public function reorderOutlook(): array
    {
        // Require at least two past non-cancelled orders to establish a statistically meaningful cadence.
        $rows = DB::table('orders')
            ->selectRaw('customer_id, count(*) as orders_count, max(created_at) as last_order, min(created_at) as first_order')
            ->whereNotNull('customer_id')
            ->whereNotIn('status', ['cancelled', 'draft'])
            ->groupBy('customer_id')
            ->havingRaw('count(*) >= 2')
            ->limit(100)
            ->get();
        $out = [];
        foreach ($rows as $row) {
            $span = max(1, (int) now()->parse($row->first_order)->diffInDays(now()->parse($row->last_order)));
            // Calculate mean interval across order gaps (n orders yield n - 1 intervals).
            $average = $span / max(1, ((int) $row->orders_count) - 1);
            $since = (int) now()->parse($row->last_order)->diffInDays(now());
            if ($since < $average) {
                continue;
            }
            $customer = Customer::query()->find($row->customer_id);
            $out[] = [
                'customer_id' => (int) $row->customer_id,
                'customer' => $customer?->company_name ?: $customer?->name,
                'average_days' => round($average, 1),
                'days_since_last' => $since,
            ];
        }

        return array_slice($out, 0, 20);
    }

    /**
     * Computes conversion percentage of closed quotations across final states (accepted, rejected, expired).
     *
     * @return array<string, mixed> Aggregated counts and acceptance rate percentage.
     */
    public function quoteAcceptance(): array
    {
        $counts = Quotation::query()
            ->selectRaw('status, count(*) as c')
            ->groupBy('status')
            ->pluck('c', 'status');
        $accepted = (int) ($counts[QuotationStatus::Accepted->value] ?? 0);
        // Exclude pending/draft quotes from denominator so in-flight negotiations do not artificially depress rate.
        $closed = $accepted
            + (int) ($counts[QuotationStatus::Rejected->value] ?? 0)
            + (int) ($counts[QuotationStatus::Expired->value] ?? 0);

        return [
            'accepted' => $accepted,
            'closed' => $closed,
            'acceptance_rate' => $closed === 0 ? null : round(($accepted / $closed) * 100, 1),
        ];
    }

    /**
     * Highlights reliable merchants operating near their credit ceiling without any overdue invoices.
     *
     * @return list<array<string, mixed>> Eligible merchants recommended for staff credit review.
     */
    public function creditSuggestions(): array
    {
        $out = [];
        $customers = Customer::query()
            ->commercial()
            ->where('status', 'approved')
            ->where('credit_limit', '>', 0)
            ->limit(100)
            ->get();

        if ($customers->isEmpty()) {
            return [];
        }

        $customerIds = $customers->pluck('id')->all();

        // Disqualify merchants with any unpaid orders past due_at, regardless of total utilization.
        $overdueCustomerIds = Order::query()
            ->whereIn('customer_id', $customerIds)
            ->where('payment_status', 'unpaid')
            ->whereNotNull('due_at')
            ->where('due_at', '<', now())
            ->pluck('customer_id')
            ->flip()
            ->all();

        $usedByCustomer = Order::query()
            ->whereIn('customer_id', $customerIds)
            ->where('payment_method', 'credit')
            ->where('payment_status', 'unpaid')
            ->groupBy('customer_id')
            ->selectRaw('customer_id, SUM(grand_total) as total_used')
            ->pluck('total_used', 'customer_id')
            ->all();

        foreach ($customers as $customer) {
            if (isset($overdueCustomerIds[$customer->id])) {
                continue;
            }
            $used = (float) ($usedByCustomer[$customer->id] ?? 0.0);
            $limit = (float) $customer->credit_limit;
            // Target merchants with at least 90% credit utilization to proactively prevent order checkout blockages.
            if ($limit <= 0 || ($used / $limit) < 0.9) {
                continue;
            }
            $out[] = [
                'customer_id' => $customer->id,
                'customer' => $customer->company_name ?: $customer->name,
                'used_percent' => round(($used / $limit) * 100, 1),
                'suggestion' => 'العميل يسدد في الميعاد واستخدم أغلب الحد. مراجعة رفع الحد قرار موظف.',
            ];
        }

        return $out;
    }

    /**
     * Flags discrepancies between declared payment notice amounts and vision OCR extractions.
     *
     * @return list<array<string, mixed>> List of flagged payment notices exceeding the 1-cent variance threshold.
     */
    public function anomalies(): array
    {
        $out = [];
        $notices = WholesalePaymentNotice::query()->whereNotNull('ocr_payload')->limit(100)->get();
        foreach ($notices as $notice) {
            $read = $notice->ocr_payload['amount'] ?? null;
            if (! is_string($read) || $read === '') {
                continue;
            }
            // Flag any mismatch >= 0.01 EGP between the merchant claim and bank slip OCR for manual review.
            if (abs((float) $read - (float) $notice->amount) >= 0.01) {
                $out[] = [
                    'notice_number' => $notice->notice_number,
                    'kind' => 'amount_gap',
                    'stated' => (string) $notice->amount,
                    'read' => $read,
                ];
            }
        }

        return $out;
    }
}<?php

declare(strict_types=1);

namespace App\Services;

use App\Enums\PriceListType;
use App\Exceptions\BusinessException;
use App\Jobs\RefreshCatalogRetailPrices;
use App\Models\PriceList;
use App\Models\PriceListItem;
use App\Models\ProductVariant;
use App\Models\User;
use Carbon\Carbon;
use DateTimeInterface;
use Illuminate\Auth\Access\AuthorizationException;
use Illuminate\Contracts\Pagination\LengthAwarePaginator;
use Illuminate\Database\Eloquent\ModelNotFoundException;
use Illuminate\Http\UploadedFile;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Log;
use Illuminate\Support\Facades\Validator;
use Symfony\Component\HttpFoundation\StreamedResponse;

/**
 * Manages price list entities, tiered volume items, and CSV bulk import/export.
 *
 * Core price resolution logic resides in PricingService.
 */
class PriceListService
{
    /**
     * Paginates price lists with branch-level scoping and optional filters.
     *
     * @param  array<string, mixed>  $filters
     */
    public function paginate(array $filters, ?User $user = null): LengthAwarePaginator
    {
        return PriceList::query()
            ->with(['customer', 'customerGroup', 'branch'])
            ->withCount('items')
            ->when($this->restrictedBranch($user) !== null, fn ($q) => $q->where('branch_id', $this->restrictedBranch($user)))
            ->when($filters['type'] ?? null, fn ($q, $v) => $q->where('type', $v))
            ->when($filters['customer_id'] ?? null, fn ($q, $v) => $q->where('customer_id', $v))
            ->when($filters['customer_group_id'] ?? null, fn ($q, $v) => $q->where('customer_group_id', $v))
            ->when($filters['branch_id'] ?? null, fn ($q, $v) => $q->where('branch_id', $v))
            ->when(array_key_exists('is_active', $filters) && $filters['is_active'] !== null, fn ($q) => $q->where('is_active', $filters['is_active']))
            ->when($filters['search'] ?? null, fn ($q, $v) => $q->whereLike('name', SearchTerm::pattern($v), caseSensitive: false))
            ->orderByDesc('priority')
            ->orderByDesc('id')
            ->paginate($filters['per_page'] ?? 15);
    }

    /**
     * Retrieves a single price list by ID ensuring branch authorization.
     */
    public function find(int $id, ?User $user = null): PriceList
    {
        return PriceList::query()
            ->with(['customer', 'customerGroup', 'branch'])
            ->withCount('items')
            ->when($this->restrictedBranch($user) !== null, fn ($q) => $q->where('branch_id', $this->restrictedBranch($user)))
            ->findOrFail($id);
    }

    /**
     * Creates a new price list with validated owner relationships and date ranges.
     *
     * @param  array<string, mixed>  $data
     */
    public function create(array $data, ?User $user = null): PriceList
    {
        $restricted = $this->restrictedBranch($user);
        if ($restricted !== null) {
            if (isset($data['branch_id']) && (int) $data['branch_id'] !== $restricted) {
                throw new AuthorizationException('لا تملك صلاحية إنشاء قوائم أسعار لفرع آخر.');
            }
            $data['branch_id'] = $restricted;
        }
        $data = $this->normalizeDates($data);
        $data = array_filter($data, fn ($value, $key) => $value !== null || ! in_array($key, ['currency', 'priority', 'is_active'], true), ARRAY_FILTER_USE_BOTH);
        $this->validateDates($data);
        $data = $this->withValidOwner($data);

        return PriceList::query()->create($data)->load(['customer', 'customerGroup', 'branch']);
    }

    /**
     * Updates an existing price list under an exclusive row lock to prevent branch transfer races.
     *
     * @param  array<string, mixed>  $data
     */
    public function update(PriceList $priceList, array $data, ?User $user = null): PriceList
    {
        $this->assertListAccess($user, $priceList);
        $restricted = $this->restrictedBranch($user);
        // Use array_key_exists so passing branch_id = null cannot bypass branch restriction checks.
        if ($restricted !== null && array_key_exists('branch_id', $data)
            && ($data['branch_id'] === null || (int) $data['branch_id'] !== $restricted)) {
            throw new AuthorizationException('لا تملك صلاحية نقل قائمة أسعار إلى فرع آخر.');
        }
        $data = $this->normalizeDates($data);

        return DB::transaction(function () use ($priceList, $data, $user): PriceList {
            $priceList = PriceList::query()->lockForUpdate()->findOrFail($priceList->id);
            // Re-verify branch access after acquiring row lock to protect against concurrent reassignments.
            $this->assertListAccess($user, $priceList);
            $this->validateDates($data, $priceList);
            $data = $this->withValidOwner($data, $priceList);
            $priceList->update($data);

            return $priceList->load(['customer', 'customerGroup', 'branch']);
        });
    }

    /**
     * Enforces polymorphic ownership rules based on the target price list type.
     */
    private function withValidOwner(array $data, ?PriceList $priceList = null): array
    {
        // Enforce owner linkage on final state: customer_specific requires customer, customer_group requires group.
        $type = $data['type'] ?? $priceList?->type;
        $typeValue = $type instanceof PriceListType ? $type->value : $type;

        if ($typeValue === PriceListType::CustomerSpecific->value) {
            $customerId = array_key_exists('customer_id', $data) ? $data['customer_id'] : $priceList?->customer_id;
            if ($customerId === null) {
                throw new BusinessException('قائمة الأسعار الخاصة بعميل تتطلب تحديد العميل.');
            }
            $data['customer_id'] = $customerId;
            $data['customer_group_id'] = null;
        } elseif ($typeValue === PriceListType::CustomerGroup->value) {
            $groupId = array_key_exists('customer_group_id', $data) ? $data['customer_group_id'] : $priceList?->customer_group_id;
            if ($groupId === null) {
                throw new BusinessException('قائمة أسعار المجموعة تتطلب تحديد مجموعة العملاء.');
            }
            $data['customer_group_id'] = $groupId;
            $data['customer_id'] = null;
        } else {
            $data['customer_id'] = null;
            $data['customer_group_id'] = null;
        }

        return $data;
    }

    /**
     * Deletes a price list under exclusive lock (cascades item deletion in database).
     */
    public function delete(PriceList $priceList, ?User $user = null): void
    {
        $this->assertListAccess($user, $priceList);

        DB::transaction(function () use ($priceList, $user): void {
            $locked = PriceList::query()->lockForUpdate()->findOrFail($priceList->id);
            $this->assertListAccess($user, $locked);
            $locked->delete();
        });
    }

    // ---------- Items ----------

    /**
     * Paginates tiered items belonging to a price list.
     *
     * @param  array<string, mixed>  $filters
     */
    public function paginateItems(PriceList $priceList, array $filters, ?User $user = null): LengthAwarePaginator
    {
        $this->assertListAccess($user, $priceList);

        return $priceList->items()
            ->with(['variant.product'])
            ->when($filters['product_variant_id'] ?? null, fn ($q, $v) => $q->where('product_variant_id', $v))
            ->orderBy('product_variant_id')
            ->orderBy('min_qty')
            ->orderBy('id')
            ->paginate($filters['per_page'] ?? 15);
    }

    /**
     * Adds a tiered pricing item ensuring no duplicate (variant_id, min_qty) tier exists in the list.
     *
     * @param  array<string, mixed>  $data
     */
    public function createItem(PriceList $priceList, array $data, ?User $user = null): PriceListItem
    {
        $this->assertListAccess($user, $priceList);
        $data = $this->normalizeDates($data);

        return DB::transaction(function () use ($priceList, $data, $user): PriceListItem {
            $priceList = PriceList::query()->lockForUpdate()->findOrFail($priceList->id);
            $this->assertListAccess($user, $priceList);
            $data['min_qty'] = $data['min_qty'] ?? 1;
            $this->validateDates($data);
            $this->assertNoDuplicateTier($priceList, (int) $data['product_variant_id'], (float) $data['min_qty']);

            return $priceList->items()->create($data)->load('variant.product');
        });
    }

    /**
     * Updates a tiered item under a lock on the parent price list and item row.
     *
     * @param  array<string, mixed>  $data
     */
    public function updateItem(PriceListItem $item, array $data, ?User $user = null): PriceListItem
    {
        $this->assertListAccess($user, $item->priceList);
        $data = $this->normalizeDates($data);

        return DB::transaction(function () use ($item, $data, $user): PriceListItem {
            $lockedList = PriceList::query()->lockForUpdate()->findOrFail($item->price_list_id);
            $this->assertListAccess($user, $lockedList);
            $item = PriceListItem::query()->lockForUpdate()->findOrFail($item->id);
            $this->validateDates($data, $item);
            if (isset($data['product_variant_id']) || isset($data['min_qty'])) {
                $this->assertNoDuplicateTier(
                    $item->priceList,
                    (int) ($data['product_variant_id'] ?? $item->product_variant_id),
                    (float) ($data['min_qty'] ?? $item->min_qty),
                    $item->id,
                );
            }

            $item->update($data);

            return $item->load('variant.product');
        });
    }

    /**
     * Deletes a price list item under row locks.
     */
    public function deleteItem(PriceListItem $item, ?User $user = null): void
    {
        $this->assertListAccess($user, $item->priceList);

        DB::transaction(function () use ($item, $user): void {
            $lockedList = PriceList::query()->lockForUpdate()->findOrFail($item->price_list_id);
            $this->assertListAccess($user, $lockedList);
            PriceListItem::query()->lockForUpdate()->findOrFail($item->id)->delete();
        });
    }

    public function applyPercentage(PriceList $priceList, float $percent, User $user): int
    {
        return DB::transaction(function () use ($priceList, $percent, $user): int {
            $locked = PriceList::query()->lockForUpdate()->findOrFail($priceList->id);
            $this->assertListAccess($user, $locked);

            $items = $locked->items();
            $factor = 1 + $percent / 100;
            $outOfRange = (clone $items)->whereRaw('round(price * ?::numeric, 4) > ?', [$factor, '99999999.9999'])->exists();
            if ($outOfRange) {
                throw new BusinessException('أحد الأسعار بعد التعديل يتجاوز الحد المسموح.');
            }

            $productIds = ProductVariant::query()->withTrashed()
                ->whereIn('id', (clone $items)->select('product_variant_id'))
                ->distinct()->pluck('product_id')->map(fn ($id) => (int) $id)->all();
            $updated = DB::update(
                'UPDATE price_list_items SET price = round(price * ?::numeric, 4), updated_at = ? WHERE price_list_id = ?',
                [$factor, now(), $locked->id],
            );
            if ($productIds !== []) {
                DB::afterCommit(static fn () => RefreshCatalogRetailPrices::dispatch($productIds));
            }

            return $updated;
        });
    }

    /**
     * Guards against duplicate variant tiers with identical minimum quantities in the same list.
     */
    private function assertNoDuplicateTier(PriceList $priceList, int $variantId, float $minQty, ?int $ignoreItemId = null): void
    {
        $exists = $priceList->items()
            ->where('product_variant_id', $variantId)
            ->where('min_qty', $minQty)
            ->when($ignoreItemId !== null, fn ($q) => $q->whereKeyNot($ignoreItemId))
            ->exists();

        if ($exists) {
            throw new BusinessException('توجد شريحة بنفس المتغير وحد الكمية داخل هذه القائمة بالفعل.');
        }
    }

    // ---------- CSV ----------

    /**
     * Streams price list items as a CSV file matching the import format.
     */
    public function exportCsv(PriceList $priceList, ?User $user = null): StreamedResponse
    {
        $this->assertListAccess($user, $priceList);

        return response()->streamDownload(function () use ($priceList): void {
            $handle = fopen('php://output', 'w');
            try {
                // Disable PHP's default escape character to prevent trailing backslashes breaking CSV syntax.
                fputcsv($handle, ['sku', 'variant_id', 'product_name', 'min_qty', 'price', 'starts_at', 'ends_at'], escape: '');

                $priceList->items()
                    ->with(['variant.product' => fn ($query) => $query->withTrashed()])
                    ->chunkById(500, function ($items) use ($handle): void {
                        foreach ($items as $item) {
                            fputcsv($handle, [
                                $this->csvText($item->variant?->sku ?? ''),
                                $item->product_variant_id,
                                $this->csvText($item->variant?->product?->name_ar ?? ''),
                                $item->min_qty,
                                $item->price,
                                $item->starts_at?->toIso8601String(),
                                $item->ends_at?->toIso8601String(),
                            ], escape: '');
                        }
                    });

            } catch (\Throwable $e) {
                // Log streaming errors; browser receives aborted stream with partial data.
                Log::error('فشل تصدير قائمة أسعار أثناء البث', [
                    'price_list_id' => $priceList->id,
                    'exception' => $e->getMessage(),
                ]);

                throw $e;
            } finally {
                fclose($handle);
            }
        }, 'price-list-'.$priceList->id.'.csv', [
            'Content-Type' => 'text/csv; charset=UTF-8',
            'X-Row-Count' => (string) $priceList->items()->count(),
        ]);
    }

    /**
     * Sanitizes CSV text cells against CSV formula injection attacks (=, +, -, @).
     */
    private function csvText(string $value): string
    {
        return preg_match('/^[\s]*[=+@\-\t\r\n]/u', $value) ? "'".$value : $value;
    }

    /**
     * Imports CSV rows into price list items using batched upserts.
     *
     * @return array{created: int, updated: int, skipped: int, errors: list<array{line: int, message: string}>, diff?: list<array>, row_count?: int}
     */
    public function importCsv(PriceList $priceList, UploadedFile $file, ?User $user = null, bool $dryRun = false): array
    {
        $this->assertListAccess($user, $priceList);
        $handle = fopen($file->getRealPath(), 'r');
        if ($handle === false) {
            throw new BusinessException('تعذرت قراءة ملف الاستيراد.');
        }
        try {
            $header = fgetcsv($handle, escape: '');
            if ($header === false) {
                throw new BusinessException('ملف الاستيراد فارغ.');
            }
            $header[0] = preg_replace('/^\xEF\xBB\xBF/', '', (string) $header[0]);
            $columns = array_map(fn ($h) => strtolower(trim((string) $h)), $header);
            $index = array_flip($columns);
            if (count($index) !== count($columns) || ! isset($index['price']) || (! isset($index['variant_id']) && ! isset($index['sku']))) {
                throw new BusinessException('يجب أن يحتوي الملف على price وsku أو variant_id، دون أعمدة مكررة.');
            }
            $rows = [];
            $line = 1;
            while (($row = fgetcsv($handle, escape: '')) !== false) {
                $line++;
                if ($line > 10000) {
                    throw new BusinessException('عدد أسطر الملف يتجاوز الحد المسموح.');
                }
                if ($row === [null] || trim(implode('', array_map('strval', $row))) === '') {
                    continue;
                }
                if (count($rows) >= 2000) {
                    throw new BusinessException('الحد الأقصى للاستيراد المتزامن 2000 صف؛ قسّم الملف إلى أجزاء أصغر.');
                }
                $get = fn (string $key) => isset($index[$key]) ? trim((string) ($row[$index[$key]] ?? '')) : '';
                $rows[] = ['line' => $line, 'variant_id' => $get('variant_id'), 'sku' => $get('sku'),
                    'price' => $get('price'), 'min_qty' => $get('min_qty') === '' ? '1' : $get('min_qty'),
                    'starts_at' => $get('starts_at') === '' ? null : $get('starts_at'),
                    'ends_at' => $get('ends_at') === '' ? null : $get('ends_at')];
            }
        } finally {
            fclose($handle);
        }

        $ids = array_values(array_filter(array_map(fn ($row) => filter_var($row['variant_id'], FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]), $rows)));
        $skus = [];
        $upperSkus = [];
        foreach ($rows as $row) {
            // Match SKUs case-insensitively to prevent import failures from casing discrepancies.
            $skus[] = $row['sku'];
            $skus[] = $this->unescapeCsvText($row['sku']);
            $skus[] = strtoupper($row['sku']);
            $skus[] = strtoupper($this->unescapeCsvText($row['sku']));
            $upperSkus[] = strtoupper($this->unescapeCsvText($row['sku']));
        }
        $upperSkus = array_values(array_unique(array_filter($upperSkus, fn ($sku) => $sku !== '')));
        $variants = ProductVariant::query()->where('is_active', true)
            ->where(fn ($q) => $q->whereIn('id', $ids)->orWhereIn('sku', array_unique($skus))
                ->when($upperSkus !== [], fn ($q) => $q->orWhereIn(DB::raw('UPPER(sku)'), $upperSkus)))->get();
        $byId = $variants->keyBy('id');
        $bySku = $variants->keyBy('sku');
        $bySkuUpper = $variants->groupBy(fn (ProductVariant $variant) => strtoupper($variant->sku));
        $report = ['created' => 0, 'updated' => 0, 'skipped' => 0, 'errors' => []];
        if ($dryRun) {
            $report['row_count'] = count($rows);
        }
        $valid = [];
        foreach ($rows as $row) {
            try {
                $normalizedSku = $this->unescapeCsvText($row['sku']);
                $foldedMatches = $bySkuUpper->get(strtoupper($normalizedSku));
                $variant = $row['variant_id'] !== ''
                    ? $byId->get(filter_var($row['variant_id'], FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]) ?: 0)
                    : ($bySku->get($row['sku']) ?? $bySku->get($normalizedSku)
                        ?? ($foldedMatches?->count() === 1 ? $foldedMatches->first() : null));
                if ($variant === null) {
                    throw new BusinessException('الصنف غير موجود أو يوجد تعارض بين sku وvariant_id.');
                }
                if ($row['sku'] !== '') {
                    $rowSku = strtoupper($this->unescapeCsvText($row['sku']));
                    $matches = $rowSku === strtoupper($variant->sku) || $rowSku === strtoupper($this->csvText($variant->sku));
                    if (! $matches) {
                        throw new BusinessException('الصنف غير موجود أو يوجد تعارض بين sku وvariant_id.');
                    }
                }
                $validator = Validator::make($row, [
                    'price' => ['required', 'numeric', 'decimal:0,4', 'min:0', 'max:99999999.9999'],
                    'min_qty' => ['required', 'numeric', 'decimal:0,4', 'gt:0', 'max:99999999.9999'],
                    'starts_at' => ['nullable', 'date'], 'ends_at' => ['nullable', 'date'],
                ]);
                if ($validator->fails()) {
                    throw new BusinessException($validator->errors()->first());
                }
                $row['starts_at'] = $this->parseDate($row['starts_at'] ?? '');
                $row['ends_at'] = $this->parseDate($row['ends_at'] ?? '');
                $this->validateDates($row);
                $valid[] = [...$row, 'product_variant_id' => $variant->id, 'resolved_sku' => $variant->sku];
            } catch (BusinessException $exception) {
                $report['skipped']++;
                $report['errors'][] = ['line' => $row['line'], 'message' => $exception->getMessage()];
            }
        }
        // De-duplicate same (variant, min_qty) lines in CSV payload with last-write-wins semantics.
        $deduped = [];
        foreach ($valid as $row) {
            $deduped[$row['product_variant_id'].':'.number_format((float) $row['min_qty'], 4, '.', '')] = $row;
        }
        $valid = array_values($deduped);

        DB::transaction(function () use ($valid, $priceList, $user, $dryRun, &$report): void {
            $locked = PriceList::query()
                ->when(! $dryRun, fn ($query) => $query->lockForUpdate())
                ->findOrFail($priceList->id);
            $this->assertListAccess($user, $locked);

            // Batch existing lookup and upsert to avoid thousands of per-row queries while holding row lock.
            $existing = PriceListItem::query()
                ->where('price_list_id', $priceList->id)
                ->whereIn('product_variant_id', array_column($valid, 'product_variant_id'))
                ->get(['product_variant_id', 'min_qty', 'price'])
                ->keyBy(fn ($item) => $item->product_variant_id.':'.number_format((float) $item->min_qty, 4, '.', ''));

            $rows = [];
            if ($dryRun) {
                $report['diff'] = [];
            }
            $now = now();
            foreach ($valid as $row) {
                $key = $row['product_variant_id'].':'.number_format((float) $row['min_qty'], 4, '.', '');
                $existing->has($key) ? $report['updated']++ : $report['created']++;
                if ($dryRun) {
                    $report['diff'][] = [
                        'line' => $row['line'],
                        'variant_id' => $row['product_variant_id'],
                        'sku' => $row['resolved_sku'],
                        'min_qty' => $row['min_qty'],
                        'old_price' => $existing->get($key)?->price,
                        'new_price' => $row['price'],
                        'starts_at' => $row['starts_at'],
                        'ends_at' => $row['ends_at'],
                    ];

                    continue;
                }
                $rows[] = [
                    'price_list_id' => $priceList->id,
                    'product_variant_id' => $row['product_variant_id'],
                    'min_qty' => $row['min_qty'],
                    'price' => $row['price'],
                    'starts_at' => $row['starts_at'],
                    'ends_at' => $row['ends_at'],
                    'created_at' => $now,
                    'updated_at' => $now,
                ];
            }

            if ($rows === []) {
                return;
            }
            foreach (array_chunk($rows, 500) as $chunk) {
                PriceListItem::query()->upsert($chunk, ['price_list_id', 'product_variant_id', 'min_qty'], ['price', 'starts_at', 'ends_at', 'updated_at']);
            }

            // Query-builder upsert fires no Eloquent events, so the catalog
            // snapshot observer never sees these writes. Refresh the affected
            // products explicitly, mirroring the AI upsert path.
            $productIds = ProductVariant::query()
                ->whereIn('id', array_column($valid, 'product_variant_id'))
                ->distinct()
                ->pluck('product_id')
                ->all();
            if ($productIds !== []) {
                $ids = array_values(array_unique(array_map('intval', $productIds)));
                DB::afterCommit(static function () use ($ids): void {
                    RefreshCatalogRetailPrices::dispatch($ids);
                });
            }
        });

        return $report;
    }

    /**
     * Strips leading single quote added for CSV formula neutralization.
     */
    private function unescapeCsvText(string $value): string
    {
        return str_starts_with($value, "'") && $this->csvText(substr($value, 1)) === $value ? substr($value, 1) : $value;
    }

    /**
     * Parses dates strictly into UTC (Y-m-d H:i:s) assuming business timezone for un-offset inputs.
     */
    private function parseDate(string $value): ?string
    {
        $value = trim($value);
        if ($value === '') {
            return null;
        }

        $businessTz = (string) config('app.business_timezone', 'Africa/Cairo');
        $value = preg_replace('/Z$/', '+00:00', $value);
        $value = preg_replace_callback('/\.(\d{1,6})([+-]\d{2}:\d{2})$/', fn ($matches) => '.'.str_pad($matches[1], 6, '0').$matches[2], $value);
        foreach (['Y-m-d\TH:i:s.uP', 'Y-m-d\TH:i:sP', 'Y-m-d H:i:s', 'Y-m-d'] as $format) {
            try {
                $parsed = Carbon::rawCreateFromFormat('!'.$format, $value, $businessTz);
            } catch (\Throwable) {
                $parsed = null;
            }
            if ($parsed !== null && $parsed->format($format) === $value) {
                return $parsed->utc()->format('Y-m-d H:i:s');
            }
        }

        throw new BusinessException("تاريخ غير صالح: {$value} — الصيغ المقبولة: Y-m-d أو Y-m-d H:i:s أو ISO-8601 مع إزاحة.");
    }

    /**
     * Normalizes starts_at and ends_at input fields to UTC before storage.
     */
    private function normalizeDates(array $data): array
    {
        foreach (['starts_at', 'ends_at'] as $field) {
            if (! array_key_exists($field, $data) || $data[$field] === null) {
                continue;
            }
            $data[$field] = $data[$field] instanceof DateTimeInterface
                ? Carbon::instance($data[$field])->utc()->format('Y-m-d H:i:s')
                : $this->parseDate((string) $data[$field]);
        }

        return $data;
    }

    /**
     * Resolves the branch ID restricted for a scoped admin user, or null if unrestricted.
     */
    private function restrictedBranch(?User $user): ?int
    {
        return $user === null ? null : app(BranchAccess::class)->restrictedBranch($user);
    }

    /**
     * Asserts user access to a price list, throwing 404 for out-of-scope lists to avoid probing.
     */
    public function assertListAccess(?User $user, PriceList $priceList): void
    {
        $restricted = $this->restrictedBranch($user);
        if ($restricted !== null && $priceList->branch_id !== $restricted) {
            // Throw 404 instead of 403 to prevent probing existence of other branches' price lists.
            throw new ModelNotFoundException('قائمة الأسعار غير موجودة.');
        }
    }

    /**
     * Asserts that price list starts_at does not exceed ends_at.
     */
    private function validateDates(array $data, PriceList|PriceListItem|null $model = null): void
    {
        $start = array_key_exists('starts_at', $data) ? $data['starts_at'] : $model?->starts_at;
        $end = array_key_exists('ends_at', $data) ? $data['ends_at'] : $model?->ends_at;
        if ($start !== null && $end !== null && Carbon::parse($end)->lt(Carbon::parse($start))) {
            throw new BusinessException('نهاية صلاحية السعر يجب ألا تسبق بدايتها.');
        }
    }
}<?php

declare(strict_types=1);

namespace Database\Seeders;

use App\Enums\CustomerStatus;
use App\Enums\CustomerType;
use App\Enums\OrderStatus;
use App\Enums\SalesChannel;
use App\Models\Branch;
use App\Models\Customer;
use App\Models\CustomerDocument;
use App\Models\CustomerGroup;
use App\Models\Order;
use App\Models\PriceList;
use App\Models\Product;
use App\Models\StockLevel;
use Illuminate\Database\Seeder;

/**
 * Wholesale portal demo dataset for local and testing environments.
 * Seeds approved, pending, and rejected merchants, tiered price lists,
 * published wholesale catalog items with stock, and representative orders.
 */
class WholesaleDemoSeeder extends Seeder
{
    private string $password;

    public function run(): void
    {
        // Restrict execution to local and testing environments.
        if (! app()->environment(['local', 'testing'])) {
            throw new \LogicException('Wholesale demo data is only available locally.');
        }
        $password = env('WHOLESALE_DEMO_PASSWORD');
        if (! is_string($password) || strlen($password) < 12) {
            throw new \LogicException('Set WHOLESALE_DEMO_PASSWORD to at least 12 characters.');
        }
        $this->password = $password;

        $branch = Branch::query()->where('is_active', true)->first()
            ?? Branch::factory()->create(['is_active' => true]);

        $group = CustomerGroup::firstOrCreate(
            ['code' => 'WHOLESALE-A'],
            ['name' => 'تجار الجملة — فئة أ', 'discount_percentage' => 0, 'is_active' => true],
        );

        $approved = $this->trader([
            'email' => 'wholesale.demo@alfarid.test',
            'status' => CustomerStatus::Approved,
            'credit_limit' => 250000,
            'approved_at' => now(),
        ], $group->id);
        foreach (['commercial_register', 'tax_card', 'national_id'] as $type) {
            CustomerDocument::create([
                'customer_id' => $approved->id,
                'document_type' => $type,
                'file_path' => "wholesale-demo/{$type}.pdf",
                'original_name' => "{$type}.pdf",
                'mime_type' => 'application/pdf',
                'status' => 'verified',
            ]);
        }

        $this->trader([
            'email' => 'wholesale.pending@alfarid.test',
            'status' => CustomerStatus::Pending,
        ], $group->id);

        $this->trader([
            'email' => 'wholesale.rejected@alfarid.test',
            'status' => CustomerStatus::Rejected,
            'rejection_reason' => 'المستندات غير مكتملة — أعد رفع السجل التجاري.',
        ], $group->id);

        // SalesChannel::Both permits catalog listing on wholesale while allowing store cart testing.
        $products = Product::factory()->count(4)->published()->create([
            'sales_channel' => SalesChannel::Both,
        ]);

        $variants = collect();
        foreach ($products as $product) {
            $variant = $product->variants()->first()
                ?? \App\Models\ProductVariant::factory()->create(['product_id' => $product->id]);
            $variant->update(['retail_price' => 1000, 'wholesale_price' => 900, 'is_active' => true]);
            StockLevel::forceCreate([
                'branch_id' => $branch->id,
                'product_variant_id' => $variant->id,
                'on_hand' => 500,
                'reserved' => 0,
            ]);
            $variants->push($variant->fresh());
        }

        $list = PriceList::create([
            'name' => 'قائمة فئة أ — تجريبية',
            'type' => 'customer_group',
            'customer_group_id' => $group->id,
            'currency' => 'EGP',
            'priority' => 1,
            'is_active' => true,
        ]);
        foreach ($variants as $variant) {
            foreach ([[1, 900], [24, 860], [60, 820]] as [$minQty, $price]) {
                $list->items()->create([
                    'product_variant_id' => $variant->id,
                    'min_qty' => $minQty,
                    'price' => $price,
                ]);
            }
        }

        $this->order($approved, $variants[0], OrderStatus::Pending, 'credit', 'unpaid');
        $this->order($approved, $variants[1], OrderStatus::Processing, 'credit', 'unpaid');
        $this->order($approved, $variants[0], OrderStatus::Delivered, 'credit', 'unpaid');
        $this->order($approved, $variants[1], OrderStatus::Delivered, 'bank_transfer', 'paid');
        $this->order($approved, $variants[2], OrderStatus::Cancelled, 'credit', 'unpaid');
    }

    private function trader(array $attributes, int $groupId): Customer
    {
        $merged = array_merge([
            'name' => 'تاجر تجريبي',
            'phone' => '010'.fake()->numerify('########'),
            'password' => $this->password,
            'type' => CustomerType::Wholesale,
            'company_name' => 'شركة الاختبار للتجارة',
            'tax_number' => fake()->unique()->numerify('#########'),
            'commercial_register' => fake()->unique()->numerify('######'),
            'customer_group_id' => $groupId,
        ], $attributes);

        $customer = Customer::firstOrNew(['email' => $attributes['email']]);
        $customer->forceFill($merged)->save();

        return $customer;
    }

    private function order(Customer $customer, $variant, OrderStatus $status, string $method, string $pay): Order
    {
        $order = Order::create([
            'order_number' => 'WS-'.fake()->unique()->numerify('######'),
            'channel' => 'wholesale',
            'customer_id' => $customer->id,
            'guest_name' => $customer->name,
            'guest_phone' => $customer->phone,
            'status' => $status,
            'payment_method' => $method,
            'payment_status' => $pay,
            'subtotal' => 5000,
            'discount_amount' => 0,
            'shipping_cost' => 0,
            'tax_amount' => 0,
            'grand_total' => 5000,
        ]);
        $order->items()->create([
            'product_variant_id' => $variant->id,
            'product_name_snapshot' => 'منتج تجريبي',
            'sku_snapshot' => $variant->sku,
            'qty' => 5,
            'unit_price' => 1000,
            'discount_amount' => 0,
            'line_total' => 5000,
        ]);
        $order->statusHistories()->create([
            'from_status' => null,
            'to_status' => $status,
            'changed_by_type' => Customer::class,
            'changed_by_id' => $customer->id,
        ]);

        return $order;
    }
}import React, { useState, useEffect, useRef } from 'react';
import { useApp } from './context';
import { wholesaleEndpoints, accountEndpoints } from '@alfarid/api-client';
import { useApi } from './data/useApi';
import { DataBoundary } from './data/DataBoundary';
import { apiError, saveBlob, pageMeta, num, calendarDay, today, allPages } from './data/helpers';
import { mapOrder, mapInvoice, mapStatement, mapNotice, mapWalletTx, mapNotif } from './data/mappers';
import { ORDER_STATUS, PAY_METHOD, PAY_STATUS, NOTICE_STATUS, NOTICE_METHOD } from './data/constants';
import { fmt, Money } from './data/format';
import {
  Badge, PageHead, Crumb, Panel, Empty,
  Async, Pager, Field, Modal, Banner, Seg
} from './ui-primitives';

/* Screens 18–21, 23–25: invoices, statement, payment notices, wallet, notifications, account. */

/* ---------- 18. Invoices ---------- */
export const Invoices = () => {
  const { go, toast, account } = useApp();
  const [f, setF] = useState('all');
  const [page, setPage] = useState(1);
  const [open, setOpen] = useState(null);
  const [dl, setDl] = useState(null);
  const [unpaidTotal, setUnpaidTotal] = useState(0);

  const api = useApi((signal) => wholesaleEndpoints
    .invoices({ payment_status: f === 'all' ? undefined : f, page }, signal)
    .then((r) => ({ items: (r.data || []).map(mapInvoice), meta: pageMeta(r.meta) })), [f, page]);

  const list = api.data?.items || [];
  const meta = api.data?.meta || { page: 1, pages: 1, total: 0, per: 15 };
  const detailApi = useApi((signal) => wholesaleEndpoints.order(open.id, signal).then(mapOrder), [open?.id], !!open);
  const openOrder = detailApi.state === 'ready' ? detailApi.data : null;

  useEffect(() => {
    wholesaleEndpoints.outstanding().then((d) => setUnpaidTotal(num(d.outstanding_balance) ?? 0)).catch(() => {});
  }, []);

  const openInvoice = (o) => setOpen(o);

  const pdf = async (o) => {
    setDl(o.id);
    try {
      await saveBlob(wholesaleEndpoints.invoicePdf(o.id), `invoice-${o.number}.pdf`);
    } catch (e) {
      toast(apiError(e).message);
    } finally {
      setDl(null);
    }
  };

  return (
    <>
      <PageHead en="Invoices" ar="رقم الفاتورة هو نفس رقم الطلب" />
      <section className="panel">
        <div className="toolbar"><Seg value={f} onChange={(v) => { setF(v); setPage(1); }} options={[{ value: 'all', label: 'الكل' }, { value: 'unpaid', label: 'غير مدفوع' }, { value: 'paid', label: 'مدفوع' }]} />
          <span className="soft small">غير مدفوع: <Money v={unpaidTotal} strong /></span></div>
        <DataBoundary api={api}>
          <Async rows={5} cols={7} isEmpty={!list.length} empty={<Empty icon="fa-file-invoice" title="لا توجد فواتير" />}>
            <div className="tbl-wrap"><table className="tbl">
              <thead><tr><th>رقم الفاتورة</th><th>التاريخ</th><th>حالة الطلب</th><th>الدفع</th><th>السداد</th><th>قبل الخصم</th><th>الخصم</th><th>الشحن</th><th>الضريبة</th><th className="t-end">الإجمالي</th><th></th></tr></thead>
              <tbody>{list.map((o) => (
                <tr key={o.id} className="is-click" onClick={() => openInvoice(o)}>
                  <td className="strong num">{o.number}</td><td className="num">{o.date}</td><td><Badge map={ORDER_STATUS} k={o.status} /></td><td>{PAY_METHOD[o.method]}</td><td><Badge map={PAY_STATUS} k={o.pay} /></td>
                  <td className="num">{fmt(o.subtotal)}</td><td className="num" style={{ color: o.discount ? 'var(--teal)' : null }}>{o.discount ? fmt(o.discount) : '—'}</td><td className="num">{fmt(o.shipping)}</td><td className="num">{fmt(o.tax)}</td>
                  <td className="t-end strong num">{fmt(o.total)}</td>
                  <td onClick={(e) => e.stopPropagation()}><div className="row-actions"><button className="btn-pill sm" onClick={() => pdf(o)} disabled={dl === o.id}>{dl === o.id ? <span className="spin" /> : <i className="fa-regular fa-file-pdf" />} PDF</button></div></td>
                </tr>))}</tbody>
            </table></div>
            <Pager page={meta.page} pages={meta.pages} total={meta.total} per={meta.per} onPage={setPage} />
          </Async>
        </DataBoundary>
      </section>
      {open && (
        <Modal wide title={<>فاتورة <span className="num">{open.number}</span></>} onClose={() => setOpen(null)}
          foot={<><button className="btn-pill" onClick={() => go('order', open.id)}>فتح الطلب المرتبط</button><button className="btn-pill is-dark" disabled={dl === open.id} onClick={() => pdf(open)}>{dl === open.id ? <span className="spin" /> : <i className="fa-regular fa-file-pdf" />} تنزيل PDF</button></>}>
          <div className="inv-head">
            <div><div className="wp-logo" style={{ fontSize: 20 }}>SOPHIE</div><div className="soft small">فاتورة ضريبية مبسطة</div></div>
            <dl className="kv" style={{ gridTemplateColumns: '90px auto' }}><dt>التاريخ</dt><dd className="num">{open.date}</dd><dt>العميل</dt><dd>{account?.company}</dd><dt>السداد</dt><dd><Badge map={PAY_STATUS} k={open.pay} /></dd></dl>
          </div>
          <DataBoundary api={detailApi}><Async rows={3} cols={4}>
          <table className="tbl mt-16"><thead><tr><th>المنتج</th><th>الكمية</th><th>السعر</th><th className="t-end">الإجمالي</th></tr></thead>
            <tbody>{(openOrder?.items || []).map((it) => <tr key={it.id || it.sku}><td><div className="strong">{it.name}</div><div className="sku">{it.sku}</div></td><td className="num">{it.qty}</td><td className="num">{fmt(it.unit)}</td><td className="t-end num strong">{fmt(it.line_total)}</td></tr>)}</tbody></table>
          </Async></DataBoundary>
          <div style={{ maxWidth: 320, marginInlineStart: 'auto' }} className="mt-16">
            <div className="sum-row"><span>المنتجات قبل الخصم</span><strong className="num">{fmt(openOrder?.subtotal ?? open.subtotal)}</strong></div>
            <div className="sum-row is-neg"><span>الخصم</span><strong className="num">{(openOrder?.discount ?? open.discount) ? '− ' + fmt(openOrder?.discount ?? open.discount) : '—'}</strong></div>
            <div className="sum-row"><span>الشحن</span><strong className="num">{fmt(openOrder?.shipping ?? open.shipping)}</strong></div>
            <div className="sum-row"><span>الضريبة</span><strong className="num">{fmt(openOrder?.tax ?? open.tax)}</strong></div>
            <div className="sum-total"><span>الإجمالي</span><strong className="num">{fmt(openOrder?.total ?? open.total)}</strong></div>
          </div>
        </Modal>
      )}
    </>
  );
};

/* ---------- 19. Statement ---------- */
const firstOfMonth = () => { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-01`; };

export const Statement = () => {
  const { go, account } = useApp();
  const [from, setFrom] = useState(firstOfMonth());
  const [to, setTo] = useState(today());
  const [chip, setChip] = useState(0);
  const bad = from > to;

  const api = useApi((signal) => bad
    ? Promise.resolve(null)
    : wholesaleEndpoints.statement({ from, to }, signal).then(mapStatement), [from, to, bad]);

  const entries = api.data?.entries || [];

  const outApi = useApi((signal) => wholesaleEndpoints
    .invoices({ payment_status: 'unpaid', page: 1 }, signal)
    .then((r) => (r.data || []).map(mapInvoice)), []);
  const out = outApi.data || [];
  const debtApi = useApi(() => wholesaleEndpoints.outstanding().then((d) => num(d.outstanding_balance) ?? 0), []);
  const debt = debtApi.data ?? 0;

  const setRange = (i) => {
    setChip(i);
    const now = new Date();
    if (i === 0) { setFrom(firstOfMonth()); setTo(today()); }
    else if (i === 1) { const d = new Date(now.getFullYear(), now.getMonth() - 2, 1); setFrom(calendarDay(d)); setTo(today()); }
    else { setFrom(`${now.getFullYear()}-01-01`); setTo(today()); }
  };

  return (
    <>
      <PageHead en="Statement" ar="كشف الحساب والمديونية">
        <button className="btn-pill is-dark" onClick={() => go('noticeNew')}><i className="fa-solid fa-money-check-dollar" /> تسجيل إشعار سداد</button>
      </PageHead>
      <div className="kpis" style={{ gridTemplateColumns: 'repeat(4, minmax(0,1fr))' }}>
        <div className="kpi is-ink"><span className="kpi-en">CURRENT DEBT</span><span className="kpi-label">المديونية الحالية</span><span className="kpi-value">{fmt(debt)}<small>EGP</small></span></div>
        <div className="kpi"><span className="kpi-en">CREDIT LIMIT</span><span className="kpi-label">حد الائتمان</span><span className="kpi-value">{fmt(account?.credit_limit ?? 0)}<small>EGP</small></span></div>
        <div className="kpi"><span className="kpi-en">OPENING</span><span className="kpi-label">رصيد أول المدة</span><span className="kpi-value">{fmt(api.data?.opening_balance)}<small>EGP</small></span></div>
        <div className="kpi"><span className="kpi-en">CLOSING</span><span className="kpi-label">رصيد آخر المدة</span><span className="kpi-value">{fmt(api.data?.closing_balance)}<small>EGP</small></span></div>
      </div>
      <div className="grid-2" style={{ gridTemplateColumns: '1fr 320px' }}>
        <section className="panel">
          <div className="toolbar">
            <div className="row" style={{ gap: 20 }}>
              <Field label="من تاريخ"><input type="date" className={`line-input ltr${bad ? ' is-invalid' : ''}`} value={from} onChange={(e) => setFrom(e.target.value)} /></Field>
              <Field label="إلى تاريخ"><input type="date" className={`line-input ltr${bad ? ' is-invalid' : ''}`} value={to} onChange={(e) => setTo(e.target.value)} /></Field>
            </div>
            <div className="chips">{['هذا الشهر', 'آخر 3 شهور', 'هذه السنة'].map((l, i) => <button key={l} className={`chip${chip === i ? ' is-on' : ''}`} onClick={() => setRange(i)}>{l}</button>)}</div>
          </div>
          {bad ? <div style={{ padding: 24 }}><Banner kind="error">تاريخ البداية لازم يكون قبل تاريخ النهاية.</Banner></div> : (
            <DataBoundary api={api}>
              <Async rows={8} cols={6} isEmpty={!entries.length} empty={<Empty icon="fa-receipt" title="لا توجد حركات في هذه الفترة" desc="جرب فترة زمنية أخرى." />}>
                <div className="tbl-wrap"><table className="tbl">
                  <thead><tr><th>التاريخ</th><th>المرجع</th><th>البيان</th><th className="t-end">مدين</th><th className="t-end">دائن</th><th className="t-end">الرصيد</th></tr></thead>
                  <tbody>{entries.map((r, i) => (
                    <tr key={i}>
                      <td className="num">{r.date}</td><td className="sku">{r.ref}</td><td>{r.desc}</td>
                      <td className="t-end num">{r.debit ? fmt(r.debit) : ''}</td><td className="t-end num" style={{ color: 'var(--teal)' }}>{r.credit ? fmt(r.credit) : ''}</td>
                      <td className="t-end num strong">{fmt(r.bal)}</td></tr>))}</tbody>
                  <tfoot><tr><td colSpan="3">رصيد آخر المدة</td><td className="t-end num">{fmt(entries.reduce((a, r) => a + (r.debit || 0), 0))}</td><td className="t-end num">{fmt(entries.reduce((a, r) => a + (r.credit || 0), 0))}</td><td className="t-end num">{fmt(api.data?.closing_balance)}</td></tr></tfoot>
                </table></div>
              </Async>
            </DataBoundary>
          )}
        </section>
        <aside className="stack" style={{ position: 'sticky', top: 100 }}>
          <Panel title="مستحقات مفتوحة" en="OUTSTANDING" body={false}>
            <DataBoundary api={outApi}><Async rows={3} cols={2} isEmpty={!out.length} empty={<Empty title="لا توجد مستحقات مفتوحة" />}>
            {out.map((o) => <div key={o.id} className="out-row" onClick={() => go('order', o.id)}><div><b className="num">{o.number}</b><span className="num">{o.date}</span></div><span className="num strong">{fmt(o.total)}</span></div>)}
            <div className="panel-body" style={{ paddingTop: 12 }}><div className="sum-total" style={{ paddingTop: 0 }}><span>الإجمالي</span><span className="num" style={{ fontSize: 18 }}>{fmt(out.reduce((a, o) => a + (o.total || 0), 0))}</span></div></div>
            </Async></DataBoundary>
          </Panel>
          <p className="note"><i className="fa-solid fa-circle-info" />المديونية والائتمان منفصلين تمامًا عن رصيد المحفظة.</p>
        </aside>
      </div>
    </>
  );
};

/* ---------- 20. New payment notice ---------- */
const NOTICE_FIELD_MAP = { bank_name: 'bank', reference_number: 'ref', transfer_date: 'date', receipt: 'file', order_id: 'order', payment_method: 'method' };

export const NoticeForm = () => {
  const { go, toast, route } = useApp();
  const preselectId = route.id;
  const [f, setF] = useState({ order: '', amount: '', method: 'bank_transfer', bank: '', ref: '', date: today() });
  const [file, setFile] = useState(null);
  const [errs, setErrs] = useState({});
  const [stage, setStage] = useState('form'); // form | confirm | sending | done
  const [done, setDone] = useState(null);
  const inputRef = useRef(null);

  const ordersApi = useApi((signal) => allPages((page, signal) => wholesaleEndpoints.invoices({ payment_status: 'unpaid', page }, signal), signal)
    .then((rows) => rows.map(mapInvoice)), []);
  const orders = ordersApi.data || [];
  useEffect(() => {
    const pre = preselectId ? orders.find((x) => x.id === preselectId) : null;
    if (pre) setF((s) => ({ ...s, order: String(pre.id), amount: String(pre.total ?? '') }));
  }, [preselectId, ordersApi.data]);

  const set = (k, v) => { setF({ ...f, [k]: v }); setErrs({ ...errs, [k]: null }); };

  const pickOrder = (orderId) => {
    const o = orders.find((x) => String(x.id) === orderId);
    setF({ ...f, order: orderId, amount: o ? String(o.total ?? '') : f.amount });
  };

  const validate = () => {
    const e = {};
    if (!f.amount || Number(f.amount) <= 0) e.amount = 'أدخل مبلغ صحيح أكبر من صفر.';
    if (!f.bank.trim()) e.bank = 'اسم البنك مطلوب.';
    if (!f.ref.trim()) e.ref = 'رقم المرجع مطلوب.';
    if (!f.date) e.date = 'تاريخ التحويل مطلوب.';
    else if (f.date > today()) e.date = 'تاريخ التحويل لا يمكن أن يكون في المستقبل.';
    if (!file) e.file = 'إيصال التحويل مطلوب.';
    else if (file.size > 10 * 1024 * 1024) e.file = 'حجم الملف أكبر من 10 ميجابايت.';
    else if (!['application/pdf', 'image/jpeg', 'image/png', 'image/webp'].includes(file.type)) e.file = 'النوع غير مدعوم (pdf/jpg/png/webp).';
    setErrs(e);
    return !Object.keys(e).length;
  };

  const send = async () => {
    setStage('sending');
    const fd = new FormData();
    if (f.order) fd.append('order_id', f.order);
    fd.append('amount', f.amount);
    fd.append('payment_method', f.method);
    fd.append('bank_name', f.bank);
    fd.append('reference_number', f.ref);
    fd.append('transfer_date', f.date);
    fd.append('receipt', file);
    try {
      const n = await wholesaleEndpoints.createNotice(fd);
      setDone(n);
      setStage('done');
    } catch (e) {
      const info = apiError(e);
      const mapped = {};
      Object.entries(info.fields || {}).forEach(([k, msgs]) => {
        mapped[NOTICE_FIELD_MAP[k] || k] = Array.isArray(msgs) ? msgs[0] : String(msgs);
      });
      setErrs(mapped);
      if (!Object.keys(mapped).length) toast(info.message);
      setStage('form');
    }
  };

  if (stage === 'done' && done) return (
    <div className="success-wrap"><div className="order-card">
      <div className="modal-icon" style={{ width: 64, height: 64, fontSize: 26 }}><i className="fa-solid fa-paper-plane" /></div>
      <h1 className="success-title">NOTICE SENT</h1>
      <p className="muted">تم إرسال إشعار السداد للمراجعة</p>
      <p className="success-num num">{done.notice_number}</p>
      <Banner kind="warn" icon="fa-hourglass-half">رفع الإيصال <b>لا يعني اعتماد السداد</b>. الإدارة هتراجع التحويل وتعتمده، وهيوصلك إشعار.</Banner>
      <div className="row mt-24" style={{ justifyContent: 'center' }}><button className="btn-pill is-dark" onClick={() => go('notice', done.id)}>عرض الإشعار</button><button className="btn-pill" onClick={() => go('notices')}>كل الإشعارات</button></div>
    </div></div>
  );

  return (
    <>
      <PageHead en="Payment Notice" crumb={<Crumb items={[{ label: 'إشعارات السداد', go: () => go('notices') }, { label: 'إشعار جديد' }]} />} ar="سجّل تحويل أو شيك أو إيداع تم لحساب الشركة" />
      <div className="grid-2" style={{ gridTemplateColumns: '1fr 340px' }}>
        <section className="panel"><div className="panel-body">
          <div className="fields">
            <Field label="طلب مرتبط" opt span error={errs.order}>
              <DataBoundary api={ordersApi}><Async rows={1} cols={1}>
              <select className="line-input" value={f.order} onChange={(e) => pickOrder(e.target.value)}>
                <option value="">بدون — سداد على الحساب</option>{orders.map((o) => <option key={o.id} value={o.id}>{o.number} · {fmt(o.total)} EGP</option>)}
              </select></Async></DataBoundary></Field>
            <Field label="المبلغ" req error={errs.amount}><div style={{ position: 'relative' }}><input className={`line-input ltr${errs.amount ? ' is-invalid' : ''}`} style={{ textAlign: 'right', paddingLeft: 40 }} inputMode="decimal" placeholder="0.00" value={f.amount} onChange={(e) => set('amount', e.target.value.replace(/[^\d.]/g, ''))} /><span className="soft small" style={{ position: 'absolute', left: 0, top: 12 }}>EGP</span></div></Field>
            <Field label="تاريخ التحويل" req error={errs.date}><input type="date" max={today()} className={`line-input ltr${errs.date ? ' is-invalid' : ''}`} value={f.date} onChange={(e) => set('date', e.target.value)} /></Field>
            <Field label="طريقة السداد" req span error={errs.method}>
              <div className="chips">{Object.entries(NOTICE_METHOD).map(([k, l]) => <button key={k} type="button" className={`chip${f.method === k ? ' is-on' : ''}`} onClick={() => set('method', k)}><i className={`fa-solid ${{ bank_transfer: 'fa-building-columns', check: 'fa-money-check', deposit: 'fa-piggy-bank' }[k]}`} />{l}</button>)}</div></Field>
            <Field label="اسم البنك" req error={errs.bank}><input className={`line-input${errs.bank ? ' is-invalid' : ''}`} placeholder="مثال: البنك الأهلي المصري" value={f.bank} onChange={(e) => set('bank', e.target.value)} /></Field>
            <Field label={f.method === 'check' ? 'رقم الشيك' : 'رقم المرجع'} req error={errs.ref}><input className={`line-input ltr${errs.ref ? ' is-invalid' : ''}`} style={{ textAlign: 'right' }} value={f.ref} onChange={(e) => set('ref', e.target.value)} /></Field>
            <Field label="الإيصال" req span error={errs.file}>
              <input ref={inputRef} type="file" accept=".pdf,.jpg,.jpeg,.png,.webp" style={{ display: 'none' }} onChange={(e) => { setFile(e.target.files?.[0] || null); setErrs({ ...errs, file: null }); }} />
              {file ? (
                <div className="file-row"><i className="fa-regular fa-file-pdf" /><div className="grow"><b className="num">{file.name}</b></div><button className="btn-link muted" onClick={() => setFile(null)}><i className="fa-solid fa-xmark" /></button></div>
              ) : (
                <div className={`drop${errs.file ? ' is-invalid' : ''}`} style={{ minHeight: 120 }} onClick={() => inputRef.current?.click()}>
                  <i className="fa-solid fa-receipt" /><b>ارفع صورة أو PDF للإيصال</b><small>PDF · JPG · JPEG · PNG · WebP — حتى <span className="num">10</span> ميجابايت</small></div>
              )}
            </Field>
          </div>
        </div></section>
        <aside className="stack" style={{ position: 'sticky', top: 100 }}>
          <Panel title="مراجعة">
            <div className="sum-row"><span>الطلب</span><strong className="num">{f.order ? orders.find((o) => String(o.id) === f.order)?.number : 'على الحساب'}</strong></div>
            <div className="sum-row"><span>الطريقة</span><strong>{NOTICE_METHOD[f.method]}</strong></div>
            <div className="sum-total"><span>المبلغ</span><span className="num">{f.amount ? fmt(f.amount) : '—'}</span></div>
            <button className="btn-block mt-24" onClick={() => validate() && setStage('confirm')}>إرسال للمراجعة</button>
          </Panel>
          <p className="note"><i className="fa-solid fa-circle-info" />السداد مش بيتعتمد تلقائيًا؛ الإدارة بتراجع الإيصال مع كشف البنك.</p>
        </aside>
      </div>
      {(stage === 'confirm' || stage === 'sending') && <Modal title="تأكيد إرسال إشعار السداد" onClose={() => setStage('form')} icon={<div className="modal-icon"><i className="fa-solid fa-money-check-dollar" /></div>}
        foot={<><button className="btn-pill" onClick={() => setStage('form')}>تعديل</button><button className="btn-pill is-dark" disabled={stage === 'sending'} onClick={send}>{stage === 'sending' ? <span className="spin" /> : null} تأكيد الإرسال</button></>}>
        <dl className="kv"><dt>المبلغ</dt><dd><Money v={f.amount} strong /></dd><dt>الطريقة</dt><dd>{NOTICE_METHOD[f.method]}</dd><dt>البنك</dt><dd>{f.bank}</dd><dt>المرجع</dt><dd className="sku">{f.ref}</dd><dt>التاريخ</dt><dd className="num">{f.date}</dd><dt>الإيصال</dt><dd className="num">{file?.name}</dd></dl>
      </Modal>}
    </>
  );
};

