      <PageHead en={n?.number || ''} crumb={<Crumb items={[{ label: 'إشعارات السداد', go: () => go('notices') }, { label: n?.number || '', mono: true }]} />} ar={n ? <>أُرسل في <span className="num">{n.created}</span></> : null}>
