                </Panel>
                <Panel title="ملاحظات الإدارة" en="ADMIN NOTE">
                  <div className="note-bubble is-admin" style={{ margin: 0 }}><p>{n.admin_note || <span className="soft">لا توجد ملاحظات</span>}</p></div>
