const today = () => toDate(new Date().toISOString());
const mockPage = <T,>(data: T[], page = 1): Paginated<T> => ({ data: data.slice((page - 1) * 20, page * 20), meta: { current_page: page, last_page: Math.max(1, Math.ceil(data.length / 20)), per_page: 20, total: data.length, from: data.length ? (page - 1) * 20 + 1 : null, to: data.length ? Math.min(page * 20, data.length) : null } });
export const mapTreasury = (t: Treasury): TreasuryRow & { branchId: number | null } => ({ id: t.id, code: t.code, name: t.name, type: treasuryToUI(t.type), branch: t.branch?.name ?? null, branchId: t.branch_id, balance: num(t.current_balance), active: t.is_active });
export const mapExpense = (e: Expense): ExpenseRow => ({ id: e.id, no: e.expense_number, branch: e.branch?.name ?? '', tr: e.treasury_id, cat: e.category, amount: num(e.amount), date: e.expense_date?.slice(0, 10) ?? '', by: e.creator?.name ?? '', shift: e.shift_id ? `#${e.shift_id}` : null, notes: e.notes ?? '', voidedAt: e.voided_at ?? null, voidReason: e.void_reason ?? null, hasAttachment: Boolean(e.attachment_path) });
export const mapShift = (s: PosShift): ShiftRow => ({ id: s.id, no: s.shift_number, cashier: s.cashier?.name ?? '', branch: s.branch?.name ?? '', tr: s.treasury_id, open: s.opened_at, close: s.closed_at, status: s.status === 'closed_pending_approval' ? 'closed' : s.status, exp: s.expected_closing_cash === null ? null : num(s.expected_closing_cash), act: s.actual_closing_cash === null ? null : num(s.actual_closing_cash) });
const quoteStatus = (s: string) => s === 'priced_by_admin' ? 'priced' : s === 'converted_to_order' ? 'converted' : s;
export const mapQuote = (q: Quotation): QuoteRow => ({ id: q.id, no: q.quotation_number, company: q.customer?.company_name || q.customer?.name || '—', cust: q.customer?.name ?? '', status: quoteStatus(q.status), total: q.status === 'draft' || q.status === 'requested' ? null : num(q.grand_total), valid: q.valid_until, date: q.created_at.slice(0, 10), order: q.converted_order_id ? `#${q.converted_order_id}` : undefined });
export const mapNotice = (n: PaymentNotice): PaymentNoticeRow => ({ id: n.id, no: n.notice_number, company: n.customer?.company_name || n.customer?.name || '—', cust: n.customer?.name ?? '', amount: num(n.amount), method: n.payment_method === 'bank_transfer' ? 'bank' : n.payment_method, status: n.status === 'pending_review' ? 'pending' : n.status, date: n.transfer_date ?? n.created_at.slice(0, 10), bank: n.bank_name ?? '', ref: n.reference_number ?? '', file: n.has_receipt, order: n.order_number ?? null, tr: n.treasury_id ?? undefined, review: n.admin_notes ?? undefined });


function RemoteNote({ remote }: { remote: { loading: boolean; error: { message: string } | null; usingMock: boolean; reload: () => void } }) {
  if (remote.usingMock && !USE_MOCK) return <Note tone="red">تعذّر الاتصال بالخادم؛ البيانات المعروضة تجريبية.</Note>;
  if (remote.error) return <><Empty icon="alert" title={remote.error.message} /><button className="btn btn-soft" onClick={remote.reload}>إعادة المحاولة</button></>;
  if (remote.loading) return <AdminLoading />;
  return null;
}

/* ---------------- FINANCE PAGE ---------------- */
export function FinancePage({ sub = 'tr', id, can = () => true }: { sub?: string; id?: string | number; can?: (permission: string) => boolean }) {
  const [tab, setTab] = useState(sub);
  useEffect(() => setTab(sub), [sub]);
  const tabs = [
    { value: 'tr', label: 'الخزائن', icon: 'vault', permission: 'treasuries.view' },
    { value: 'exp', label: 'المصروفات', icon: 'receipt', permission: 'expenses.view' },
    { value: 'trf', label: 'تحويلات الخزائن', icon: 'swap', permission: 'treasury_transfers.view' },
  ].filter(t => can(t.permission));
  const activeTab = tabs.some(t => t.value === tab) ? tab : tabs[0]?.value;
  const numericId = Number(id);
  const recordId = activeTab === sub && Number.isSafeInteger(numericId) && numericId > 0 ? numericId : undefined;

  return (
    <div className="space-y-5">
      <PageHead title="المالية" sub="الخزائن والمصروفات وتحويلات النقدية بين الخزائن." />
      <TabsBar
        value={activeTab}
        onChange={(v: any) => setTab(v)}
        tabs={tabs}
      />
      {recordId && <button type="button" className="btn btn-soft" onClick={() => { window.location.hash = `/finance?tab=${activeTab}`; }}>عرض كل السجلات</button>}
      {activeTab === 'tr' && <TreasuriesTab key={recordId} recordId={recordId} />}
      {activeTab === 'exp' && <ExpensesTab key={recordId} recordId={recordId} can={can} />}
      {activeTab === 'trf' && <TransfersTab key={recordId} recordId={recordId} />}
    </div>
  );
}

export function ExpenseForm({ onClose, onSaved }: { onClose: () => void; onSaved: () => void }) {
  const toast = useToast();
  const { busy, run } = useAction();
  const f = useFormState({ branchId: '', treasuryId: '', category: '', amount: '', date: today(), notes: '' });
  const [idemKey, setIdemKey] = useState(() => newIdempotencyKey());
  const treasures = useRemote((s) => allPages((page) => treasuriesApi.list({ page, per_page: 100, is_active: true }, s)), []);
  const branches = useRemote((s) => allPages((page) => opsApi.get('/api/v1/admin/branches', { params: { page, per_page: 100 }, signal: s }).then((r) => asPage<{ id: number; name: string }>(r))), []);
  const selectedTreasury = treasures.data?.find((t) => t.id === Number(f.v.treasuryId));
  const categories = ['نظافة', 'صيانة', 'نقل وتحميل', 'إيجار', 'ضيافة', 'أدوات مكتبية', 'أخرى'];
  const save = async () => {
    if (!f.v.branchId || !f.v.treasuryId || !f.v.category || !f.v.amount) return toast('أكمل الحقول المطلوبة', 'red');
    const r = await run(() => expensesApi.create({
      branch_id: Number(f.v.branchId),
      treasury_id: Number(f.v.treasuryId), category: f.v.category, amount: Number(f.v.amount),
      expense_date: f.v.date, notes: f.v.notes || null,
    }, idemKey), { toast, success: 'تم تسجيل سند الصرف', onFieldErrors: (e) => f.setErrors(e as any) });
    if (r) { setIdemKey(newIdempotencyKey()); onSaved(); onClose(); }
  };
  return (
    <Modal open onClose={onClose} title="سند صرف مصروفات" icon="receipt" width={560}
      footer={<><button className="btn btn-soft" onClick={onClose}>إلغاء</button><button className="btn btn-dark" disabled={busy} onClick={save}>تسجيل الصرف</button></>}>
      <div className="space-y-4">
        <RemoteNote remote={treasures} />
        <RemoteNote remote={branches} />
        <div className="grid grid-cols-2 gap-3">
          <Field label="الفرع" req err={f.errors.branch_id}>
            <select className="inp" value={f.v.branchId} onChange={f.on('branchId')}>
              <option value="">اختر الفرع</option>
              {(branches.data ?? []).map((b) => <option key={b.id} value={b.id}>{b.name}</option>)}
            </select>
          </Field>
          <Field label="الخزينة المنصرف منها" req err={f.errors.treasury_id}>
            <select className="inp" value={f.v.treasuryId} onChange={f.on('treasuryId' as any)}>
              <option value="">اختر الخزينة</option>
              {(treasures.data ?? []).map((t: { id: number; name: string }) => (<option key={t.id} value={String(t.id)}>{t.name}</option>))}
            </select>
          </Field>
          <Field label="تصنيف المصروف" req err={f.errors.category}>
            <select className="inp" value={f.v.category} onChange={f.on('category' as any)}>
              <option value="">اختر التصنيف</option>
              {categories.map((c) => (<option key={c} value={c}>{c}</option>))}
            </select>
          </Field>
          <Field label="المبلغ (EGP)" req err={f.errors.amount} hint={selectedTreasury && Number(f.v.amount) > num(selectedTreasury.current_balance) ? 'المبلغ أكبر من رصيد الخزينة' : undefined}>
            <input type="number" step="0.01" min="0.01" className="inp num" value={f.v.amount} onChange={f.on('amount' as any)} />
          </Field>
        </div>
        <Field label="التاريخ" req err={f.errors.expense_date}>
          <input type="date" className="inp" value={f.v.date} onChange={f.on('date' as any)} />
        </Field>
        <TextArea label="البيان / الملاحظات" req value={f.v.notes} onChange={(v) => f.set('notes', v)} />
      </div>
    </Modal>
  );
}

const treasuryToUI = (t: string): TreasuryRow['type'] => t === 'main_safe' ? 'main' : t === 'pos_drawer' ? 'drawer' : t === 'bank_account' ? 'bank' : 'main';
const treasuryToBackend = (t: string): TreasuryType => (t === 'main' ? 'main_safe' : t === 'drawer' ? 'pos_drawer' : t === 'bank' ? 'bank_account' : t) as TreasuryType;

export function TreasuryForm({ row, onClose, onSaved }: { row: any; onClose: () => void; onSaved: () => void }) {
  const toast = useToast();
  const { busy, run } = useAction();
  const f = useFormState({ name: row?.name ?? '', code: row?.code ?? '', type: row?.type ?? 'main', branchId: String(row?.branchId ?? ''), active: row?.active ?? true });
  const branches = useRemote((s) => allPages((page) => opsApi.get('/api/v1/admin/branches', { params: { page, per_page: 100 }, signal: s }).then((r) => asPage<{ id: number; name: string }>(r))), []);
  const save = async () => {
    if (!f.v.name.trim()) return toast('اسم الخزينة مطلوب', 'red');
    const body: any = {
      name: f.v.name, code: f.v.code, type: treasuryToBackend(f.v.type),
      branch_id: (f.v.branchId as string) ? Number(f.v.branchId) : null,
      is_active: !!f.v.active,
    };
    const r = await run(() => (row ? treasuriesApi.update(row.id, body) : treasuriesApi.create(body)),
      { toast, success: 'تم الحفظ', onFieldErrors: (e) => f.setErrors(mapErrors(e, { branch_id: 'branchId' })) });
    if (r) { onSaved(); onClose(); }
  };
  return (
    <Modal open onClose={onClose} title={row ? 'تعديل خزينة' : 'خزينة جديدة'} icon="vault" width={600}
      footer={<><button className="btn btn-soft" onClick={onClose}>إلغاء</button><button className="btn btn-dark" disabled={busy} onClick={save}>حفظ</button></>}>
      <div className="space-y-4">
        <div className="grid grid-cols-2 gap-3">
          <Field label="اسم الخزينة" req err={f.errors.name}><input className="inp" value={f.v.name} onChange={f.on('name')} /></Field>
          <Field label="الكود" req err={f.errors.code}><input className="inp" value={f.v.code} onChange={f.on('code')} /></Field>
          <Field label="النوع" req err={f.errors.type}>
            <select className="inp" disabled={!!row} value={f.v.type} onChange={f.on('type' as any)}>
              {Object.entries(TREASURY_TYPES).map(([k, l]) => (<option key={k} value={k}>{l as string}</option>))}
            </select>
          </Field>
        </div>
        <Field label="الفرع" hint="فارغ للخزائن المركزية" err={f.errors.branchId}>
          <select className="inp" value={f.v.branchId} onChange={f.on('branchId' as any)}>
            <option value="">خزينة مركزية</option>
            {(branches.data ?? []).map((b: { id: number; name: string }) => (<option key={b.id} value={String(b.id)}>{b.name}</option>))}
          </select>
        </Field>
        {!row && (<Field label="الرصيد الافتتاحي" hint="يُسجَّل الرصيد عبر تحويل أو إيراد"><input type="number" step="0.01" className="inp num" value={0} readOnly /></Field>)}
        <ToggleRow label="مفعّلة" on={f.v.active} onChange={(v) => f.set('active', v)} />
      </div>
    </Modal>
  );
}

export function TreasuriesTab({ recordId }: { recordId?: number } = {}) {
  const toast = useToast();
  const { run } = useAction();
  const [br, setBr] = useState('');
  const [ty, setTy] = useState('');
  const [act, setAct] = useState('');
  const [form, setForm] = useState<any>(null);
  const [del, setDel] = useState<TreasuryRow | null>(null);
  const [page, setPage] = useState(1);
  useEffect(() => setPage(1), [br, ty, act]);
  const list = useRemote((s) => recordId
    ? treasuriesApi.show(recordId, s).then((record) => mockPage([mapTreasury(record)]))
    : treasuriesApi.list({ page, per_page: 20, branch_id: br || undefined, type: ty ? treasuryToBackend(ty) : undefined, is_active: act ? act === 'true' : undefined }, s).then((p) => ({ ...p, data: p.data.map(mapTreasury) })), [recordId, page, br, ty, act], { mock: () => mockPage(TREASURIES.filter((row) => !recordId || row.id === recordId)) });
  const branches = useRemote((s) => allPages((page) => opsApi.get('/api/v1/admin/branches', { params: { page, per_page: 100 }, signal: s }).then((r) => asPage<{ id: number; name: string }>(r))), []);
  const rows = list.data?.data ?? [];
  const sum = (k: string) => rows.filter((t) => t.type === k).reduce((a, t) => a + t.balance, 0);

  return (
    <>
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 stg stg-2">
        <KPI
          hero
          label="الحسابات البنكية"
          icon="bank"
          value={<span className="ltr">{fmtNum(sum('bank'), 0)}</span>}
          small
          foot="EGP"
        />
        <KPI
          label="الخزائن الرئيسية"
          icon="vault"
          value={<span className="ltr">{fmtNum(sum('main'), 0)}</span>}
          small
          foot="EGP"
        />
        <KPI
          label="أدراج الكاشير"
          icon="cash"
          value={<span className="ltr">{fmtNum(sum('drawer'), 0)}</span>}
          small
          foot="EGP"
        />
      </div>
      <Card stg={3}>
        <div className="flex flex-wrap items-center justify-between gap-2 mb-4">
          <div className="flex flex-wrap gap-2">
            <FSelect value={br} onChange={setBr} placeholder="الفرع" options={(branches.data ?? []).map((b) => ({ value: String(b.id), label: b.name }))} />
            <FSelect
              value={ty}
              onChange={setTy}
              placeholder="النوع"
              options={Object.entries(TREASURY_TYPES).map(([v, l]) => ({ value: v, label: l }))}
            />
            <FSelect
              value={act}
              onChange={setAct}
              placeholder="التفعيل"
              options={[
                { value: 'true', label: 'مفعّلة' },
                { value: 'false', label: 'معطّلة' },
              ]}
            />
          </div>
          <button className="btn btn-dark btn-sm" onClick={() => setForm({})}>
            <Icon name="plus" size={13} />
            خزينة جديدة
          </button>
        </div>
        <RemoteNote remote={list} />
        <DataTable
          rows={rows}
          onRow={list.usingMock ? undefined : setForm}
          cols={[
            {
              h: 'الخزينة',
              r: (t: TreasuryRow) => (
                <div className="flex items-center gap-2.5">
                  <span className="w-8 h-8 rounded-[10px] v-sub flex items-center justify-center tx2">
                    <Icon
                      name={
                        ({
                          bank: 'bank',
                          main: 'vault',
                          drawer: 'cash',
                          branch: 'vault',
                        } as const)[t.type as 'bank'] || 'vault'
                      }
                      size={14}
                    />
                  </span>
                  <span className="font-semibold tx1">{t.name}</span>
                </div>
              ),
            },
            {
              h: 'الكود',
              r: (t: TreasuryRow) => (
                <span className="num text-[11.5px] font-semibold v-sub px-2 py-1 rounded-md tx2">{t.code}</span>
              ),
            },
            {
              h: 'النوع',
              r: (t: TreasuryRow) => (
                <Badge
                  dot={false}
                  tone={
                    ({
                      bank: 'blue',
                      main: 'violet',
                      drawer: 'orange',
                      branch: 'gray',
                    } as const)[t.type as 'bank'] || 'gray'
                  }
                >
                  {TREASURY_TYPES[t.type as keyof typeof TREASURY_TYPES] || t.type}
                </Badge>
              ),
            },
            {
              h: 'الفرع',
              r: (t: TreasuryRow) => (t.branch ? <span className="tx2">{t.branch}</span> : <span className="tx3">مركزي</span>),
            },
            {
              h: 'الرصيد الحالي',
              r: (t: TreasuryRow) => (
                <span className={'font-semibold ' + (t.balance < 0 ? 'c-red' : '')}>{fmtMoney(t.balance)}</span>
              ),
            },
            { h: 'التفعيل', r: (t: TreasuryRow) => <ActiveDot on={t.active} /> },
            {
              h: '',
              r: (t: TreasuryRow) => (
                <RowActions>
                  <button className="icon-btn !w-7 !h-7" disabled={list.usingMock} onClick={() => setForm(t)}>
                    <Icon name="edit" size={13} />
                  </button>
                  <button className="icon-btn !w-7 !h-7" disabled={list.usingMock} onClick={() => setDel(t)}>
                    <Icon name="trash" size={13} />
                  </button>
                </RowActions>
              ),
            },
          ]}
        />
        <Pager total={list.data?.meta.total ?? 0} page={page} per={20} onPage={setPage} />
      </Card>
      {form && (
        <TreasuryForm row={form.id ? form : null} onClose={() => setForm(null)} onSaved={() => list.reload()} />
      )}
      <ConfirmModal
        open={!!del}
        onClose={() => setDel(null)}
        danger
        title={'حذف «' + (del?.name || '') + '»'}
        cta="حذف الخزينة"
        text="لا يمكن حذف خزينة بها رصيد أو حركات سابقة."
        onConfirm={async () => {
          if (!del || list.usingMock) return;
          if (del.balance !== 0) return toast('لا يمكن حذف خزينة رصيدها لا يساوي صفر', 'red');
          const r = await run(() => treasuriesApi.remove(del.id), { toast, success: 'تم الحذف' });
          if (r) { setDel(null); list.reload(); }
        }}
      />
    </>
  );
}

export function ExpensesTab({ recordId, can = () => true }: { recordId?: number; can?: (permission: string) => boolean } = {}) {
  const toast = useToast();
  const { busy, run } = useAction();
  const [br, setBr] = useState('');
  const [tr, setTr] = useState('');
  const [cat, setCat] = useState('');
  const [form, setForm] = useState(false);
  const [voiding, setVoiding] = useState<ExpenseRow | null>(null);
  const [voidReason, setVoidReason] = useState('');

  const categories = ['نظافة', 'صيانة', 'نقل وتحميل', 'إيجار', 'ضيافة', 'أدوات مكتبية', 'أخرى'];
  const [page, setPage] = useState(1);
  useEffect(() => setPage(1), [br, tr, cat]);
  const list = useRemote((s) => recordId
    ? expensesApi.show(recordId, s).then((record) => mockPage([mapExpense(record)]))
    : expensesApi.list({ page, per_page: 20, branch_id: br || undefined, treasury_id: tr || undefined, category: cat || undefined }, s).then((p) => ({ ...p, data: p.data.map(mapExpense) })), [recordId, page, br, tr, cat], { mock: () => mockPage(EXPENSES.filter((row) => !recordId || row.id === recordId)) });
  const treasures = useRemote((s) => allPages((page) => treasuriesApi.list({ page, per_page: 100 }, s)), []);
  const branches = useRemote((s) => allPages((page) => opsApi.get('/api/v1/admin/branches', { params: { page, per_page: 100 }, signal: s }).then((r) => asPage<{ id: number; name: string }>(r))), []);
  const rows = list.data?.data ?? [];
  const activeRows = rows.filter(e => !e.voidedAt);
  const largest = [...activeRows].sort((a, b) => b.amount - a.amount)[0];
  const nameOf = (id: number) => treasures.data?.find((t) => t.id === id)?.name ?? (USE_MOCK ? trName(id) : `#${id}`);
  const total = activeRows.reduce((a, e) => a + e.amount, 0);

  return (
    <>
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 stg stg-2">
        <KPI
          hero
          label="إجمالي المصروفات المعروضة"
          icon="receipt"
          value={<span className="ltr">{fmtNum(total, 0)}</span>}
          small
          foot="EGP"
        />
        <KPI label="عدد سندات الصرف" icon="file" value={rows.length} foot="سند مسجّل" />
        <KPI label="أعلى بند صرف" icon="tag" value={largest?.cat ?? '—'} foot={largest ? fmtMoney(largest.amount) : '—'} />
      </div>
      <Card stg={3}>
        <div className="flex flex-wrap items-center justify-between gap-2 mb-4">
          <div className="flex flex-wrap gap-2">
            <FSelect value={br} onChange={setBr} placeholder="الفرع" options={(branches.data ?? []).map((b: { id: number; name: string }) => ({ value: String(b.id), label: b.name }))} />
            <FSelect
              value={tr}
              onChange={setTr}
              placeholder="الخزينة"
              options={(treasures.data ?? []).map((t: { id: number; name: string }) => ({ value: String(t.id), label: t.name }))}
            />
            <FSelect value={cat} onChange={setCat} placeholder="التصنيف" options={categories} />
          </div>
          <button className="btn btn-dark btn-sm" onClick={() => setForm(true)}>
            <Icon name="plus" size={13} />
            سند صرف
          </button>
        </div>
        <RemoteNote remote={list} />
        <DataTable
          rows={rows}
          cols={[
            { h: 'رقم السند', r: (e: ExpenseRow) => <span className="num font-semibold tx1">{e.no}</span> },
            { h: 'الحالة', r: (e: ExpenseRow) => <Badge tone={e.voidedAt ? 'red' : 'green'}>{e.voidedAt ? 'ملغى' : 'مسجّل'}</Badge> },
            { h: 'الفرع', r: (e: ExpenseRow) => <span className="tx2">{e.branch}</span> },
            { h: 'الخزينة', r: (e: ExpenseRow) => <span className="text-[12px]">{nameOf(e.tr)}</span> },
            {
              h: 'التصنيف',
              r: (e: ExpenseRow) => (
                <Badge dot={false} tone="gray">
                  {e.cat}
                </Badge>
              ),
            },
            {
              h: 'المبلغ',
              r: (e: ExpenseRow) => <span className="font-semibold c-red">{fmtMoney(e.amount)}</span>,
            },
            { h: 'التاريخ', r: (e: ExpenseRow) => <Num className="tx2">{e.date}</Num> },
            {
              h: 'بواسطة',
              r: (e: ExpenseRow) => (
                <div className="flex items-center gap-1.5 text-[12px]">
                  <Avatar name={e.by} tone={e.id} size={22} />
                  <span>{e.by}</span>
                </div>
              ),
            },
            {
              h: 'الوردية',
              r: (e: ExpenseRow) => (e.shift ? <Num className="tx3 text-[11px]">{e.shift}</Num> : <span className="tx3">—</span>),
            },
            {
              h: 'ملاحظات',
              r: (e: ExpenseRow) => <span className="text-[11.5px] tx2 clamp1">{e.voidReason || e.notes || '—'}</span>,
            },
            { h: 'الإيصال', r: (e: ExpenseRow) => e.hasAttachment ? (
              <button type="button" className="btn btn-soft btn-sm" onClick={() => {
                void expensesApi.openAttachment(e.id).catch((error) => toast(parseApiError(error).message, 'red'));
              }}>📎 فتح الإيصال</button>
            ) : null },
            { h: '', r: (e: ExpenseRow) => !e.voidedAt && !e.shift && can('expenses.delete') ? <button className="btn btn-soft btn-sm" onClick={() => { setVoiding(e); setVoidReason(''); }}>إلغاء المصروف</button> : null },
          ]}
        />
        <Pager total={list.data?.meta.total ?? 0} page={page} per={20} onPage={setPage} />
      </Card>
      {form && (
        <ExpenseForm onClose={() => setForm(false)} onSaved={() => { list.reload(); treasures.reload(); }} />
      )}
      {voiding && <Modal open title={`إلغاء المصروف ${voiding.no}`} onClose={() => { if (!busy) setVoiding(null); }}
        footer={<button className="btn btn-dark" disabled={busy || !voidReason.trim()} onClick={async () => {
          if (list.usingMock) return toast('البيانات المعروضة تجريبية — لم يتم الحفظ', 'red');
          const result = await run(() => expensesApi.void(voiding.id, voidReason.trim()), { toast, success: 'تم إلغاء المصروف وعكس أثره على الخزينة' });
          if (result) { setVoiding(null); list.reload(); treasures.reload(); }
        }}>تأكيد الإلغاء</button>}>
        <Note>يُحفظ السند في سجل التدقيق ويُعاد المبلغ إلى الخزينة.</Note>
        <TextArea label="سبب الإلغاء" req value={voidReason} onChange={setVoidReason} />
      </Modal>}
    </>
  );
}

export function TransfersTab({ recordId }: { recordId?: number } = {}) {
  const toast = useToast();
  const { busy, run } = useAction();
  const [st, setSt] = useState('');
  const [tr, setTr] = useState('');
  const [view, setView] = useState<any>(null);
  const [form, setForm] = useState(false);
  const [src, setSrc] = useState('');
  const [idemKey, setIdemKey] = useState(() => newIdempotencyKey());
  const [unresolved, setUnresolved] = useState(false);
  const [dst, setDst] = useState('');
  const [amount, setAmount] = useState('');
  const [notes, setNotes] = useState('');
  const [errors, setErrors] = useState<Record<string, string>>({});

  const [page, setPage] = useState(1);
  useEffect(() => setPage(1), [st, tr]);
  const list = useRemote(async (s) => {
    // The server supports separate source/destination filters, not an OR filter.
    const result = recordId
      ? mockPage([await treasuryTransfersApi.show(recordId, s)])
      : tr
      ? mockPage((await allPages((page) => treasuryTransfersApi.list({ page, per_page: 100, status: st || undefined }, s))).filter((x) => String(x.from_treasury_id) === tr || String(x.to_treasury_id) === tr), page)
      : await treasuryTransfersApi.list({ page, per_page: 20, status: st || undefined }, s);
    return { ...result, data: result.data.map((x): TreasuryTransfer => ({
      id: x.id, from: x.from_treasury_id, to: x.to_treasury_id, amount: num(x.amount),
      status: x.status, date: (x.created_at ?? '').slice(0, 10), by: x.creator?.name ?? '', appr: x.approver?.name ?? null, notes: x.notes,
    })) };
  }, [recordId, page, st, tr], { mock: () => mockPage(TRANSFERS.filter((x) => recordId ? x.id === recordId : (!st || x.status === st) && (!tr || String(x.from) === tr || String(x.to) === tr)), page) });
  const treasures = useRemote((s) => allPages((page) => treasuriesApi.list({ page, per_page: 100 }, s)), []);
  const nameOf = (id: number) => (treasures.data ?? []).find((t) => t.id === id)?.name ?? (USE_MOCK ? trName(id) : `#${id}`);
  const rows = (list.data?.data ?? []).filter(
    (x) => recordId || ((!st || x.status === st) && (!tr || String(x.from) === tr || String(x.to) === tr))
  );
  const approve = async (id: number) => {
    if (list.usingMock) return toast('البيانات المعروضة تجريبية — لم يتم الحفظ', 'red');
    const r = await run(() => treasuryTransfersApi.approve(id), { toast, success: 'تم اعتماد التحويل' });
    if (r) { setView(null); list.reload(); treasures.reload(); }
  };
  const reject = async (id: number) => {
    if (list.usingMock) return toast('البيانات المعروضة تجريبية — لم يتم الحفظ', 'red');
    const r = await run(() => treasuryTransfersApi.reject(id), { toast, success: 'تم رفض التحويل' });
    if (r) { setView(null); list.reload(); treasures.reload(); }
  };
  const create = async () => {
    if (!src || !dst || src === dst) return toast('اختر مصدرًا ووجهة مختلفين', 'red');
    if (!amount || Number(amount) <= 0) return toast('أدخل مبلغًا صحيحًا', 'red');
    const r = await run(async () => {
      setUnresolved(true);
      try {
        return await treasuryTransfersApi.create({
          from_treasury_id: Number(src), to_treasury_id: Number(dst), amount: Number(amount), notes: notes || null,
        }, idemKey);
      } catch (error) {
        const { status } = parseApiError(error);
        if (status !== null && status >= 400 && status < 500 && ![408, 409, 425, 429].includes(status)) setUnresolved(false);
        throw error;
      }
    }, { toast, success: 'أُرسل طلب التحويل', onFieldErrors: setErrors });
    if (r) { setUnresolved(false); setIdemKey(newIdempotencyKey()); setForm(false); setSrc(''); setDst(''); setAmount(''); setNotes(''); list.reload(); treasures.reload(); }
  };
  const closeForm = () => {
    if (busy) return;
    setForm(false);
    if (!unresolved) { setIdemKey(newIdempotencyKey()); setErrors({}); }
  };

  return (
    <>
      <Card stg={3}>
        <div className="flex flex-wrap items-center justify-between gap-2 mb-4">
          <div className="flex flex-wrap gap-2">
            <FSelect
              value={st}
              onChange={setSt}
              placeholder="الحالة"
              options={Object.entries(TRANSFER_STATUS).map(([v, s]) => ({ value: v, label: s.label }))}
            />
            <FSelect
              value={tr}
              onChange={setTr}
              placeholder="الخزينة (مصدر أو وجهة)"
              options={(treasures.data ?? []).map((t: { id: number; name: string }) => ({ value: String(t.id), label: t.name }))}
            />
          </div>
          <button className="btn btn-dark btn-sm" onClick={() => setForm(true)}>
            <Icon name="plus" size={13} />
            طلب تحويل
          </button>
        </div>
        <RemoteNote remote={list} />
        <DataTable
          rows={rows}
          onRow={list.usingMock ? undefined : setView}
          cols={[
            {
              h: 'المصدر',
              r: (x: TreasuryTransfer) => <span className="font-semibold tx1">{nameOf(x.from)}</span>,
            },
            {
              h: 'الوجهة',
              r: (x: TreasuryTransfer) => <span className="font-semibold tx1">{nameOf(x.to)}</span>,
            },
            {
              h: 'المبلغ',
              r: (x: TreasuryTransfer) => <span className="font-display font-bold text-[14px]">{fmtMoney(x.amount)}</span>,
            },
            { h: 'الحالة', r: (x: TreasuryTransfer) => <StatusBadge map={TRANSFER_STATUS} value={x.status} /> },
            { h: 'التاريخ', r: (x: TreasuryTransfer) => <Num className="tx2">{x.date}</Num> },
            { h: 'المنشئ', r: (x: TreasuryTransfer) => <span className="text-[12px] tx2">{x.by}</span> },
            {
              h: 'المعتمد',
              r: (x: TreasuryTransfer) => (x.appr ? <span className="text-[12px] tx2">{x.appr}</span> : <span className="tx3">—</span>),
            },
            {
              h: '',
              r: (x: TreasuryTransfer) =>
                x.status === 'pending' && (
                  <RowActions>
                    <button className="btn btn-danger btn-xs" disabled={busy} onClick={() => reject(x.id)}>
                      رفض
                    </button>
                    <button className="btn btn-success btn-xs" disabled={busy} onClick={() => approve(x.id)}>
                      اعتماد
                    </button>
                  </RowActions>
                ),
            },
          ]}
        />
        <Pager total={list.data?.meta.total ?? 0} page={page} per={20} onPage={setPage} />
      </Card>
      {view && (
        <Modal
          open
          onClose={() => setView(null)}
          title="طلب تحويل"
          icon="swap"
          width={520}
          footer={
            view.status === 'pending' && (
              <>
                <button
                  className="btn btn-danger"
                  disabled={busy}
                  onClick={() => reject(view.id)}
                >
                  رفض
                </button>
                <button
                  className="btn btn-dark"
                  disabled={busy}
                  onClick={() => approve(view.id)}
                >
                  اعتماد
                </button>
              </>
            )
          }
        >
          <div className="space-y-4 pb-2">
            <div className="grid grid-cols-[1fr_auto_1fr] items-center gap-3">
              <div className="v-sub p-3 text-center">
                <div className="text-[11px] tx3 mb-1">من</div>
                <div className="font-semibold text-[12.5px]">{nameOf(view.from)}</div>
              </div>
              <span className="w-9 h-9 rounded-full btn-accent flex items-center justify-center">
                <Icon name="arrowL" size={15} />
              </span>
              <div className="v-sub p-3 text-center">
                <div className="text-[11px] tx3 mb-1">إلى</div>
                <div className="font-semibold text-[12.5px]">{nameOf(view.to)}</div>
              </div>
            </div>
            <div className="text-center">
              <div className="font-display text-[28px] font-bold">{fmtMoney(view.amount)}</div>
              <div className="mt-1">
                <StatusBadge map={TRANSFER_STATUS} value={view.status} />
              </div>
            </div>
            <KV
              items={[
                ['المنشئ', view.by],
                ['المعتمد', view.appr],
                ['التاريخ', <Num>{view.date}</Num>],
                ['ملاحظات', view.notes],
              ]}
            />
          </div>
        </Modal>
      )}
      <Modal
        open={form}
        onClose={closeForm}
        title="طلب تحويل بين خزائن"
        icon="swap"
        width={520}
        sub="يُنشأ بحالة «بانتظار الاعتماد» ولا يمكن تعديله بعد ذلك."
        footer={
          <>
            <button className="btn btn-soft" disabled={busy} onClick={closeForm}>
              إلغاء
            </button>
            <button
              className="btn btn-dark"
              disabled={!src || !dst || src === dst || busy}
              onClick={create}
            >
              إنشاء الطلب
            </button>
          </>
        }
      >
        {unresolved && <p role="status">نتيجة الطلب السابق لم تُحسم. أعد الإرسال بنفس البيانات للتحقق منه بأمان.</p>}
        <fieldset disabled={busy || unresolved} className="space-y-4">
          <div className="grid grid-cols-2 gap-3">
            <Field label="الخزينة المصدر" req err={errors.from_treasury_id}>
              <select className="inp" value={src} onChange={(e) => setSrc(e.target.value)}>
                <option value="">اختر</option>
                {(treasures.data ?? []).map((x: { id: number; name: string }) => (
                  <option key={x.id} value={x.id}>
                    {x.name}
                  </option>
                ))}
              </select>
            </Field>
            <Field label="الخزينة الوجهة" req err={errors.to_treasury_id || (src && src === dst ? 'يجب أن تختلف عن المصدر' : null)}>
              <select
                className={'inp ' + (src && src === dst ? 'err' : '')}
                value={dst}
                onChange={(e) => setDst(e.target.value)}
              >
                <option value="">اختر</option>
                {(treasures.data ?? []).map((x: { id: number; name: string }) => (
                  <option key={x.id} value={x.id} disabled={String(x.id) === src}>
                    {x.name}
                  </option>
                ))}
              </select>
            </Field>
          </div>
          <Field label="المبلغ" req err={errors.amount}>
            <input type="number" step="0.01" min="0.01" className="inp num" value={amount} onChange={(e) => setAmount(e.target.value)} />
          </Field>
          <TextArea label="ملاحظات" value={notes} onChange={setNotes} />
        </fieldset>
      </Modal>
    </>
  );
}

/* ---------------- SHIFTS PAGE ---------------- */
export function DiffCell({ s }: { s: ShiftRow }) {
  if (s.exp == null) return <span className="tx3">—</span>;
  const d = (s.act ?? 0) - s.exp;
  if (d === 0) return <Badge tone="green" dot={false}>مطابق</Badge>;
  return (
    <span className={'font-semibold ' + (d < 0 ? 'c-red' : 'c-amber')}>
      {d < 0 ? 'عجز ' : 'زيادة '}
      <span className="num ltr">{fmtNum(Math.abs(d))}</span>
    </span>
  );
}

export function ShiftsPage() {
  const toast = useToast();
  const { busy, run } = useAction();
  const [br, setBr] = useState('');
  const [ca, setCa] = useState('');
  const [st, setSt] = useState('');
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [view, setView] = useState<ShiftRow | null>(null);

  const [page, setPage] = useState(1);
  useEffect(() => setPage(1), [br, ca, st, from, to]);
  const list = useRemote((s) => shiftsApi.list({ page, per_page: 20, branch_id: br || undefined, user_id: ca || undefined, status: st === 'closed' ? 'closed_pending_approval' : st || undefined, from_date: from || undefined, to_date: to || undefined }, s).then((p) => ({ ...p, data: p.data.map(mapShift) })), [page, br, ca, st, from, to], { mock: () => mockPage(SHIFTS) });
  const branches = useRemote((s) => allPages((page) => opsApi.get('/api/v1/admin/branches', { params: { page, per_page: 100 }, signal: s }).then((r) => asPage<{ id: number; name: string }>(r))), []);
  const cashiers = useRemote((s) => allPages((page) => opsApi.get('/api/v1/admin/users', { params: { page, per_page: 100 }, signal: s }).then((r) => asPage<{id: number; name: string}>(r))), []);
  const treasures = useRemote((s) => allPages((page) => treasuriesApi.list({ page, per_page: 100 }, s)), []);
  const nameOf = (id: number) => treasures.data?.find((t) => t.id === id)?.name ?? (USE_MOCK ? trName(id) : `#${id}`);
  const rows = list.data?.data ?? [];
  const approveShift = async (id: number) => {
    if (list.usingMock) return toast('البيانات المعروضة تجريبية — لم يتم الحفظ', 'red');
    const r = await run(() => shiftsApi.approve(id), { toast, success: 'تم اعتماد الوردية' });
    if (r) { setView(null); list.reload(); }
  };

  return (
    <div className="space-y-5">
      <PageHead title="مراجعة الورديات" sub="مطابقة النقدية المتوقعة مع الفعلية واعتماد الورديات المغلقة." />
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 stg stg-2">
        <KPI
          hero
          label="بانتظار الاعتماد"
          icon="clock"
          value={rows.filter((s) => s.status === 'closed').length}
          foot="ورديات مغلقة"
        />
        <KPI
          label="ورديات بها فروق"
          icon="alert"
          value={rows.filter((s) => s.exp != null && s.act !== s.exp).length}
          foot="عجز أو زيادة"
        />
        <KPI label="إجمالي الورديات المسجلة" icon="calendar" value={list.data?.meta.total ?? 0} foot="وردية" />
      </div>
      <Card stg={3}>
        <div className="flex flex-wrap gap-2 mb-4">
          <FSelect value={br} onChange={setBr} placeholder="الفرع" options={(branches.data ?? []).map((b) => ({ value: String(b.id), label: b.name }))} />
          <FSelect value={ca} onChange={setCa} placeholder="الكاشير" options={(cashiers.data ?? []).map((c) => ({ value: String(c.id), label: c.name }))} />
          <FSelect
            value={st}
            onChange={setSt}
            placeholder="الحالة"
            options={Object.entries(SHIFT_STATUS).map(([v, s]) => ({ value: v, label: s.label }))}
          />
          <FDate label="من" value={from} onChange={setFrom} />
          <FDate label="إلى" value={to} onChange={setTo} />
        </div>
        <RemoteNote remote={list} />
        <DataTable
          rows={rows}
          onRow={setView}
          cols={[
            { h: 'رقم الوردية', r: (s: ShiftRow) => <span className="num font-semibold tx1">{s.no}</span> },
            {
              h: 'الكاشير / الفرع',
              r: (s: ShiftRow) => (
                <div className="flex items-center gap-2">
                  <Avatar name={s.cashier} tone={s.id} size={28} />
                  <div className="leading-tight">
                    <div className="font-medium tx1">{s.cashier}</div>
                    <div className="text-[11px] tx3">{s.branch}</div>
                  </div>
                </div>
              ),
            },
            { h: 'الخزينة', r: (s: ShiftRow) => <span className="text-[12px] tx2">{nameOf(s.tr)}</span> },
            {
              h: 'الفتح / الإغلاق',
              r: (s: ShiftRow) => (
                <div className="leading-tight num text-[11.5px]">
                  <div className="tx1">{s.open}</div>
                  <div className="tx3">{s.close || '—'}</div>
                </div>
              ),
            },
            { h: 'الحالة', r: (s: ShiftRow) => <StatusBadge map={SHIFT_STATUS} value={s.status} /> },
            {
              h: 'المتوقعة',
              r: (s: ShiftRow) => (s.exp != null ? fmtMoney(s.exp) : <span className="tx3">—</span>),
            },
            {
              h: 'الفعلية',
              r: (s: ShiftRow) => (s.act != null ? fmtMoney(s.act) : <span className="tx3">—</span>),
            },
            { h: 'الفرق', r: (s: ShiftRow) => <DiffCell s={s} /> },
          ]}
        />
        <Pager total={list.data?.meta.total ?? 0} page={page} per={20} onPage={setPage} />
      </Card>
      {view && (
        <ShiftModal
          s={view}
          onClose={() => setView(null)}
          onApprove={() => approveShift(view.id)}
        />
      )}
    </div>
  );
}

export function ShiftModal({ s: initial, onClose, onApprove }: { s: ShiftRow; onClose: () => void; onApprove: () => void }) {
  const detail = useRemote((signal) => shiftsApi.show(initial.id, signal), [initial.id]);
  const s = detail.data ? mapShift(detail.data) : initial;
  const opening = num(detail.data?.opening_cash);
  const cashSales = num(detail.data?.cash_sales_total);
  const cardSales = num(detail.data?.card_sales_total);
  const cashRet = num(detail.data?.cash_returns_total);
  const cashExp = num(detail.data?.cash_expenses_total);
  const exp = s.exp ?? opening + cashSales - cashRet - cashExp;
  const d = s.act != null ? s.act - exp : null;

  return (
    <Modal
      open
      onClose={onClose}
      width={680}
      icon="clock"
      title={
        <span className="flex items-center gap-2">
          <span className="num">{s.no}</span>
          <StatusBadge map={SHIFT_STATUS} value={s.status} />
        </span>
      }
      sub={
        <>
          {s.cashier} · {s.branch} · {detail.data?.treasury?.name ?? `#${s.tr}`}
        </>
      }
      footer={
        detail.data?.status === 'closed_pending_approval' ? (
          <>
            <button className="btn btn-soft" onClick={onClose}>
              إغلاق
            </button>
            <button className="btn btn-dark" onClick={onApprove}>
              <Icon name="check" size={14} />
              اعتماد الوردية
            </button>
          </>
        ) : null
      }
    >
      <div className="space-y-4 pb-2">
        <RemoteNote remote={detail} />
        {s.status === 'open' && (
          <Note tone="blue" icon="info">
            الوردية ما زالت مفتوحة — الأرقام حتى اللحظة، والاعتماد متاح بعد إغلاقها من نقطة البيع.
          </Note>
        )}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <div className="v-sub p-4 space-y-2.5 text-[12.5px]">
            {[
              ['عهدة بداية الوردية', opening, ''],
              ['+ المبيعات النقدية', cashSales, 'c-green'],
              ['− المرتجعات النقدية', -cashRet, 'c-red'],
              ['− المصروفات النقدية', -cashExp, 'c-red'],
            ].map(([l, v, c]) => (
              <div key={l as string} className="flex items-center justify-between">
                <span className="tx2">{l}</span>
                <span className={'font-semibold ' + (c as string)}>{fmtMoney(v as number)}</span>
              </div>
            ))}
            <div className="flex items-center justify-between v-bt pt-2.5">
              <span className="font-semibold tx1">النقدية المتوقعة</span>
              <span className="font-display font-bold">{fmtMoney(exp)}</span>
            </div>
            <div className="flex items-center justify-between text-[11.5px] tx3">
              <span>مبيعات البطاقات (خارج الدرج)</span>
              <span>{fmtMoney(cardSales)}</span>
            </div>
          </div>
          <div
            className={
              'rounded-[18px] p-4 flex flex-col justify-between ' +
              (d == null ? 'v-sub' : d === 0 ? 't-green' : d < 0 ? 't-red' : 't-amber')
            }
          >
            <div>
              <div className="text-[12px] font-medium opacity-90">النقدية الفعلية</div>
              <div className="font-display text-[26px] font-bold num ltr mt-1">
                {s.act != null ? fmtNum(s.act) : '—'}
              </div>
            </div>
            <div className="mt-4">
              <div className="text-[12px] font-medium opacity-90">الفرق</div>
              <div className="font-display text-[20px] font-bold mt-0.5">
                {d == null ? (
                  '—'
                ) : d === 0 ? (
                  'مطابق'
                ) : (
                  <>
                    {d < 0 ? 'عجز' : 'زيادة'} <span className="num ltr">{fmtNum(Math.abs(d))}</span>
                  </>
                )}
              </div>
            </div>
          </div>
        </div>
        <div>
          <div className="lbl mb-2">مصروفات الوردية</div>
          <DataTable
            compact
            rows={(detail.data?.expenses ?? []).map(mapExpense)}
            cols={[
              { h: 'رقم السند', r: (e: ExpenseRow) => <span className="num">{e.no}</span> },
              { h: 'التصنيف', r: (e: ExpenseRow) => e.cat },
              { h: 'المبلغ', r: (e: ExpenseRow) => fmtMoney(e.amount) },
              { h: 'البيان', r: (e: ExpenseRow) => e.notes || '—' },
            ]}
            empty="لا توجد مصروفات مسجلة على هذه الوردية"
          />
        </div>
      </div>
    </Modal>
  );
}

/* ---------------- WHOLESALE PAGE ---------------- */
export function WholesalePage({ sub = 'quotes' }: { sub?: string }) {
  const [tab, setTab] = useState(sub);
  useEffect(() => setTab(sub), [sub]);

  return (
    <div className="space-y-5">
      <PageHead title="الجملة" sub="تسعير عروض أسعار التجار ومراجعة إشعارات السداد الواردة من بوابة الجملة." />
      <TabsBar
        value={tab}
        onChange={(v: any) => setTab(v)}
        tabs={[
          {
            value: 'quotes',
            label: 'عروض الأسعار',
            icon: 'quote',
          },
          {
            value: 'notices',
            label: 'إشعارات السداد',
            icon: 'bank',
          },
        ]}
      />
      {tab === 'quotes' ? <QuotesTab /> : <NoticesTab />}
    </div>
  );
}

export function QuotesTab() {
  const toast = useToast();
  const { busy, run } = useAction();
  const [st, setSt] = useState('');
  const [cu, setCu] = useState('');
  const [page, setPage] = useState(1);
  const [view, setView] = useState<QuoteRow | null>(null);
  const [price, setPrice] = useState(false);
  const [expire, setExpire] = useState(false);
  const [prices, setPrices] = useState<Record<number, string>>({});
  const [validUntil, setValidUntil] = useState('');
  const [adminNotes, setAdminNotes] = useState('');
  const [errors, setErrors] = useState<Record<string, string>>({});
  useEffect(() => setPage(1), [st, cu]);
  const status = st === 'priced' ? 'priced_by_admin' : st === 'converted' || st === 'ordered' ? 'converted_to_order' : st;
  const list = useRemote((s) => quotationsApi.list({ page, per_page: 20, status: status || undefined, customer_id: cu || undefined }, s).then((p) => ({ ...p, data: p.data.map(mapQuote) })), [page, st, cu], { mock: () => mockPage(QUOTES) });
  const customers = useRemote((s) => allPages((page) => opsApi.get('/api/v1/admin/customers', { params: { page, type: 'wholesale', per_page: 100 }, signal: s }).then((r) => asPage<{ id: number; name: string; company_name?: string }>(r))), []);
  const detail = useRemote((s) => quotationsApi.show(view!.id, s), [view?.id], { enabled: !!view });
  useEffect(() => {
    if (!detail.data) return;
    setPrices(Object.fromEntries((detail.data.items ?? []).map((item) => [item.id, item.offered_unit_price ?? item.requested_target_price ?? ''])));
    setValidUntil(detail.data.valid_until ?? '');
    setAdminNotes(detail.data.admin_notes ?? '');
    setErrors({});
  }, [detail.data]);
  const rows = list.data?.data ?? [];
  const lines = (detail.data?.items ?? []).map((item) => ({ id: item.id, v: { name: item.variant?.product_name ?? '—', sku: item.variant?.sku ?? '', price: num(item.offered_unit_price) }, qty: item.qty, price: item.offered_unit_price === null ? null : num(item.offered_unit_price), note: null }));
  const sub = lines.reduce((total, line) => total + num(prices[line.id]) * line.qty, 0);
  const savePrice = async () => {
    if (!detail.data || list.usingMock) return;
    if (!validUntil || validUntil < today()) return toast('تاريخ الصلاحية يجب ألا يسبق اليوم', 'red');
    if (lines.some((line) => prices[line.id] == null || prices[line.id] === '' || !Number.isFinite(Number(prices[line.id])) || Number(prices[line.id]) < 0)) return toast('أدخل سعراً صحيحاً لكل بند', 'red');
    const result = await run(() => quotationsApi.price(detail.data!.id, { items: lines.map((line) => ({ id: line.id, offered_unit_price: Number(prices[line.id]) })), valid_until: validUntil, admin_notes: adminNotes || null }), { toast, success: 'أُرسل التسعير للعميل', onFieldErrors: setErrors });
    if (result) { detail.setData(result); setView(mapQuote(result)); setPrice(false); list.reload(); }
  };
  const expireQuote = async () => {
    if (!view || list.usingMock || !detail.data) return;
    const result = await run(() => quotationsApi.expire(view.id), { toast, success: 'تم إنهاء صلاحية العرض' });
    if (result) { setExpire(false); setView(mapQuote(result)); detail.setData(result); list.reload(); }
  };

  return (
    <>
      <Card stg={3}>
        <div className="flex flex-wrap gap-2 mb-4">
          <FSelect
            value={st}
            onChange={setSt}
            placeholder="الحالة"
            options={Object.entries(QUOTE_STATUS).map(([v, s]) => ({ value: v, label: s.label }))}
          />
          <FSelect value={cu} onChange={setCu} placeholder="العميل" options={(customers.data ?? []).map((c) => ({ value: String(c.id), label: c.company_name || c.name }))} />
        </div>
        <RemoteNote remote={list} />
        <DataTable
          rows={rows}
          onRow={setView}
          cols={[
            { h: 'رقم العرض', r: (q: QuoteRow) => <span className="num font-semibold tx1">{q.no}</span> },
            {
              h: 'العميل / الشركة',
              r: (q: QuoteRow) => (
                <div className="flex items-center gap-2">
                  <Avatar name={q.company} tone={q.id} size={28} />
                  <div className="leading-tight">
                    <div className="font-medium tx1">{q.company}</div>
                    <div className="text-[11px] tx3">{q.cust}</div>
                  </div>
                </div>
              ),
            },
            { h: 'الحالة', r: (q: QuoteRow) => <StatusBadge map={QUOTE_STATUS} value={q.status} /> },
            {
              h: 'الإجمالي',
              r: (q: QuoteRow) =>
                q.total ? (
                  <span className="font-semibold">{fmtMoney(q.total)}</span>
                ) : (
                  <span className="tx3 text-[11.5px]">لم يُسعّر</span>
                ),
            },
            {
              h: 'الصلاحية',
              r: (q: QuoteRow) => (q.valid ? <Num className="tx2">{q.valid}</Num> : <span className="tx3">—</span>),
            },
            { h: 'التاريخ', r: (q: QuoteRow) => <Num className="tx2">{q.date}</Num> },
            {
              h: '',
              r: (q: QuoteRow) =>
                ['requested', 'priced'].includes(q.status) && (
                  <RowActions>
                    <button
                      className="btn btn-accent btn-xs"
                      disabled={list.usingMock}
                      onClick={() => {
                        setView(q);
                        setPrice(true);
                      }}
                    >
                      تسعير
                    </button>
                  </RowActions>
                ),
            },
          ]}
        />
        <Pager total={list.data?.meta.total ?? 0} page={page} per={20} onPage={setPage} />
      </Card>
      {view && !price && (
        <Modal
          open
          onClose={() => setView(null)}
          width={760}
          icon="quote"
          title={
            <span className="flex items-center gap-2">
              <span className="num">{view.no}</span>
              <StatusBadge map={QUOTE_STATUS} value={view.status} />
            </span>
          }
          sub={
            <>
              {view.company} · {view.cust}
            </>
          }
          footer={
            <>
              {['priced', 'requested'].includes((detail.data ? quoteStatus(detail.data.status) : view.status)) && (
                <button className="btn btn-ghost me-auto" disabled={busy || detail.loading || !detail.data || list.usingMock} onClick={() => setExpire(true)}>
                  <Icon name="clock" size={13} />
                  إنهاء الصلاحية
                </button>
              )}
              {['requested', 'priced'].includes(view.status) && (
                <button className="btn btn-dark" disabled={detail.loading || !detail.data || list.usingMock} onClick={() => setPrice(true)}>
                  {view.status === 'priced' ? 'إعادة التسعير' : 'تسعير العرض'}
                </button>
              )}
            </>
          }
        >
          <div className="space-y-4 pb-2">
            <RemoteNote remote={detail} />
            {view.status === 'priced' && (
              <Note tone="blue" icon="info">
                بانتظار رد التاجر — القبول أو الرفض يتم من بوابة الجملة.
              </Note>
            )}
            {view.order && (
              <div className="v-sub p-3 flex items-center justify-between text-[12.5px]">
                <span className="flex items-center gap-2">
                  <Icon name="link" size={14} className="accent" />
                  تحول إلى طلب
                </span>
                <span className="num font-semibold accent underline underline-offset-4">{view.order}</span>
              </div>
            )}
            <div className="v-sub p-3.5">
              <div className="lbl mb-1">ملاحظات العميل</div>
              <div className="text-[12.5px] tx1">
                {detail.data?.customer_notes || '—'}
              </div>
            </div>
            <DataTable
              compact
              rows={lines}
              cols={[
                {
                  h: 'البند',
                  r: (l: any) => (
                    <div className="leading-tight">
                      <div className="font-medium tx1">{l.v.name}</div>
                      <div className="text-[11px] tx3 num">{l.v.sku}</div>
                      {l.note && <div className="text-[11px] tx2 mt-0.5">«{l.note}»</div>}
                    </div>
                  ),
                },
                {
                  h: 'الكمية',
                  align: 'center',
                  r: (l: any) => <Num className="font-semibold">{l.qty}</Num>,
                },
                {
                  h: 'السعر المعروض',
                  r: (l: any) => (l.price !== null ? fmtMoney(l.price) : <span className="tx3">—</span>),
                },
                {
                  h: 'الإجمالي',
                  r: (l: any) => (l.price !== null ? <span className="font-semibold">{fmtMoney(l.price * l.qty)}</span> : <span className="tx3">—</span>),
                },
              ]}
            />
            {view.total !== null && (
              <div className="v-sub p-4 flex items-center justify-between">
                <span className="tx2">إجمالي العرض المُقدَّم</span>
                <span className="font-display text-[22px] font-bold num">{fmtMoney(view.total)}</span>
              </div>
            )}
          </div>
        </Modal>
      )}
      {price && view && (
        <Modal
          open
          onClose={() => setPrice(false)}
          title={'تسعير ' + view.no}
          icon="quote"
          width={800}
          footer={
            <>
              <button className="btn btn-soft" onClick={() => setPrice(false)}>
                إلغاء
              </button>
              <button
                className="btn btn-dark"
                disabled={busy || detail.loading || !detail.data} onClick={savePrice}
              >
                إرسال التسعير للعميل
              </button>
            </>
          }
        >
          <div className="space-y-4">
            <div className="grid grid-cols-2 gap-3">
              <Field label="صالح حتى تاريخ" req err={errors.valid_until}>
                <input type="date" className="inp" value={validUntil} onChange={(e) => setValidUntil(e.target.value)} />
              </Field>
              <Field label="شروط الدفع">
                <select className="inp" disabled title="شروط الدفع تُدار من بوابة العميل">
                  <option>سداد نقدي عند الاستلام</option>
                  <option>تحويل بنكي مسبق</option>
                  <option>أجل 30 يومًا</option>
                </select>
              </Field>
            </div>
            <div className="v-sub p-2">
              <div className="grid grid-cols-12 gap-2 px-2 py-1 text-[11px] tx3">
                <span className="col-span-5">البند المطلوب</span>
                <span className="col-span-2 text-center">الكمية</span>
                <span className="col-span-2 text-end">سعر الوحدة</span>
                <span className="col-span-3 text-end">الإجمالي</span>
              </div>
              {lines.map((l, i) => (
                <div key={i} className="grid grid-cols-12 gap-2 items-center px-2 py-1.5 v-bb">
                  <div className="col-span-5 leading-tight">
                    <div className="text-[12.5px] font-medium clamp1">{l.v.name}</div>
                    <div className="text-[10.5px] tx3 num">{l.v.sku}</div>
                  </div>
                  <Num className="col-span-2 text-center font-semibold">{l.qty}</Num>
                  <input
                    type="number"
                    step="0.01"
                    className="inp inp-sm col-span-2 num text-end !bg-[var(--bg-card)]"
                    min="0" value={prices[l.id] ?? ''} onChange={(e) => setPrices((prev) => ({ ...prev, [l.id]: e.target.value }))}
                  />
                  <span className="col-span-3 text-end font-semibold num text-[12px]">
                    {fmtMoney(num(prices[l.id]) * l.qty)}
                  </span>
                </div>
              ))}
            </div>
            <div className="v-sub p-3.5 flex items-center justify-between">
              <span className="font-semibold tx1">المجموع التقديري</span>
              <span className="font-display text-[20px] font-bold num">{fmtMoney(sub)}</span>
            </div>
            <TextArea label="ملاحظات العرض للعميل" placeholder="أي شروط توريد أو خصومات إضافية" value={adminNotes} onChange={setAdminNotes} />
            {Object.values(errors).map((message, i) => <Note key={i} tone="red">{message}</Note>)}
          </div>
        </Modal>
      )}
      <ConfirmModal open={expire} onClose={() => setExpire(false)} title="إنهاء صلاحية العرض" text="سيُغلق عرض السعر ولن يتمكن العميل من قبوله." cta="إنهاء الصلاحية" onConfirm={expireQuote} />
    </>
  );
}

export function NoticesTab() {
  const toast = useToast();
  const { busy, run } = useAction();
  const [st, setSt] = useState('');
  const [cu, setCu] = useState('');
  const [page, setPage] = useState(1);
  const [selected, setSelected] = useState<PaymentNoticeRow | null>(null);
  const [mode, setMode] = useState<'approve' | 'reject' | null>(null);
  const [treasuryId, setTreasuryId] = useState('');
  const [notes, setNotes] = useState('');
  const [errors, setErrors] = useState<Record<string, string>>({});
  useEffect(() => { setPage(1); setSelected(null); }, [st, cu]);
  useEffect(() => { setNotes(''); setTreasuryId(''); setErrors({}); }, [mode, selected?.id]);
  const list = useRemote((s) => paymentNoticesApi.list({ page, per_page: 20, status: st === 'pending' ? 'pending_review' : st || undefined, customer_id: cu || undefined }, s).then((p) => ({ ...p, data: p.data.map(mapNotice) })), [page, st, cu], { mock: () => mockPage(NOTICES) });
  const detail = useRemote((s) => paymentNoticesApi.show(selected!.id, s), [selected?.id], { enabled: !!selected });
  const treasures = useRemote((s) => allPages((page) => treasuriesApi.list({ page, per_page: 100, is_active: true }, s)), []);
  const customers = useRemote((s) => allPages((page) => opsApi.get('/api/v1/admin/customers', { params: { page, type: 'wholesale', per_page: 100 }, signal: s }).then((r) => asPage<{ id: number; name: string; company_name?: string }>(r))), []);
  const nameOf = (id: number) => treasures.data?.find((t) => t.id === id)?.name ?? (USE_MOCK ? trName(id) : '#' + id);
  const rows = list.data?.data ?? [];
  const sel = detail.data && detail.data.id === selected?.id ? mapNotice(detail.data) : selected;
  const setSel = setSelected;
  useEffect(() => { if (!selected && rows.length) setSelected(rows[0]); }, [list.data, selected]);
  const review = async (approve: boolean) => {
    if (!sel || list.usingMock || !detail.data) return;
    if (!approve && !notes.trim()) return toast('سبب الرفض مطلوب', 'red');
    const result = await run(() => approve ? paymentNoticesApi.approve(sel.id, { treasury_id: treasuryId ? Number(treasuryId) : null, admin_notes: notes || null }) : paymentNoticesApi.reject(sel.id, notes), { toast, success: approve ? 'تم اعتماد إشعار الدفع' : 'تم رفض الإشعار', onFieldErrors: setErrors });
    if (result) { detail.setData(result); setSelected(mapNotice(result)); setMode(null); list.reload(); treasures.reload(); }
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-5">
      <Card stg={3} className="lg:col-span-5 space-y-3">
        <div className="flex flex-wrap gap-2">
          <FSelect
            value={st}
            onChange={setSt}
            placeholder="كل الحالات"
            options={Object.entries(NOTICE_STATUS).map(([v, s]) => ({ value: v, label: s.label }))}
          />
          <FSelect value={cu} onChange={setCu} placeholder="العميل" options={(customers.data ?? []).map((c) => ({ value: String(c.id), label: c.company_name || c.name }))} />
        </div>
        <RemoteNote remote={list} />
        <div className="space-y-2">
          {rows.length === 0 && <Empty icon="bank" title="لا توجد إشعارات" />}
          {(rows as PaymentNoticeRow[]).map((n: PaymentNoticeRow) => (
            <button
              key={n.id}
              disabled={list.usingMock} onClick={() => setSel(n)}
              className="w-full text-start v-sub p-3.5 transition flex items-start gap-3 rounded-[14px]"
              style={sel?.id === n.id ? { outline: '2px solid var(--accent)', background: 'var(--bg-card)' } : {}}
            >
              <Avatar name={n.company} tone={n.id} size={34} />
              <div className="flex-1 min-w-0">
                <div className="flex items-center justify-between gap-2">
                  <span className="font-semibold text-[12.5px] tx1 clamp1">{n.company}</span>
                  <StatusBadge map={NOTICE_STATUS} value={n.status} />
                </div>
                <div className="flex items-center justify-between mt-1.5">
                  <span className="text-[11px] tx3">
                    <span className="num">{n.no}</span> · {NOTICE_METHODS[n.method as keyof typeof NOTICE_METHODS]}
                  </span>
                  <span className="font-semibold text-[12.5px]">{fmtMoney(n.amount, 0)}</span>
                </div>
              </div>
            </button>
          ))}
        </div>
        <Pager total={list.data?.meta.total ?? 0} page={page} per={20} onPage={setPage} />
      </Card>
      {sel && (
        <Card stg={4} className="lg:col-span-7">
          <RemoteNote remote={detail} />
          <div className="flex items-start justify-between gap-3 mb-4">
            <div>
              <div className="flex items-center gap-2">
                <span className="font-display text-[18px] font-semibold num">{sel.no}</span>
                <StatusBadge map={NOTICE_STATUS} value={sel.status} />
              </div>
              <div className="text-[12px] tx2 mt-1">
                {sel.company} · {sel.cust}
              </div>
            </div>
            {sel.status === 'pending' && (
              <div className="flex gap-2">
                <button className="btn btn-danger btn-sm" onClick={() => setMode('reject')}>
                  رفض
                </button>
                <button className="btn btn-dark btn-sm" onClick={() => setMode('approve')}>
                  <Icon name="check" size={13} />
                  موافقة
                </button>
              </div>
            )}
          </div>
          <div className="v-orange rounded-[18px] p-4 flex items-center justify-between mb-4">
            <div>
              <div className="text-[12px] text-white/85">المبلغ</div>
              <div className="font-display text-[26px] font-bold num ltr">
                {fmtNum(sel.amount)} <span className="text-[13px] opacity-80">EGP</span>
              </div>
            </div>
            <span className="px-3 py-1 rounded-full bg-white/20 text-[12px] font-semibold">
              {NOTICE_METHODS[sel.method as keyof typeof NOTICE_METHODS]}
            </span>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-8">
            <KV
              items={[
                ['البنك', sel.bank],
                ['المرجع', <Num>{sel.ref}</Num>],
                ['تاريخ التحويل', <Num>{sel.date}</Num>],
              ]}
            />
            <KV
              items={[
                ['الطلب المرتبط', sel.order ? <Num className="accent">{sel.order}</Num> : null],
                ['الخزينة', sel.tr ? nameOf(sel.tr) : null],
                ['ملاحظات المراجعة', sel.review],
              ]}
            />
          </div>
          <div className="mt-4">
            {sel.file ? (
              <div className="v-sub p-3 flex items-center gap-3">
                <div
                  className="w-16 h-20 rounded-[10px] bg-[var(--bg-card)] flex items-center justify-center tx3 border"
                  style={{ borderColor: 'var(--border-subtle)' }}
                >
                  <Icon name="image" size={20} />
                </div>
                <div className="flex-1">
                  <div className="text-[12.5px] font-medium tx1">إيصال التحويل</div>
                  <div className="text-[11px] tx3 num">{sel.no}</div>
                </div>
                <button className="btn btn-soft btn-xs" disabled={busy} onClick={() => run(() => paymentNoticesApi.openReceipt(sel.id), { toast })}>
                  <Icon name="eye" size={12} />
                  معاينة
                </button>
                <button className="btn btn-soft btn-xs" disabled={busy || list.usingMock} onClick={() => run(() => paymentNoticesApi.downloadReceipt(sel.id), { toast })}>
                  <Icon name="download" size={12} />
                  تنزيل
                </button>
              </div>
            ) : (
              <div className="v-sub p-3 text-[12px] tx3 text-center">لم يُرفق إيصال</div>
            )}
          </div>
        </Card>
      )}
      <Modal
        open={mode === 'approve'}
        onClose={() => setMode(null)}
        title="الموافقة على إشعار السداد"
        icon="check"
        tone="green"
        width={480}
        footer={
          <>
            <button className="btn btn-soft" onClick={() => setMode(null)}>
              إلغاء
            </button>
            <button
              className="btn btn-dark"
              disabled={busy || detail.loading || !detail.data} onClick={() => review(true)}
            >
              موافقة
            </button>
          </>
        }
      >
        <div className="space-y-4 pb-2">
          <Field label="الخزينة" hint="اختياري — الخزينة التي استقبلت المبلغ" err={errors.treasury_id}>
            <select className="inp" value={treasuryId} onChange={(e) => setTreasuryId(e.target.value)}>
              <option value="">بدون</option>
              {(treasures.data ?? []).map((t) => (
                <option key={t.id} value={t.id}>{t.name}</option>
              ))}
            </select>
          </Field>
          <TextArea label="ملاحظات الإدارة" value={notes} onChange={setNotes} />
          {errors.admin_notes && <Note tone="red">{errors.admin_notes}</Note>}
        </div>
      </Modal>
      <Modal
        open={mode === 'reject'}
        onClose={() => setMode(null)}
        title="رفض إشعار السداد"
        icon="ban"
        tone="red"
        width={460}
        footer={
          <>
            <button className="btn btn-soft" onClick={() => setMode(null)}>
              إلغاء
            </button>
            <button
              className="btn btn-danger"
              disabled={busy || detail.loading || !detail.data} onClick={() => review(false)}
            >
              رفض
            </button>
          </>
        }
      >
        <div className="pb-2">
          <TextArea label="ملاحظات الإدارة" req placeholder="وضّح سبب الرفض للتاجر" value={notes} onChange={setNotes} />
          {errors.admin_notes && <Note tone="red">{errors.admin_notes}</Note>}
        </div>
      </Modal>
    </div>
  );
}<?php

declare(strict_types=1);

namespace App\Http\Controllers\Api\V1\Wholesale;

use App\Enums\SalesChannel;
use App\Exceptions\BusinessException;
use App\Exports\WholesalePriceListExport;
use App\Http\Controllers\Controller;
use App\Models\Customer;
use App\Models\Product;
use App\Models\ProductVariant;
use App\Models\StockLevel;
use App\Services\PricingService;
use App\Services\SearchTerm;
use App\Services\SettingService;
use App\Services\WholesalePriceListService;
use Barryvdh\DomPDF\Facade\Pdf;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;
use Illuminate\Validation\Rule;
use Maatwebsite\Excel\Facades\Excel;
use Symfony\Component\HttpFoundation\BinaryFileResponse;
use Symfony\Component\HttpFoundation\Response;

class ProductController extends Controller
{
    public function __construct(
        private readonly PricingService $pricing,
        private readonly WholesalePriceListService $priceList,
        private readonly SettingService $settings,
    ) {}

    /**
     * Wholesale catalog: resolves merchant tier pricing, base price, and active branch availability.
     */
    public function index(Request $request): JsonResponse
    {
        $filters = $request->validate([
            'search' => ['nullable', 'string', 'max:255'],
            'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
        ]);

        /** @var Customer $customer */
        $customer = $request->user();

        $products = Product::query()
            // Restrict wholesale catalog to published products on active category trees in wholesale channels.
            ->where('status', 'published')
            ->whereIn('sales_channel', [SalesChannel::Wholesale, SalesChannel::Both])
            ->whereHas('category', fn ($q) => $q->where('is_active', true)
                ->whereDoesntHave('parent', fn ($parent) => $parent->where('is_active', false)
                    ->orWhereHas('parent', fn ($ancestor) => $ancestor->where('is_active', false))))
            ->with(['media', 'variants' => fn ($q) => $q->where('is_active', true)->with('media')])
            ->when($filters['search'] ?? null, function ($q, $v): void {
                $pattern = SearchTerm::pattern($v);
                $q->where(fn ($sub) => $sub
                    ->whereLike('name_ar', $pattern, caseSensitive: false)
                    ->orWhereLike('name_en', $pattern, caseSensitive: false)
                    ->orWhereHas('variants', fn ($qv) => $qv->whereLike('sku', $pattern, caseSensitive: false)));
            })
            ->latest('id')
            ->paginate($filters['per_page'] ?? 15);

        $variantIds = $products->getCollection()
            ->flatMap(fn (Product $product) => $product->variants->pluck('id'))
            ->all();

        // Calculate available stock across active branches only.
        $availability = StockLevel::query()
            ->join('branches', 'branches.id', '=', 'stock_levels.branch_id')
            ->where('branches.is_active', true)
            ->whereIn('product_variant_id', $variantIds)
            ->groupBy('product_variant_id')
            ->selectRaw('product_variant_id, SUM(available) AS total_available')
            ->pluck('total_available', 'product_variant_id')
            ->map(fn ($v) => (float) $v)
            ->all();

        // Preload customer price-list context once for all variants in the page to prevent repeated queries.
        $pricingCtx = $this->pricing->contextFor($customer, $variantIds);

        $data = $products->getCollection()->map(function (Product $product) use ($customer, $availability, $pricingCtx): array {
            $images = $product->catalogImages();
            $first = $images->first();
            $image = $first !== null
                ? ($first->hasGeneratedConversion('thumb') ? $first->getUrl('thumb') : $first->getUrl())
                : null;

            return [
                'id' => $product->id,
                'name' => $product->name_ar,
                'name_en' => $product->name_en,
                'image' => $image,
                'variants' => $product->variants->map(function (ProductVariant $variant) use ($customer, $availability, $pricingCtx, $image): array {
                    try {
                        $resolved = $this->pricing->resolve($variant, $customer, 1, null, $pricingCtx);
                        $price = $resolved['unit_price'];
                        $base = $resolved['base_price'];
                        $tiers = $this->pricing->tiersFor($variant, $customer, $pricingCtx);
                    } catch (BusinessException) {
                        $price = null;
                        $base = $variant->retail_price !== null ? (float) $variant->retail_price : null;
                        $tiers = [];
                    }

                    return [
                        'id' => $variant->id,
                        'sku' => $variant->sku,
                        'barcode' => $variant->barcode,
                        'label' => $variant->displayLabel(),
                        'image' => $image,
                        'base_price' => $base,
                        'your_price' => $price,
                        'tier_prices' => $tiers,
                        'available_qty' => $availability[$variant->id] ?? 0.0,
                    ];
                })->values()->all(),
            ];
        })->values()->all();

        return response()->json([
            'data' => $data,
            'meta' => [
                'current_page' => $products->currentPage(),
                'last_page' => $products->lastPage(),
                'per_page' => $products->perPage(),
                'total' => $products->total(),
            ],
        ]);
    }

    /**
     * Export merchant price list as formatted Excel or branded PDF with 30-day validity.
     */
    public function exportPriceList(Request $request): BinaryFileResponse|Response
    {
        $validated = $request->validate([
            'format' => ['required', Rule::in(['pdf', 'xlsx'])],
        ]);

        /** @var Customer $customer */
        $customer = $request->user();
        $rows = $this->priceList->rows($customer);

        if ($validated['format'] === 'xlsx') {
            return Excel::download(new WholesalePriceListExport($rows), 'price-list.xlsx');
        }

        $validUntil = now()->addDays(30);

        return Pdf::loadView('pdfs.wholesale_price_list', [
            'company_name' => (string) $this->settings->get('company_name', 'Alfarid'),
            'customer' => $customer,
            'rows' => $rows,
            'valid_until' => $validUntil,
            'generated_at' => now(),
        ])->download('price-list.pdf');
    }
}<?php

declare(strict_types=1);

namespace App\Http\Controllers\Api\V1;

use App\Http\Controllers\Controller;
use App\Models\Customer;
use App\Models\ReturnRequestItem;
use App\Models\SupplierDelivery;
use App\Models\SupplierInvoice;
use App\Models\SupplierUser;
use App\Models\User;
use App\Models\WholesalePaymentNotice;
use App\Services\BranchAccess;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\RedirectResponse;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Storage;
use Symfony\Component\HttpFoundation\HeaderUtils;
use Symfony\Component\HttpKernel\Exception\HttpException;
use Throwable;

/**
 * Securely streams private file attachments with strict role-based access control and nosniff headers.
 */
class AttachmentController extends Controller
{
    public function __construct(private readonly BranchAccess $branchAccess) {}

    /**
     * Streams inspection photos attached to a return request item.
     *
     * @param  Request  $request  Authorized request
     * @param  int  $returnItem  Return item identifier
     * @param  int  $attachment  Attachment array index
     * @return RedirectResponse Short-lived signed R2 URL
     */
    public function returnFile(Request $request, int $returnItem, int $attachment): RedirectResponse|JsonResponse
    {
        $actor = $request->user();
        $query = ReturnRequestItem::query();
        if ($actor instanceof Customer) {
            $query->whereHas('returnRequest', fn ($q) => $q->where('customer_id', $actor->id));
        } else {
            abort_unless($actor instanceof User && $actor->can('returns.view'), 403);
        }
        $item = $query->findOrFail($returnItem);
        if ($actor instanceof User) {
            $return = $item->returnRequest;
            $branchId = $return->branch_id ?? $return->order?->allocated_branch_id;
            if ($branchId === null) {
                $this->branchAccess->assertCentralAccess($actor);
            } else {
                $this->branchAccess->assertBranch($actor->id, (int) $branchId);
            }
        }

        return $this->download($request, ($item->attachments ?? [])[$attachment] ?? null);
    }

    /**
     * Streams supplier invoice PDF attachment.
     *
     * @param  Request  $request  Authorized request
     * @param  int  $invoice  Supplier invoice identifier
     * @return RedirectResponse Short-lived signed R2 URL
     */
    public function invoice(Request $request, int $invoice): RedirectResponse|JsonResponse
    {
        $actor = $request->user();
        $query = SupplierInvoice::query()->with('purchaseOrder');
        if ($actor instanceof SupplierUser) {
            $query->where('supplier_id', $actor->supplier_id)->where('status', '!=', 'draft');
        } else {
            abort_unless($actor instanceof User && $actor->can('purchases.view'), 403);
        }

        $model = $query->findOrFail($invoice);
        if ($actor instanceof User) {
            // Prevent branch-confined staff from accessing procurement documents of other branches.
            $branchId = $model->purchaseOrder?->branch_id;
            if ($branchId === null) {
                $this->branchAccess->assertCentralAccess($actor);
            } else {
                $this->branchAccess->assertBranch($actor->id, (int) $branchId);
            }
        }

        return $this->download($request, $model->attachment_path);
    }

    /**
     * Streams delivery receipt document attached to a procurement delivery.
     *
     * @param  Request  $request  Authorized request
     * @param  int  $delivery  Delivery identifier
     * @return RedirectResponse Short-lived signed R2 URL
     */
    public function delivery(Request $request, int $delivery): RedirectResponse|JsonResponse
    {
        $actor = $request->user();
        $query = SupplierDelivery::query()->with('purchaseOrder');
        if ($actor instanceof SupplierUser) {
            $query->where('supplier_id', $actor->supplier_id);
        } else {
            abort_unless($actor instanceof User && $actor->can('purchases.view'), 403);
        }

        $model = $query->findOrFail($delivery);
        if ($actor instanceof User) {
            // Prevent cross-branch procurement document retrieval.
            $branchId = $model->purchaseOrder?->branch_id;
            if ($branchId === null) {
                $this->branchAccess->assertCentralAccess($actor);
            } else {
                $this->branchAccess->assertBranch($actor->id, (int) $branchId);
            }
        }

        return $this->download($request, $model->invoice_file_path);
    }

    /**
     * Streams bank transfer receipt attached to a wholesale payment notice.
     *
     * @param  Request  $request  Authorized request
     * @param  int  $notice  Payment notice identifier
     * @return RedirectResponse Short-lived signed R2 URL (H3)
     */
    public function paymentNotice(Request $request, int $notice): RedirectResponse|JsonResponse
    {
        $actor = $request->user();
        $query = WholesalePaymentNotice::query();
        if ($actor instanceof Customer) {
            $query->where('customer_id', $actor->id);
        } else {
            abort_unless($actor instanceof User && $actor->can('payment_notices.view'), 403);
        }

        $model = $query->with('order')->findOrFail($notice);
        if ($actor instanceof User) {
            $branchId = $model->order?->allocated_branch_id;
            if ($branchId === null) {
                $this->branchAccess->assertCentralAccess($actor);
            } else {
                $this->branchAccess->assertBranch($actor->id, (int) $branchId);
            }
        }

        return $this->download($request, $model->receipt_file_path);
    }

    private function download(Request $request, ?string $path): RedirectResponse|JsonResponse
    {
        // Avoid proxying storage payload through PHP-FPM workers to prevent connection exhaustion.
        // Instead, authorize locally and redirect to a short-lived (2-minute) signed R2 URL.
        abort_if($path === null, 404);

        try {
            if (! $request->boolean('signed') && ! Storage::disk('r2')->exists($path)) {
                abort(404);
            }

            $url = Storage::disk('r2')->temporaryUrl(
                $path,
                now()->addMinutes(2),
                [
                    'ResponseContentDisposition' => HeaderUtils::makeDisposition('attachment', basename($path), 'attachment'),
                    // Prevent intermediate proxies or shared caches from storing private documents.
                    'ResponseCacheControl' => 'private, max-age=120',
                ]
            );
        } catch (Throwable $exception) {
            if ((int) ($exception->getCode() ?: 0) === 404 || $exception instanceof HttpException) {
                throw $exception;
            }

            // R2 outage (throw => true) is a dependency failure, not a bug.
            abort(503, 'Document storage is temporarily unavailable.');
        }

        if ($request->boolean('signed')) {
            return response()->json(['url' => $url])->header('Cache-Control', 'private, no-store');
        }

        return redirect()->to($url)->header('Cache-Control', 'private, no-store');
    }
}<?php

declare(strict_types=1);

namespace App\Services;

use App\Enums\OrderStatus;
use App\Enums\TreasuryTransactionType;
use App\Enums\TreasuryType;
use App\Enums\WholesalePaymentNoticeStatus;
use App\Events\PaymentNoticeReviewed;
use App\Events\PaymentNoticeSubmitted;
use App\Exceptions\BusinessException;
use App\Models\Customer;
use App\Models\Order;
use App\Models\ReturnRequest;
use App\Models\Treasury;
use App\Models\User;
use App\Models\WholesalePaymentAllocation;
use App\Models\WholesalePaymentNotice;
use Brick\Math\BigDecimal;
use Brick\Math\RoundingMode;
use Carbon\Carbon;
use Illuminate\Database\UniqueConstraintViolationException;
use Illuminate\Http\UploadedFile;
use Illuminate\Support\Facades\DB;

/**
 * Manages wholesale customer payment notices, credit balance calculation, and order allocations.
 */
class WholesalePaymentNoticeService
{
    public function __construct(
        private readonly SettingService $settings,
        private readonly TreasuryService $treasury,
    ) {}

    /**
     * Submits a new payment notice with an uploaded proof receipt.
     *
     * @param  Customer  $customer  Submitting wholesale customer
     * @param  array<string, mixed>  $data  Notice metadata
     * @param  UploadedFile  $receipt  Proof of payment file
     * @return WholesalePaymentNotice Created pending notice
     *
     * @throws BusinessException If linked order is invalid or capacity exceeded
     */
    public function create(Customer $customer, array $data, UploadedFile $receipt): WholesalePaymentNotice
    {
        return PrivateAttachments::transaction(function (PrivateAttachments $files) use ($customer, $data, $receipt): WholesalePaymentNotice {
            // Serialize free and linked submissions for the same customer before
            // checking the bank reference, including requests with different files.
            Customer::query()->lockForUpdate()->findOrFail($customer->id);
            $reference = trim($data['reference_number']);
            if (WholesalePaymentNotice::query()->where('customer_id', $customer->id)
                ->whereReferenceNumber($reference)->exists()) {
                throw new BusinessException('رقم مرجع السداد مسجل بالفعل لهذا التاجر.', [], 409);
            }

            $amount = BigDecimal::of((string) $data['amount'])->toScale(2, RoundingMode::HalfUp);
            $transferDate = Carbon::parse((string) $data['transfer_date'])->toDateString();
            $crossCustomer = WholesalePaymentNotice::query()
                ->where('customer_id', '!=', $customer->id)
                ->where('status', '!=', WholesalePaymentNoticeStatus::Rejected->value)
                ->whereReferenceNumber($reference)
                ->where('amount', (string) $amount)
                ->whereDate('transfer_date', $transferDate)
                ->first();
            if ($crossCustomer !== null) {
                throw new BusinessException("نفس المرجع والمبلغ والتاريخ مسجّلين لإشعار {$crossCustomer->notice_number} من حساب تاجر آخر.", [], 409);
            }

            $realPath = $receipt->getRealPath();
            if ($realPath === false) {
                throw new BusinessException('تعذر قراءة إيصال السداد.');
            }
            $hash = hash_file('sha256', $realPath);
            $sameReceipt = WholesalePaymentNotice::query()
                ->where('receipt_sha256', $hash)
                ->where('status', '!=', WholesalePaymentNoticeStatus::Rejected->value)
                ->first();
            if ($sameReceipt !== null) {
                throw new BusinessException("نفس الإيصال اترفع قبل كده ({$sameReceipt->notice_number}).", [], 409);
            }

            $order = null;

            if (! empty($data['order_id'])) {
                // Pessimistic lock inside transaction serializes concurrent submissions against remaining balance.
                $order = $this->assertCreditableOrder($customer, (int) $data['order_id']);
                $this->assertOrderCapacity($order, (string) $data['amount']);
            }

            $path = $files->store($receipt, "wholesale_payment_notices/{$customer->id}");

            try {
                $notice = WholesalePaymentNotice::create([
                    'notice_number' => $this->settings->generateNextNumber('payment_notice'),
                    'customer_id' => $customer->id,
                    'order_id' => $order?->id,
                    'amount' => (string) $amount,
                    'payment_method' => $data['payment_method'],
                    'bank_name' => $data['bank_name'],
                    'reference_number' => $reference,
                    'transfer_date' => $transferDate,
                    'receipt_file_path' => $path,
                    'receipt_sha256' => $hash,
                    'status' => WholesalePaymentNoticeStatus::PendingReview,
                ]);
            } catch (UniqueConstraintViolationException) {
                throw new BusinessException('نفس الإيصال اترفع قبل كده.', [], 409);
            }

            PaymentNoticeSubmitted::dispatch($notice);

            return $notice;
        }, [[$receipt, 'wholesale_payment_notices/'.$customer->id]]);
    }

    /**
     * Computes the current net debt for a wholesale customer (negative implies credit balance).
     *
     * @param  Customer  $customer  Wholesale customer
     * @return float Current outstanding debt or negative advance credit
     */
    public function outstandingBalance(Customer $customer): float
    {
        return (float) (string) $this->outstandingBalanceDecimal($customer);
    }

    /**
     * @return array{debt: string, linked_open_notices: string, free_pool: string, allocated: string, floating_credit: string, outstanding: string}
     */
    public function balanceBreakdown(Customer $customer): array
    {
        $debt = BigDecimal::of((string) Order::query()
            ->where('customer_id', $customer->id)
            ->where('payment_method', 'credit')
            ->where('payment_status', 'unpaid')
            ->where('status', '!=', OrderStatus::Cancelled->value)
            ->sum('grand_total'))->toScale(2, RoundingMode::HalfUp);

        // Fully paid orders and their linked notices are excluded to avoid double deduction.
        $linkedOpen = BigDecimal::of((string) WholesalePaymentNotice::query()
            ->where('customer_id', $customer->id)
            ->where('status', WholesalePaymentNoticeStatus::Approved->value)
            ->whereNotNull('order_id')
            ->whereExists(function ($exists): void {
                $exists->selectRaw('1')->from('orders as o')
                    ->whereColumn('o.id', 'wholesale_payment_notices.order_id')
                    ->where('o.payment_status', 'unpaid')
                    ->where('o.status', '!=', OrderStatus::Cancelled->value);
            })
            ->sum('amount'))->toScale(2, RoundingMode::HalfUp);

        $free = $this->freePoolTotal($customer);
        $allocated = $this->allocatedTotal($customer);
        $floating = $free->minus($allocated)->toScale(2, RoundingMode::HalfUp);
        $outstanding = $debt->minus($linkedOpen)->minus($floating)->toScale(2, RoundingMode::HalfUp);

        return [
            'debt' => (string) $debt,
            'linked_open_notices' => (string) $linkedOpen,
            'free_pool' => (string) $free,
            'allocated' => (string) $allocated,
            'floating_credit' => (string) $floating,
            'outstanding' => (string) $outstanding,
        ];
    }

    private function outstandingBalanceDecimal(Customer $customer): BigDecimal
    {
        return BigDecimal::of($this->balanceBreakdown($customer)['outstanding']);
    }

    private function freeNoticesQuery(Customer $customer)
    {
        return WholesalePaymentNotice::query()
            ->where('customer_id', $customer->id)
            ->where('status', WholesalePaymentNoticeStatus::Approved->value)
            ->where(function ($query): void {
                $query->whereNull('order_id')
                    ->orWhereExists(function ($exists): void {
                        $exists->selectRaw('1')->from('orders as o')
                            ->whereColumn('o.id', 'wholesale_payment_notices.order_id')
                            ->where('o.status', OrderStatus::Cancelled->value);
                    });
            });
    }

    private function freePoolTotal(Customer $customer): BigDecimal
    {
        return BigDecimal::of((string) $this->freeNoticesQuery($customer)->sum('amount'))
            ->toScale(2, RoundingMode::HalfUp);
    }

    private function allocatedTotal(Customer $customer): BigDecimal
    {
        return BigDecimal::of((string) WholesalePaymentAllocation::query()
            ->whereHas('notice', fn ($q) => $q->where('customer_id', $customer->id))
            ->whereHas('order', fn ($q) => $q->where('status', '!=', OrderStatus::Cancelled->value))
            ->sum('amount'))->toScale(2, RoundingMode::HalfUp);
    }

    /**
     * Generates a chronological statement of account including debits, credits, and opening balance.
     *
     * @param  Customer  $customer  Wholesale customer
     * @param  string|null  $from  Start date (inclusive, YYYY-MM-DD)
     * @param  string|null  $to  End date (inclusive, YYYY-MM-DD)
     * @return array{opening_balance: float, closing_balance: float, entries: list<array<string, mixed>>}
     */
    public function statement(Customer $customer, ?string $from = null, ?string $to = null): array
    {
        $entries = collect();

        Order::query()
            ->where('customer_id', $customer->id)
            ->where('payment_method', 'credit')
            ->where('status', '!=', OrderStatus::Cancelled->value)
            ->get(['id', 'order_number', 'grand_total', 'created_at'])
            ->each(fn (Order $order) => $entries->push([
                'date' => $order->created_at->copy(),
                'type' => 'debit',
                'description' => "طلب آجل {$order->order_number}",
                'reference' => $order->order_number,
                'amount' => (float) $order->grand_total,
            ]));

        WholesalePaymentNotice::query()
            ->where('customer_id', $customer->id)
            ->where('status', WholesalePaymentNoticeStatus::Approved->value)
            ->get(['id', 'notice_number', 'payment_method', 'amount', 'approved_at', 'transfer_date', 'updated_at'])
            ->each(fn (WholesalePaymentNotice $notice) => $entries->push([
                'date' => ($notice->approved_at ?? $notice->transfer_date ?? $notice->updated_at)->copy(),
                'type' => 'credit',
                'description' => "سداد {$notice->notice_number} ({$notice->payment_method->value})",
                'reference' => $notice->notice_number,
                'amount' => (float) $notice->amount,
            ]));

        ReturnRequest::query()
            ->where('customer_id', $customer->id)
            ->where('status', 'refunded')
            ->whereNotNull('refunded_at')
            ->get(['id', 'return_number', 'total_refund_amount', 'refunded_at'])
            ->each(fn (ReturnRequest $return) => $entries->push([
                'date' => $return->refunded_at->copy(),
                'type' => 'credit',
                'description' => "مرتجع مسترد {$return->return_number}",
                'reference' => $return->return_number,
                'amount' => (float) $return->total_refund_amount,
            ]));

        // Standard accounting convention: debits precede credits on identical dates.
        $sorted = $entries->sortBy([
            fn (array $a, array $b): int => $a['date']->startOfDay() <=> $b['date']->startOfDay(),
            fn (array $a, array $b): int => ($a['type'] === 'debit' ? 0 : 1) <=> ($b['type'] === 'debit' ? 0 : 1),
        ])->values();

        $fromDate = $from !== null ? Carbon::parse($from)->startOfDay() : null;
        $toDate = $to !== null ? Carbon::parse($to)->endOfDay() : null;

        $opening = 0.0;
        $running = 0.0;
        $result = [];
        foreach ($sorted as $entry) {
            $delta = $entry['type'] === 'debit' ? $entry['amount'] : -$entry['amount'];

            if ($fromDate !== null && $entry['date']->lt($fromDate)) {
                $opening += $delta;
                $running = $opening;

                continue;
            }
            if ($toDate !== null && $entry['date']->gt($toDate)) {
                continue;
            }

            $running += $delta;
            $result[] = [
                'date' => $entry['date']->toDateString(),
                'reference' => $entry['reference'],
                'description' => $entry['description'],
                'debit' => $entry['type'] === 'debit' ? number_format($entry['amount'], 2, '.', '') : '0.00',
                'credit' => $entry['type'] === 'credit' ? number_format($entry['amount'], 2, '.', '') : '0.00',
                'balance' => number_format($running, 2, '.', ''),
            ];
        }

        return [
            'opening_balance' => round($opening, 2),
            'closing_balance' => round($running, 2),
            'entries' => $result,
        ];
    }

    /**
     * Approves a payment notice, recording treasury receipt and allocating against open debt.
     *
     * @param  WholesalePaymentNotice  $notice  Target notice
     * @param  int  $adminId  Approving staff member ID
     * @param  int|null  $treasuryId  Destination treasury ID
     * @param  string|null  $adminNotes  Optional administrative review notes
     * @return WholesalePaymentNotice Updated notice instance
     *
     * @throws BusinessException If notice was reviewed, exceeds debt, or treasury is invalid
     */
    public function approve(WholesalePaymentNotice $notice, int $adminId, ?int $treasuryId = null, ?string $adminNotes = null): WholesalePaymentNotice
    {
        return DB::transaction(function () use ($notice, $adminId, $treasuryId, $adminNotes): WholesalePaymentNotice {
            $notice = WholesalePaymentNotice::query()->lockForUpdate()->findOrFail($notice->id);
            $customer = Customer::query()->lockForUpdate()->findOrFail($notice->customer_id);

            if ($notice->status !== WholesalePaymentNoticeStatus::PendingReview) {
                throw new BusinessException('إشعار السداد هذا تمت مراجعته من قبل.');
            }

            if ($notice->order_id !== null) {
                $order = Order::query()->lockForUpdate()->findOrFail($notice->order_id);
                if ($order->payment_status === 'paid') {
                    throw new BusinessException('الطلب المرتبط تم سداده بالفعل؛ لا يمكن اعتماد إشعار السداد.');
                }
            }

            // Decimal comparison avoids floating-point precision boundary errors.
            if (BigDecimal::of((string) $notice->amount)->compareTo($this->outstandingBalanceDecimal($customer)) > 0) {
                throw new BusinessException('مبلغ الإشعار أكبر من المديونية الآجلة الحالية للتاجر.');
            }

            $treasury = $this->resolveTreasury($treasuryId);
            app(BranchAccess::class)->assertTreasury($adminId, $treasury);

            $transaction = $this->treasury->record([
                'treasury_id' => $treasury->id,
                'type' => TreasuryTransactionType::CustomerReceipt,
                'amount' => (string) $notice->amount,
                'reference_type' => 'wholesale_payment_notice',
                'reference_id' => $notice->id,
                'created_by' => $adminId,
                'notes' => "اعتماد إشعار سداد جملة {$notice->notice_number}",
            ]);

            $notice->update([
                'status' => WholesalePaymentNoticeStatus::Approved,
                'reviewed_by' => $adminId,
                'approved_at' => now(),
                'admin_notes' => $adminNotes ?? $notice->admin_notes,
                'treasury_id' => $treasury->id,
                'treasury_transaction_id' => $transaction->id,
            ]);

            if ($notice->order_id !== null) {
                $this->settleOrderIfCovered((int) $notice->order_id, $adminId, $notice->notice_number);
            }
            $this->settleFreeNoticeFifo($customer, $adminId, $notice->notice_number);

            $notice = $notice->load(['customer', 'order', 'treasury', 'treasuryTransaction']);
            PaymentNoticeReviewed::dispatch($notice);

            return $notice;
        });
    }

    /**
     * Rejects a pending wholesale payment notice.
     *
     * @param  WholesalePaymentNotice  $notice  Target notice
     * @param  int  $adminId  Reviewing staff member ID
     * @param  string|null  $adminNotes  Reason for rejection
     * @return WholesalePaymentNotice Updated notice instance
     *
     * @throws BusinessException If notice was already reviewed
     */
    public function reject(WholesalePaymentNotice $notice, int $adminId, ?string $adminNotes = null): WholesalePaymentNotice
    {
        return DB::transaction(function () use ($notice, $adminId, $adminNotes): WholesalePaymentNotice {
            $notice = WholesalePaymentNotice::query()->lockForUpdate()->findOrFail($notice->id);

            if ($notice->status !== WholesalePaymentNoticeStatus::PendingReview) {
                throw new BusinessException('إشعار السداد هذا تمت مراجعته من قبل.');
            }

            $notice->update([
                'status' => WholesalePaymentNoticeStatus::Rejected,
                'reviewed_by' => $adminId,
                'admin_notes' => $adminNotes ?? $notice->admin_notes,
            ]);

            $notice = $notice->load(['customer', 'order']);
            PaymentNoticeReviewed::dispatch($notice);

            return $notice;
        });
    }

    /**
     * Reverses an approved notice: treasury reversal, allocation removal, and unpaid orders.
     * This is an audited financial action, not the 15-minute AI undo window.
     *
     * @throws BusinessException If the notice is not an approved, unreversed receipt.
     */
    public function reverse(WholesalePaymentNotice $notice, int $adminId, string $reason): WholesalePaymentNotice
    {
        $reason = trim($reason);
        if ($reason === '') {
            throw new BusinessException('سبب عكس الاعتماد مطلوب.');
        }

        return DB::transaction(function () use ($notice, $adminId, $reason): WholesalePaymentNotice {
            $notice = WholesalePaymentNotice::query()->lockForUpdate()->findOrFail($notice->id);
            Customer::query()->lockForUpdate()->findOrFail($notice->customer_id);

            if ($notice->status !== WholesalePaymentNoticeStatus::Approved || $notice->reversed_at !== null) {
                throw new BusinessException('لا يمكن عكس إشعار غير معتمد أو سبق عكسه.');
            }
            if ($notice->treasury_id === null) {
                throw new BusinessException('الإشعار من غير حركة خزينة، لا يمكن عكسه.');
            }

            $orderIds = WholesalePaymentAllocation::query()
                ->where('notice_id', $notice->id)
                ->pluck('order_id')
                ->all();
            if ($notice->order_id !== null) {
                $orderIds[] = (int) $notice->order_id;
            }
            WholesalePaymentAllocation::query()->where('notice_id', $notice->id)->delete();

            $reversal = $this->treasury->record([
                'treasury_id' => $notice->treasury_id,
                'type' => TreasuryTransactionType::CustomerReceiptReversal,
                'amount' => (string) BigDecimal::of((string) $notice->amount)->negated()->toScale(2, RoundingMode::HalfUp),
                'reference_type' => 'wholesale_payment_notice',
                'reference_id' => $notice->id,
                'created_by' => $adminId,
                'notes' => "عكس اعتماد إشعار سداد {$notice->notice_number}: {$reason}",
            ]);

            $notice->update([
                'status' => WholesalePaymentNoticeStatus::Reversed,
                'reversed_at' => now(),
                'reversal_treasury_transaction_id' => $reversal->id,
                'admin_notes' => $reason,
                'reviewed_by' => $adminId,
            ]);

            foreach (array_unique(array_map('intval', $orderIds)) as $orderId) {
                $this->reopenOrderIfUncovered($orderId, $adminId, $notice->notice_number);
            }

            return $notice->load(['customer', 'order', 'treasury']);
        });
    }

    private function assertCreditableOrder(Customer $customer, int $orderId): Order
    {
        // Lock order row to prevent concurrent notices from exceeding total order value.
        $order = Order::query()->where('customer_id', $customer->id)->lockForUpdate()->find($orderId);

        if ($order === null) {
            throw new BusinessException('الطلب المرتبط غير موجود أو لا يخص هذا التاجر.', [], 404);
        }

        if ($order->payment_method !== 'credit' || $order->payment_status !== 'unpaid'
            || $order->status === OrderStatus::Cancelled) {
            throw new BusinessException('الطلب المرتبط ليس طلب آجل غير مسدد.');
        }

        return $order;
    }

    private function assertOrderCapacity(Order $order, string $newAmount): void
    {
        // Include pending reviews so concurrent submissions cannot collectively overcommit the order.
        $committed = (string) WholesalePaymentNotice::query()
            ->where('order_id', $order->id)
            ->whereIn('status', [
                WholesalePaymentNoticeStatus::PendingReview->value,
                WholesalePaymentNoticeStatus::Approved->value,
            ])
            ->sum('amount');

        $total = BigDecimal::of($committed)->plus(BigDecimal::of($newAmount))->toScale(2, RoundingMode::HalfUp);
        if ($total->compareTo(BigDecimal::of((string) $order->grand_total)) > 0) {
            throw new BusinessException('مبلغ الإشعار يتجاوز المتبقي غير المسدد من هذا الطلب.');
        }
    }

    private function settleOrderIfCovered(int $orderId, int $adminId, string $noticeNumber): void
    {
        $order = Order::query()->lockForUpdate()->find($orderId);

        if ($order === null || $order->payment_status !== 'unpaid') {
            return;
        }

        $approved = (string) WholesalePaymentNotice::query()
            ->where('order_id', $order->id)
            ->where('status', WholesalePaymentNoticeStatus::Approved->value)
            ->sum('amount');

        if (BigDecimal::of($approved)->compareTo(BigDecimal::of((string) $order->grand_total)) >= 0) {
            $this->markOrderPaid($order, $adminId, "تسوية آجل بالإشعار {$noticeNumber}");
        }
    }

    /**
     * Read-only allocation preview. Uses the same planner as settlement and writes nothing.
     *
     * @return array{notice_id: int, notice_number: string, amount: string, linked_order: array<string, mixed>|null, fifo: list<array<string, mixed>>}
     */
    public function previewNoticeAllocation(WholesalePaymentNotice $notice, ?int $branchId = null): array
    {
        return DB::transaction(function () use ($notice, $branchId): array {
            $customer = Customer::query()->lockForUpdate()->findOrFail($notice->customer_id);
            $extra = '0.00';
            $linked = null;

            if ($notice->order_id !== null) {
                $order = Order::query()->lockForUpdate()->find($notice->order_id);
                if ($order !== null) {
                    $approved = BigDecimal::of((string) WholesalePaymentNotice::query()
                        ->where('order_id', $order->id)
                        ->where('status', WholesalePaymentNoticeStatus::Approved->value)
                        ->when($notice->status !== WholesalePaymentNoticeStatus::Approved, fn ($q) => $q->whereKeyNot($notice->id))
                        ->sum('amount'));
                    $incoming = $notice->status === WholesalePaymentNoticeStatus::Approved
                        ? BigDecimal::zero()
                        : BigDecimal::of((string) $notice->amount);
                    $already = BigDecimal::of((string) WholesalePaymentAllocation::query()->where('order_id', $order->id)->sum('amount'));
                    $remaining = BigDecimal::of((string) $order->grand_total)->minus($approved)->minus($incoming)->minus($already)
                        ->toScale(2, RoundingMode::HalfUp);
                    $linked = [
                        'order_id' => $order->id,
                        'order_number' => $order->order_number,
                        'remaining_after' => (string) ($remaining->isNegative() ? BigDecimal::zero()->toScale(2, RoundingMode::HalfUp) : $remaining),
                        'closes' => $remaining->isLessThanOrEqualTo('0'),
                    ];
                }
            } elseif ($notice->status !== WholesalePaymentNoticeStatus::Approved) {
                $extra = (string) BigDecimal::of((string) $notice->amount)->toScale(2, RoundingMode::HalfUp);
            }

            return [
                'notice_id' => $notice->id,
                'notice_number' => $notice->notice_number,
                'amount' => (string) $notice->amount,
                'linked_order' => $linked,
                'fifo' => $this->planFreeAllocation($customer, $extra, $branchId),
            ];
        });
    }

    /** @return list<array{notice_id: int, notice_number: string, customer_id: int, reason: string}> */
    public function receiptCollisions(WholesalePaymentNotice $notice): array
    {
        $collisions = [];
        $mapCollision = static fn (WholesalePaymentNotice $other, string $reason): array => [
            'notice_id' => $other->id,
            'notice_number' => $other->notice_number,
            'customer_id' => $other->customer_id,
            'reason' => $reason,
        ];

        if ($notice->receipt_sha256 !== null) {
            $sameFile = WholesalePaymentNotice::query()
                ->where('receipt_sha256', $notice->receipt_sha256)
                ->whereKeyNot($notice->id)
                ->where('status', '!=', WholesalePaymentNoticeStatus::Rejected->value)
                ->get(['id', 'notice_number', 'customer_id']);
            foreach ($sameFile as $other) {
                $collisions[] = $mapCollision($other, 'same_receipt');
            }
        }

        $sameTransfer = WholesalePaymentNotice::query()
            ->whereKeyNot($notice->id)
            ->where('customer_id', '!=', $notice->customer_id)
            ->where('status', '!=', WholesalePaymentNoticeStatus::Rejected->value)
            ->whereReferenceNumber((string) $notice->reference_number)
            ->where('amount', (string) $notice->amount)
            ->whereDate('transfer_date', $notice->transfer_date?->toDateString())
            ->get(['id', 'notice_number', 'customer_id']);
        foreach ($sameTransfer as $other) {
            $collisions[] = $mapCollision($other, 'same_reference_amount_date');
        }

        return $collisions;
    }

    // FIFO allocation settles oldest unpaid orders first using available unallocated notices.
    private function settleFreeNoticeFifo(Customer $customer, int $adminId, string $noticeNumber): void
    {
        $branchId = app(BranchAccess::class)->restrictedBranch(User::findOrFail($adminId));
        $this->applyFreePlan($customer, $adminId, $noticeNumber, $this->planFreeAllocation($customer, '0', $branchId));
    }

    /**
     * @return list<array{order_id: int, order_number: string, allocated: string, remaining: string, closes: bool, skipped: bool}>
     */
    private function planFreeAllocation(Customer $customer, string $extraFree, ?int $branchId): array
    {
        $available = $this->freePoolTotal($customer)->minus($this->allocatedTotal($customer))
            ->plus(BigDecimal::of($extraFree))
            ->toScale(2, RoundingMode::HalfUp);
        $mode = (string) $this->settings->get('wholesale_fifo_mode', 'strict');
        if (! in_array($mode, ['strict', 'skip_to_fit', 'partial'], true)) {
            $mode = 'strict';
        }

        $orders = Order::query()
            ->where('customer_id', $customer->id)
            ->where('payment_method', 'credit')
            ->where('payment_status', 'unpaid')
            ->where('status', '!=', OrderStatus::Cancelled->value)
            ->when($branchId !== null, fn ($q) => $q->where('allocated_branch_id', $branchId))
            ->orderBy('id')
            ->lockForUpdate()
            ->get();

        $lines = [];
        foreach ($orders as $order) {
            if ($available->isLessThanOrEqualTo('0')) {
                break;
            }
            $covered = $this->orderCoveredAmount((int) $order->id);
            $need = BigDecimal::of((string) $order->grand_total)->minus($covered)
                ->toScale(2, RoundingMode::HalfUp);
            if ($need->isLessThanOrEqualTo('0')) {
                $lines[] = $this->allocationLine($order, '0.00', '0.00', true, false);

                continue;
            }
            if ($available->compareTo($need) >= 0) {
                $lines[] = $this->allocationLine($order, (string) $need, '0.00', true, false);
                $available = $available->minus($need)->toScale(2, RoundingMode::HalfUp);

                continue;
            }
            if ($mode === 'partial') {
                $remaining = $need->minus($available)->toScale(2, RoundingMode::HalfUp);
                $lines[] = $this->allocationLine($order, (string) $available, (string) $remaining, false, false);

                break;
            }
            if ($mode === 'skip_to_fit') {
                $lines[] = $this->allocationLine($order, '0.00', (string) $need, false, true);

                continue;
            }

            $lines[] = $this->allocationLine($order, '0.00', (string) $need, false, false);

            break;
        }

        return $lines;
    }

    /** @param  list<array{order_id: int, order_number: string, allocated: string, remaining: string, closes: bool, skipped: bool}>  $lines */
    private function applyFreePlan(Customer $customer, int $adminId, string $noticeNumber, array $lines): void
    {
        foreach ($lines as $line) {
            $allocated = BigDecimal::of($line['allocated'])->toScale(2, RoundingMode::HalfUp);
            if ($allocated->isGreaterThan('0')) {
                $this->consumeFreePool($customer, $allocated, $line['order_id'], $adminId);
            }
            if ($line['closes']) {
                $order = Order::query()->lockForUpdate()->find($line['order_id']);
                if ($order !== null && $order->payment_status === 'unpaid') {
                    $this->markOrderPaid($order, $adminId, "تسوية آجل بالإشعار الحر {$noticeNumber}");
                }
            }
        }
    }

    /** @return array{order_id: int, order_number: string, allocated: string, remaining: string, closes: bool, skipped: bool} */
    private function allocationLine(Order $order, string $allocated, string $remaining, bool $closes, bool $skipped): array
    {
        return [
            'order_id' => (int) $order->id,
            'order_number' => (string) $order->order_number,
            'allocated' => $allocated,
            'remaining' => $remaining,
            'closes' => $closes,
            'skipped' => $skipped,
        ];
    }

    private function consumeFreePool(Customer $customer, BigDecimal $need, int $orderId, int $adminId): void
    {
        $notices = $this->freeNoticesQuery($customer)->orderBy('id')->lockForUpdate()->get();
        $remaining = $need->toScale(2, RoundingMode::HalfUp);

        foreach ($notices as $notice) {
            if ($remaining->isLessThanOrEqualTo('0')) {
                break;
            }
            $used = BigDecimal::of((string) WholesalePaymentAllocation::query()
                ->where('notice_id', $notice->id)
                ->whereHas('order', fn ($q) => $q->where('status', '!=', OrderStatus::Cancelled->value))
                ->sum('amount'))->toScale(2, RoundingMode::HalfUp);
            $free = BigDecimal::of((string) $notice->amount)->minus($used)->toScale(2, RoundingMode::HalfUp);
            if ($free->isLessThanOrEqualTo('0')) {
                continue;
            }
            $take = $free->compareTo($remaining) >= 0 ? $remaining : $free;
            WholesalePaymentAllocation::create([
                'notice_id' => $notice->id,
                'order_id' => $orderId,
                'amount' => (string) $take,
                'created_by' => $adminId,
            ]);
            $remaining = $remaining->minus($take)->toScale(2, RoundingMode::HalfUp);
        }
    }

    private function reopenOrderIfUncovered(int $orderId, int $adminId, string $noticeNumber): void
    {
        $order = Order::query()->lockForUpdate()->find($orderId);
        if ($order === null || $order->payment_status !== 'paid') {
            return;
        }

        $covered = $this->orderCoveredAmount((int) $order->id);
        if ($covered->compareTo(BigDecimal::of((string) $order->grand_total)) >= 0) {
            return;
        }

        $this->transitionOrderPaymentStatus($order, 'unpaid', $adminId, "إلغاء تسوية بعد عكس الإشعار {$noticeNumber}");
    }

    // Record status transition in audit history rather than performing a silent update.
    private function markOrderPaid(Order $order, int $adminId, string $notes): void
    {
        $this->transitionOrderPaymentStatus($order, 'paid', $adminId, $notes);
    }

    private function transitionOrderPaymentStatus(Order $order, string $paymentStatus, int $adminId, string $notes): void
    {
        $order->update(['payment_status' => $paymentStatus]);
        $order->statusHistories()->create([
            'from_status' => $order->status,
            'to_status' => $order->status,
            'changed_by_type' => (new User)->getMorphClass(),
            'changed_by_id' => $adminId,
            'notes' => mb_substr($notes, 0, 500),
        ]);
    }

    private function orderCoveredAmount(int $orderId): BigDecimal
    {
        $linked = BigDecimal::of((string) WholesalePaymentNotice::query()
            ->where('order_id', $orderId)
            ->where('status', WholesalePaymentNoticeStatus::Approved->value)
            ->sum('amount'));
        $allocated = BigDecimal::of((string) WholesalePaymentAllocation::query()
            ->where('order_id', $orderId)
            ->sum('amount'));

        return $linked->plus($allocated)->toScale(2, RoundingMode::HalfUp);
    }

    private function resolveTreasury(?int $treasuryId): Treasury
    {
        if ($treasuryId !== null) {
            // Receipts must go to bank accounts or main safes, not active POS drawers during open shifts.
            $treasury = Treasury::query()->findOrFail($treasuryId);
            if (! $treasury->is_active) {
                throw new BusinessException('الخزينة المحددة غير نشطة.');
            }
            if (! in_array($treasury->type, [TreasuryType::BankAccount, TreasuryType::MainSafe], true)) {
                throw new BusinessException('اعتماد إشعار السداد مسموح للخزينة البنكية أو الرئيسية فقط.');
            }

            return $treasury;
        }

        $treasury = Treasury::query()->where('is_active', true)
            ->where('type', TreasuryType::BankAccount->value)
            ->orderBy('id')
            ->first()
            ?? Treasury::query()->where('is_active', true)
                ->where('type', TreasuryType::MainSafe->value)
                ->orderBy('id')
                ->first();

        if ($treasury === null) {
            throw new BusinessException('لا توجد خزينة بنكية أو رئيسية نشطة لتسجيل القبض.');
        }

        return $treasury;
    }
}<?php

declare(strict_types=1);

namespace App\Services;

use App\Enums\ProductStatus;
use App\Exceptions\BusinessException;
use App\Models\Customer;
use App\Models\ProductVariant;
use App\Models\StockLevel;

/**
 * Generates customer-specific wholesale price list export rows.
 *
 * Serves as the single source of truth for Excel and PDF price list exports.
 */
class WholesalePriceListService
{
    public function __construct(private readonly PricingService $pricing) {}

    /**
     * Build tabular pricing and availability rows for all active variants for the given customer.
     *
     * @param  Customer  $customer  Target wholesale customer account.
     * @return list<array{sku: string, barcode: string|null, product_name: string|null, base_price: float|null, wholesale_price: float|null, tier_prices: list<array{min_qty: float, unit_price: float}>, available_qty: float}>
     */
    public function rows(Customer $customer): array
    {
        return StatementBudget::run(150000, fn (): array => $this->calculateRows($customer));
    }

    private function calculateRows(Customer $customer): array
    {
        $variants = ProductVariant::query()->with('product')
            ->where('is_active', true)
            ->whereHas('product', fn ($q) => $q->where('status', ProductStatus::Published->value))
            ->orderBy('sku')
            ->get();

        $availability = StockLevel::query()
            ->whereIn('product_variant_id', $variants->pluck('id')->all())
            ->groupBy('product_variant_id')
            ->selectRaw('product_variant_id, SUM(available) AS total_available')
            ->pluck('total_available', 'product_variant_id')
            ->map(fn ($v) => (float) $v)
            ->all();

        // Preload customer pricing rules and tier overrides once to eliminate N+1 group queries.
        $ctx = $this->pricing->contextFor($customer, $variants->pluck('id')->all());

        return $variants->map(function (ProductVariant $variant) use ($customer, $availability, $ctx): array {
            try {
                $resolved = $this->pricing->resolve($variant, $customer, 1, null, $ctx);
                $price = $resolved['unit_price'];
                $base = $resolved['base_price'];
                $tiers = $this->pricing->tiersFor($variant, $customer, $ctx);
            } catch (BusinessException) {
                // Emit unpriced variants with null instead of aborting the bulk catalog export.
                $price = null;
                $base = $variant->retail_price !== null ? (float) $variant->retail_price : null;
                $tiers = [];
            }

            return [
                'sku' => $variant->sku,
                'barcode' => $variant->barcode,
                'product_name' => $variant->product?->name_ar,
                'base_price' => $base,
                'wholesale_price' => $price,
                'tier_prices' => $tiers,
                'available_qty' => $availability[$variant->id] ?? 0.0,
            ];
        })->all();
    }
}<?php

declare(strict_types=1);

namespace App\Services;

use App\Enums\StaffRole;
use App\Models\Branch;
use App\Models\Treasury;
use App\Models\User;
use Illuminate\Auth\Access\AuthorizationException;
use Illuminate\Database\Eloquent\ModelNotFoundException;
use Illuminate\Support\Collection;

/**
 * Enforces staff branch scoping using a fail-closed access policy:
 * Multi-branch access is an explicit privilege (Super Admin role or inventory.all_branches permission).
 * A branch-assigned staff member is strictly confined to their branch.
 * Users with no branch assignment and no all-branch privilege are denied access by default.
 */
class BranchAccess
{
    /** @var array<int, User> Per-request memory cache to avoid reloading user instances on repeated checks. */
    private array $usersById = [];

    /** @var array<int, bool> Per-request cache of branch active statuses. */
    private array $branchActive = [];

    /**
     * Determine branch scope restriction for the given user.
     *
     * Returns null if user possesses global multi-branch access, returns branch ID if confined,
     * or throws an authorization exception if unassigned without global privileges.
     *
     * @param  User|null  $user
     * @return int|null
     *
     * @throws AuthorizationException
     */
    public function restrictedBranch(?User $user): ?int
    {
        if ($user === null) {
            throw new AuthorizationException;
        }

        if ($user->hasRole(StaffRole::SuperAdmin->value, 'staff') || $user->can('inventory.all_branches')) {
            return null;
        }

        if ($user->branch_id !== null) {
            // Fail closed if the assigned branch is deactivated to prevent unauthorized operations.
            $branchId = (int) $user->branch_id;
            $this->branchActive[$branchId] ??= (bool) (Branch::query()->find($branchId)?->is_active);
            if (! $this->branchActive[$branchId]) {
                throw new AuthorizationException('الفرع المرتبط بحسابك متوقف حالياً.');
            }

            return $branchId;
        }

        throw new AuthorizationException('حسابك غير مرتبط بأي فرع ولا تملك صلاحية الوصول لكل الفروع (inventory.all_branches).');
    }

    /**
     * Assert that the user is authorized to access at least one of the specified branches.
     *
     * @param  int  $userId
     * @param  int  ...$branchIds
     * @return void
     *
     * @throws AuthorizationException
     */
    public function assertBranch(int $userId, int ...$branchIds): void
    {
        $branchId = $this->restrictedBranch($this->usersById[$userId] ??= User::findOrFail($userId));
        if ($branchId !== null && ! in_array($branchId, $branchIds, true)) {
            throw new AuthorizationException('لا تملك صلاحية الوصول إلى هذا الفرع.');
        }
    }

    /**
     * Assert that the user possesses global multi-branch access required for central headquarters operations.
     *
     * @param  User|null  $user
     * @return void
     *
     * @throws AuthorizationException
     */
    public function assertCentralAccess(?User $user): void
    {
        if ($this->restrictedBranch($user) !== null) {
            throw new AuthorizationException('هذه العملية المركزية تتطلب صلاحية الوصول لكل الفروع.');
        }
    }

    /**
     * Lock and retrieve an active branch by ID with a shared read lock.
     *
     * @param  int  $branchId  Branch identifier.
     * @return Branch Active branch model.
     *
     * @throws ModelNotFoundException If the branch does not exist.
     * @throws AuthorizationException If the branch is deactivated.
     */
    public function lockActiveBranch(int $branchId): Branch
    {
        return $this->lockActiveBranches([$branchId])->get($branchId)
            ?? throw (new ModelNotFoundException)->setModel(Branch::class, [$branchId]);
    }

    /**
     * Lock and retrieve multiple active branches with a shared read lock.
     *
     * @param  array<int, int>|Collection<int, int>  $branchIds  Branch IDs to lock.
     * @return Collection<int, Branch> Keyed by branch ID.
     *
     * @throws ModelNotFoundException If any branch does not exist.
     * @throws AuthorizationException If any branch is deactivated.
     */
    public function lockActiveBranches(array|Collection $branchIds): Collection
    {
        $ids = collect($branchIds)->map(fn ($id) => (int) $id)->unique()->sort()->values();
        if ($ids->isEmpty()) {
            return collect();
        }

        $branches = Branch::query()->whereIn('id', $ids->all())->orderBy('id')->sharedLock()->get()->keyBy('id');
        foreach ($ids as $id) {
            $branch = $branches->get($id);
            if ($branch === null) {
                throw (new ModelNotFoundException)->setModel(Branch::class, [$id]);
            }
            if (! $branch->is_active) {
                throw new AuthorizationException('الفرع متوقف حالياً.');
            }
        }

        return $branches;
    }

    /**
     * Assert that the user is authorized to perform operations on the specified treasury.
     *
     * Central treasuries (branch_id = null) require global access; branch treasuries require branch access.
     *
     * @param  int  $userId
     * @param  Treasury  $treasury
     * @return void
     *
     * @throws AuthorizationException
     */
    public function assertTreasury(int $userId, Treasury $treasury): void
    {
        if ($treasury->branch_id === null) {
            $this->assertCentralAccess($this->usersById[$userId] ??= User::findOrFail($userId));
        } else {
            $this->assertBranch($userId, (int) $treasury->branch_id);
        }
    }
}<?php

declare(strict_types=1);

namespace App\Services;

use App\Enums\ProductStatus;
use App\Exceptions\BusinessException;
use App\Models\Customer;
use App\Models\Order;
use App\Models\ProductVariant;
use App\Models\StockLevel;
use Illuminate\Support\Collection;

/**
 * Quick-order service for wholesale customers.
 * Handles bulk code lookups (with tiered pricing and stock availability), cart imports, and order re-ordering.
 * All cart additions route through CartService to guarantee current real-time pricing.
 */
class WholesaleQuickOrderService
{
    public function __construct(
        private readonly PricingService $pricing,
        private readonly CartService $carts,
    ) {}

    /**
     * Batch lookup product variants by SKU or barcode with quantity-tier pricing and total available stock.
     *
     * @param  Customer  $customer  Wholesale customer performing the lookup.
     * @param  list<array{sku?: string|null, barcode?: string|null, qty: float}>  $lines  Requested order lines.
     * @return list<array<string, mixed>> Line details with live pricing and availability status.
     */
    public function lookup(Customer $customer, array $lines): array
    {
        $variants = $this->findVariants($lines);
        $availability = $this->availabilityFor($variants->pluck('id')->all());
        // Preload pricing context for all looked-up variants in a single query batch.
        $ctx = $this->pricing->contextFor($customer, $variants->pluck('id')->unique()->all());

        return collect($lines)->map(function (array $line) use ($customer, $variants, $availability, $ctx): array {
            $code = (string) ($line['sku'] ?? $line['barcode'] ?? '');
            $variant = $variants->get($code);
            $qty = (float) $line['qty'];

            if ($variant === null) {
                return [
                    'code' => $code, 'found' => false, 'qty' => $qty,
                    'available_qty' => 0.0, 'in_stock' => false,
                ];
            }

            $available = $availability[$variant->id] ?? 0.0;
            $unitPrice = $this->pricing->resolve($variant, $customer, $qty, null, $ctx)['unit_price'];

            return [
                'code' => $code,
                'found' => true,
                'product_variant_id' => $variant->id,
                'sku' => $variant->sku,
                'barcode' => $variant->barcode,
                'label' => $variant->displayLabel(),
                'image' => $this->imageFor($variant),
                'product_name' => $variant->product?->name_ar,
                'qty' => $qty,
                'unit_price' => $unitPrice,
                'line_total' => round($unitPrice * $qty, 2),
                'tier_prices' => $this->pricing->tiersFor($variant, $customer, $ctx),
                'available_qty' => $available,
                'in_stock' => $available >= $qty,
            ];
        })->all();
    }

    /**
     * Import multiple items from a parsed CSV/Excel file into the customer's active cart.
     * Skips invalid codes or lines exceeding available stock with explanatory status reports.
     *
     * @param  Customer  $customer  Target wholesale customer account.
     * @param  list<array{sku: string, qty: float}>  $rows  Parsed spreadsheet rows.
     * @return array{added: list<array<string, mixed>>, skipped: list<array<string, mixed>>, cart: array<string, mixed>}
     */
    public function importToCart(Customer $customer, array $rows): array
    {
        // Consolidate duplicate codes within the input before running stock availability checks.
        $merged = [];
        foreach ($rows as $row) {
            $sku = trim((string) $row['sku']);
            if ($sku === '') {
                continue;
            }
            $merged[$sku] = ($merged[$sku] ?? 0.0) + (float) $row['qty'];
        }

        $lines = collect($merged)->map(fn (float $qty, string $sku) => ['sku' => $sku, 'qty' => $qty])->values()->all();
        $variants = $this->findVariants($lines);
        $availability = $this->availabilityFor($variants->pluck('id')->all());
        // Preload pricing context for all candidate items in one batch to eliminate per-item overhead.
        $ctx = $this->pricing->contextFor($customer, $variants->pluck('id')->unique()->all());

        $items = array_map(fn (array $line) => [
            'sku' => $line['sku'],
            'qty' => $line['qty'],
            'variant' => $variants->get($line['sku']),
        ], $lines);

        return $this->addLinesToCart($customer, $items, $availability, $ctx);
    }

    /**
     * Copy lines from a previous order into the customer's current cart at today's real-time prices.
     * Skips items that are discontinued, unpublished, or out of stock.
     *
     * @param  Customer  $customer  Target wholesale customer account.
     * @param  Order  $order  Historical order to duplicate into cart.
     * @return array{added: list<array<string, mixed>>, skipped: list<array<string, mixed>>, cart: array<string, mixed>}
     */
    public function reorderToCart(Customer $customer, Order $order): array
    {
        if ($order->customer_id !== $customer->id) {
            throw new BusinessException('الطلب غير موجود أو لا يخص هذا التاجر.', [], 404);
        }

        $rows = $order->items()
            ->get()
            ->groupBy('product_variant_id')
            ->map(fn (Collection $items, int $variantId) => [
                'sku' => (string) ($items->first()->sku_snapshot ?? ''),
                'qty' => (float) $items->sum('qty'),
                'variant_id' => $variantId,
            ])
            ->values()
            ->all();

        // Key by active variant ID rather than historical snapshot SKU to ensure integrity against catalog renames.
        $variants = ProductVariant::query()->with('product')
            ->whereIn('id', collect($rows)->pluck('variant_id')->all())
            ->get()->keyBy('id');
        $availability = $this->availabilityFor($variants->pluck('id')->all());
        $ctx = $this->pricing->contextFor($customer, $variants->pluck('id')->all());

        $items = array_map(fn (array $row) => [
            'sku' => $row['sku'],
            'qty' => $row['qty'],
            'variant' => $variants->get($row['variant_id']),
        ], $rows);

        return $this->addLinesToCart($customer, $items, $availability, $ctx);
    }

    /**
     * Iterates over candidate order lines, applying stock checks and adding available items to the active cart.
     *
     * @param  list<array{sku: string, qty: float, variant: ?ProductVariant}>  $items
     * @param  array<int, float>  $availability
     * @param  array<string, mixed>  $pricingCtx
     * @return array{added: list<array<string, mixed>>, skipped: list<array<string, mixed>>, cart: array<string, mixed>}
     */
    private function addLinesToCart(Customer $customer, array $items, array $availability, array $pricingCtx): array
    {
        $cart = $this->carts->resolveCart($customer, null);
        $inCart = $cart->items()->pluck('qty', 'product_variant_id')->map(fn ($q) => (float) $q)->all();

        $added = [];
        $skipped = [];
        foreach ($items as $item) {
            $variant = $item['variant'];
            $sku = $item['sku'];
            $qty = (float) $item['qty'];

            if ($variant === null || ! $variant->is_active || $variant->product?->status !== ProductStatus::Published) {
                $skipped[] = ['sku' => $sku, 'qty' => $qty, 'reason' => 'not_found_or_inactive'];

                continue;
            }

            $alreadyInCart = $inCart[$variant->id] ?? 0.0;
            if (($availability[$variant->id] ?? 0.0) < $alreadyInCart + $qty) {
                $skipped[] = ['sku' => $sku, 'qty' => $qty, 'reason' => 'insufficient_stock'];

                continue;
            }

            $cart = $this->carts->addItem($cart, $customer, $variant->id, $qty);
            $inCart[$variant->id] = $alreadyInCart + $qty;
            $added[] = [
                'sku' => $variant->sku,
                'product_variant_id' => $variant->id,
                'qty' => $qty,
                'unit_price' => $this->pricing->resolve($variant, $customer, $inCart[$variant->id], null, $pricingCtx)['unit_price'],
            ];
        }

        return [
            'added' => $added,
            'skipped' => $skipped,
            'cart' => $this->carts->present($cart, $customer),
        ];
    }

    /**
     * Map active variants of published products by SKU and barcode.
     *
     * @param  list<array{sku?: string|null, barcode?: string|null}>  $lines
     * @return Collection<string, ProductVariant>
     */
    private function findVariants(array $lines): Collection
    {
        $skus = collect($lines)->pluck('sku')->filter()->unique()->all();
        $barcodes = collect($lines)->pluck('barcode')->filter()->unique()->all();

        if ($skus === [] && $barcodes === []) {
            return collect();
        }

        $variants = ProductVariant::query()->with(['product.media', 'media'])
            ->where('is_active', true)
            ->whereHas('product', fn ($q) => $q->where('status', 'published'))
            ->where(function ($q) use ($skus, $barcodes): void {
                if ($skus !== []) {
                    $q->orWhereIn('sku', $skus);
                }
                if ($barcodes !== []) {
                    $q->orWhereIn('barcode', $barcodes);
                }
            })
            ->get();

        $map = collect();
        foreach ($variants as $variant) {
            $map->put($variant->sku, $variant);
            if ($variant->barcode !== null && $variant->barcode !== '') {
                $map->put($variant->barcode, $variant);
            }
        }

        return $map;
    }

    /**
     * Resolves primary thumbnail following catalog priority (product gallery first, then variant media).
     */
    private function imageFor(ProductVariant $variant): ?string
    {
        $media = $variant->product?->getMedia('images')->first()
            ?? $variant->getMedia('images')->first();

        if ($media === null) {
            return null;
        }

        return $media->hasGeneratedConversion('thumb') ? $media->getUrl('thumb') : $media->getUrl();
    }

    /**
     * Total available stock across all branches for a given list of variant IDs.
     *
     * @param  list<int>  $variantIds
     * @return array<int, float>
     */
    private function availabilityFor(array $variantIds): array
    {
        if ($variantIds === []) {
            return [];
        }

        return StockLevel::query()
            ->whereIn('product_variant_id', $variantIds)
            ->groupBy('product_variant_id')
            ->selectRaw('product_variant_id, SUM(available) AS total_available')
            ->pluck('total_available', 'product_variant_id')
            ->map(fn ($v) => (float) $v)
            ->all();
    }
}<?php

declare(strict_types=1);

namespace App\Services;

use App\Enums\CustomerDocumentStatus;
use App\Enums\CustomerDocumentType;
use App\Enums\CustomerStatus;
use App\Enums\CustomerType;
use App\Events\WholesaleApplicationSubmitted;
use App\Models\Customer;
use App\Models\CustomerAuditLog;
use App\Models\CustomerDocument;
use Illuminate\Http\UploadedFile;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Storage;
use Illuminate\Support\Str;

/**
 * Handles wholesale merchant self-registration and KYC document staging.
 *
 * Persists customer accounts in pending verification status and isolates document uploads
 * in private cloud storage prior to database transaction commitment.
 */
class WholesaleRegistrationService
{
    public function __construct(
        private readonly CustomerAuthService $auth,
        private readonly CustomerPhoneVerificationService $phoneVerification,
    ) {}

    /**
     * Registers a wholesale applicant and links uploaded verification files.
     *
     * @param  array<string, mixed>  $data  Registration attributes including credentials and trade metadata.
     * @param  list<UploadedFile>  $files  Uploaded identity and commercial verification files.
     * @param  list<string|null>  $documentTypes  Corresponding document categorization tags.
     * @return array{customer: Customer, token: string} Created customer instance and initial session token.
     */
    public function register(array $data, array $files, array $documentTypes = []): array
    {
        $files = array_values($files);
        $documentTypes = array_values($documentTypes);
        $storedPaths = [];
        $staged = [];
        $stagingDirectory = 'customer_documents/pending/'.Str::uuid();
        $disk = Storage::disk('r2');

        // Assert proof existence upfront before expensive cloud file I/O; actual token consumption happens in DB transaction.
        $this->phoneVerification->assertProofPresent($data);

        try {
            foreach ($files as $i => $file) {
                $filename = Str::uuid().'.'.($file->extension() ?: 'bin');
                $path = $disk->putFileAs($stagingDirectory, $file, $filename);
                if ($path === false) {
                    throw new \RuntimeException('تعذر حفظ مستند العميل.');
                }
                $storedPaths[] = $path;
                $staged[] = [
                    'filename' => $filename, 'path' => $path,
                    'document_type' => $documentTypes[$i] ?? CustomerDocumentType::Other->value,
                    'original_name' => CustomerDocument::safeName($file->getClientOriginalName()),
                    'mime_type' => $file->getMimeType() ?? 'application/octet-stream',
                ];
            }

            // Pre-allocate Postgres sequence ID to establish customer document directory path without holding row locks during S3/R2 copy operations.
            $customerId = (int) DB::selectOne("SELECT nextval(pg_get_serial_sequence('customers', 'id')) AS id")->id;
            foreach ($staged as &$document) {
                $path = "customer_documents/{$customerId}/".$document['filename'];
                $storedPaths[] = $path;
                if (! $disk->move($document['path'], $path)) {
                    throw new \RuntimeException('تعذر حفظ مستند العميل.');
                }
                $document['path'] = $path;
            }
            unset($document);

            $registration = DB::transaction(function () use ($data, $staged, $customerId): array {
                $this->auth->lockRegistrationEmail($data['email'] ?? null);
                $verified = $this->phoneVerification->consume($data);
                $customer = Customer::query()->make([
                    'name' => $data['name'],
                    'email' => $data['email'] ?? null,
                    'phone' => $data['phone'],
                    'password' => $data['password'],
                    'type' => CustomerType::Wholesale,
                    'phone_verified_at' => $verified ? now() : null,
                    'company_name' => $data['company_name'],
                    'tax_number' => $data['tax_number'],
                    'commercial_register' => $data['commercial_register'],
                ]);
                $customer->forceFill(['id' => $customerId, 'status' => CustomerStatus::Pending])->save();

                foreach ($staged as $document) {
                    $customer->documents()->create([
                        'document_type' => $document['document_type'],
                        'file_path' => $document['path'],
                        'original_name' => $document['original_name'],
                        'mime_type' => $document['mime_type'],
                        'status' => CustomerDocumentStatus::Pending,
                    ]);
                }

                CustomerAuditLog::record($customer, 'self_registered', null, ['channel' => 'wholesale']);
                DB::afterCommit(static function () use ($customer): void {
                    try {
                        WholesaleApplicationSubmitted::dispatch($customer);
                    } catch (\Throwable $exception) {
                        // Commit the account first; prevent queue driver outages or notification failures from aborting a valid registration.
                        report($exception);
                    }
                });

                return [
                    'customer' => $customer->load('documents'),
                    'token' => $this->auth->issueToken($customer, 'wholesale-token'),
                ];
            });
        } catch (\Throwable $e) {
            // Purge staged and committed cloud assets on rollback to prevent orphaned KYC files in storage bucket.
            $this->purgePathsAndDirectory($stagingDirectory, $storedPaths);

            // Map PostgreSQL unique constraint violations (e.g. duplicate tax/phone/email) to friendly HTTP 422 validation errors.
            throw Customer::translateUniqueViolation($e);
        }

        $this->deleteDirectorySilently($stagingDirectory);

        return $registration;
    }

    /**
     * @param  list<string>  $storedPaths
     */
    private function purgePathsAndDirectory(string $stagingDirectory, array $storedPaths): void
    {
        $disk = Storage::disk('r2');
        foreach ($storedPaths as $path) {
            try {
                $disk->delete($path);
            } catch (\Throwable $exception) {
                report($exception);
            }
        }
        if ($storedPaths !== []) {
            $this->deleteDirectorySilently($stagingDirectory);
        }
    }

    private function deleteDirectorySilently(string $directory): void
    {
        try {
            Storage::disk('r2')->deleteDirectory($directory);
        } catch (\Throwable $exception) {
            report($exception);
        }
    }
}<?php

declare(strict_types=1);

use App\Http\Controllers\Api\V1\AttachmentController;
use App\Http\Controllers\Api\V1\Shared\NotificationController;
use App\Http\Controllers\Api\V1\Wholesale\DashboardController;
use App\Http\Controllers\Api\V1\Wholesale\InvoiceController;
use App\Http\Controllers\Api\V1\Wholesale\OrderController;
use App\Http\Controllers\Api\V1\Wholesale\PaymentNoticeController;
use App\Http\Controllers\Api\V1\Wholesale\ProductController;
use App\Http\Controllers\Api\V1\Wholesale\QuickOrderController;
use App\Http\Controllers\Api\V1\Wholesale\QuotationController;
use App\Http\Controllers\Api\V1\Wholesale\RegisterController;
use Illuminate\Support\Facades\Route;

Route::prefix('auth')->name('auth.')->group(function (): void {
    // Merchant onboarding registration and document uploads
    Route::post('register', [RegisterController::class, 'register'])->middleware('throttle:customer-registration')->name('register');

    // Onboarding status inspection (requires authenticated customer token; does not require wholesale approval yet)
    Route::middleware(['auth:sanctum', 'auth.customer'])->group(function (): void {
        Route::get('application-status', [RegisterController::class, 'applicationStatus'])->name('application-status');
        // Re-upload replacement for rejected onboarding documents
        Route::post('documents', [RegisterController::class, 'uploadDocument'])
            ->middleware('throttle:customer-registration')->name('documents.store');
    });
});

// Advanced wholesale portal: protected by wholesale.approved middleware to restrict trade pricing and credit terms
Route::middleware(['auth:sanctum', 'auth.customer', 'wholesale.approved'])->group(function (): void {
    Route::get('dashboard', [DashboardController::class, 'index'])->name('dashboard');

    // Catalog browsing and price list exports (PDF / Excel)
    Route::get('products', [ProductController::class, 'index'])->name('products.index');
    Route::get('price-list/export', [ProductController::class, 'exportPriceList'])->name('price-list.export');

    // Quick order lookup, spreadsheet import, and reordering
    Route::post('quick-order/lookup', [QuickOrderController::class, 'lookup'])->name('quick-order.lookup');
    Route::post('quick-order/import', [QuickOrderController::class, 'import'])->name('quick-order.import');
    Route::post('quick-order/add-to-cart', [QuickOrderController::class, 'addToCart'])->name('quick-order.add-to-cart');
    Route::get('orders', [OrderController::class, 'index'])->name('orders.index');
    Route::get('orders/{order}', [OrderController::class, 'show'])->whereNumber('order')->name('orders.show');
    Route::post('orders/{order}/reorder', [OrderController::class, 'reorder'])->whereNumber('order')->name('orders.reorder');

    // Invoices, account statements, and payment proof submissions
    Route::get('invoices', [InvoiceController::class, 'index'])->name('invoices.index');
    Route::get('invoices/{order}/pdf', [InvoiceController::class, 'pdf'])->whereNumber('order')->name('invoices.pdf');
    Route::get('statement', [InvoiceController::class, 'statement'])->name('statement');
    Route::post('payment-notices', [InvoiceController::class, 'storePaymentNotice'])->name('payment-notices.store');
    // Payment notice ledger status and receipt downloads
    Route::get('payment-notices', [PaymentNoticeController::class, 'index'])->name('payment-notices.index');
    Route::get('payment-notices/outstanding', [PaymentNoticeController::class, 'outstanding'])->name('payment-notices.outstanding');
    Route::get('payment-notices/{payment_notice}', [PaymentNoticeController::class, 'show'])->whereNumber('payment_notice')->name('payment-notices.show');
    Route::get('payment-notices/{notice}/receipt', [AttachmentController::class, 'paymentNotice'])->whereNumber('notice')->name('payment-notices.receipt');

    // Price quotations lifecycle
    Route::apiResource('quotations', QuotationController::class)->parameters(['quotations' => 'quotation']);
    Route::post('quotations/{quotation}/submit', [QuotationController::class, 'submit'])->whereNumber('quotation')->name('quotations.submit');
    Route::post('quotations/{quotation}/accept', [QuotationController::class, 'accept'])->whereNumber('quotation')->name('quotations.accept');
    Route::post('quotations/{quotation}/reject', [QuotationController::class, 'reject'])->whereNumber('quotation')->name('quotations.reject');

    // Merchant notifications
    Route::get('notifications', [NotificationController::class, 'index'])->name('notifications.index');
    Route::post('notifications/{id}/read', [NotificationController::class, 'markAsRead'])->name('notifications.read');
    Route::post('notifications/read-all', [NotificationController::class, 'readAll'])->name('notifications.read-all');
});<?php

declare(strict_types=1);

namespace App\Models;

use App\Enums\OrderStatus;
use Database\Factories\OrderFactory;
use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\HasMany;
use Illuminate\Database\Eloquent\SoftDeletes;

/**
 * Order entity representing customer orders across Storefront, POS, and Wholesale channels.
 * Status transitions MUST occur via OrderService::changeStatus() to ensure inventory reservations,
 * status history audit entries, and shipment consignments are atomically handled.
 */
class Order extends Model
{
    /** @use HasFactory<OrderFactory> */
    use HasFactory, SoftDeletes;

    protected $fillable = [
        'order_number',
        'channel',
        'customer_id',
        'guest_name',
        'guest_phone',
        'guest_phone_normalized',
        'guest_email',
        'city_id',
        'shipping_address_line',
        'shipping_notes',
        'allocated_branch_id',
        'pos_shift_id',
        'return_of_order_id',
        'status',
        'payment_method',
        'payment_status',
        'due_at',
        'requires_refund',
        'needs_attention',
        'cod_fee',
        'idempotency_key',
        'idempotency_scope',
        'gateway_order_id',
        'subtotal',
        'discount_amount',
        'coupon_id',
        'coupon_code',
        'shipping_cost',
        'tax_amount',
        'grand_total',
        'cash_amount',
        'card_amount',
    ];

    protected function casts(): array
    {
        return [
            'status' => OrderStatus::class,
            'subtotal' => 'decimal:2',
            'discount_amount' => 'decimal:2',
            'shipping_cost' => 'decimal:2',
            'cod_fee' => 'decimal:2',
            'tax_amount' => 'decimal:2',
            'grand_total' => 'decimal:2',
            'cash_amount' => 'decimal:2',
            'card_amount' => 'decimal:2',
            'requires_refund' => 'boolean',
            'needs_attention' => 'boolean',
            'due_at' => 'datetime',
        ];
    }

    /** @return BelongsTo<PosShift, $this> */
    public function posShift(): BelongsTo
    {
        return $this->belongsTo(PosShift::class);
    }

    /** @return HasMany<OrderItem, $this> */
    public function items(): HasMany
    {
        return $this->hasMany(OrderItem::class);
    }

    /** @return HasMany<OrderStatusHistory, $this> */
    public function statusHistories(): HasMany
    {
        return $this->hasMany(OrderStatusHistory::class)->latest('id');
    }

    /** @return HasMany<Shipment, $this> */
    public function shipments(): HasMany
    {
        return $this->hasMany(Shipment::class);
    }

    /** @return HasMany<ReturnRequest, $this> */
    public function returnRequests(): HasMany
    {
        return $this->hasMany(ReturnRequest::class);
    }

    /** @return BelongsTo<Customer, $this> */
    public function customer(): BelongsTo
    {
        return $this->belongsTo(Customer::class);
    }

    /** @return BelongsTo<City, $this> */
    public function city(): BelongsTo
    {
        return $this->belongsTo(City::class);
    }

    /** @return BelongsTo<Branch, $this> */
    public function allocatedBranch(): BelongsTo
    {
        return $this->belongsTo(Branch::class, 'allocated_branch_id');
    }

    /**
     * Determine whether the given phone number matches this order (guest or registered customer).
     * Compares canonical E.164 formats to prevent false mismatches from dialing codes.
     *
     * @param  string  $phone  Input phone string to compare
     * @return bool True if phone matches guest or customer phone
     */
    public function matchesPhone(string $phone): bool
    {
        $normalized = Customer::normalizePhone($phone);

        if ($this->guest_phone_normalized !== null && $this->guest_phone_normalized === $normalized) {
            return true;
        }

        if ($this->guest_phone !== null && Customer::normalizePhone($this->guest_phone) === $normalized) {
            return true;
        }

        if ($this->customer?->phone !== null && Customer::normalizePhone((string) $this->customer->phone) === $normalized) {
            return true;
        }

        return false;
    }
}<?php

declare(strict_types=1);

namespace App\Services;

use App\Enums\OrderStatus;
use App\Enums\QuotationSource;
use App\Enums\QuotationStatus;
use App\Events\OrderCreated;
use App\Events\QuotationAccepted;
use App\Events\QuotationExpired;
use App\Events\QuotationPriced;
use App\Events\QuotationSubmitted;
use App\Exceptions\BusinessException;
use App\Models\Customer;
use App\Models\Order;
use App\Models\OrderStatusHistory;
use App\Models\ProductVariant;
use App\Models\Quotation;
use App\Models\StockLevel;
use App\Models\User;
use Carbon\Carbon;
use Illuminate\Support\Facades\DB;

/**
 * Manages the wholesale quotation lifecycle:
 * Draft creation with dynamic pricing -> customer submission -> administrator pricing and validation ->
 * customer acceptance with automated order generation and stock allocation, or rejection/expiry.
 *
 * Quotations hold no inventory reservations; stock allocation occurs only upon customer acceptance.
 */
class QuotationService
{
    public function __construct(
        private readonly SettingService $settings,
        private readonly PricingService $pricing,
        private readonly OrderService $orders,
        private readonly OrderAllocationService $allocation,
    ) {}

    /**
     * Create a new draft quotation for a wholesale customer.
     *
     * @param  Customer  $customer  Wholesale customer requesting the quote.
     * @param  array{customer_notes?: string|null, items: list<array{product_variant_id: int, qty: float, requested_target_price?: float|null}>}  $data
     * @return Quotation Newly created draft quotation.
     */
    public function create(Customer $customer, array $data): Quotation
    {
        return DB::transaction(function () use ($customer, $data): Quotation {
            $source = QuotationSource::tryFrom((string) ($data['source'] ?? 'portal')) ?? QuotationSource::Portal;
            $quotation = Quotation::create([
                'quotation_number' => $this->settings->generateNextNumber('quotation'),
                'customer_id' => $customer->id,
                'status' => QuotationStatus::Draft,
                'source' => $source,
                'customer_notes' => $data['customer_notes'] ?? null,
            ]);

            $this->syncItems($quotation, $customer, $data['items']);
            $this->recalculate($quotation);

            return $quotation->load('items.variant.product');
        });
    }

    /**
     * Update items and customer notes on an unsubmitted draft quotation.
     *
     * @param  Quotation  $quotation  Draft quotation to update.
     * @param  array{customer_notes?: string|null, items?: list<array{product_variant_id: int, qty: float, requested_target_price?: float|null}>}  $data
     * @return Quotation Updated quotation instance.
     *
     * @throws BusinessException If quotation is not in draft state.
     */
    public function update(Quotation $quotation, array $data): Quotation
    {
        if ($quotation->status !== QuotationStatus::Draft) {
            throw new BusinessException('لا يمكن تعديل عرض السعر إلا وهو مسودة.');
        }

        return DB::transaction(function () use ($quotation, $data): Quotation {
            $quotation->update([
                'customer_notes' => $data['customer_notes'] ?? $quotation->customer_notes,
            ]);

            if (isset($data['items'])) {
                $quotation->items()->delete();
                $this->syncItems($quotation, $quotation->customer, $data['items']);
                $quotation->increment('revision');
            }

            $this->recalculate($quotation);

            return $quotation->load('items.variant.product');
        });
    }

    /**
     * Submit a draft quotation for administrator pricing and review.
     *
     * @param  Quotation  $quotation  Draft quotation to submit.
     * @return Quotation Submitted quotation instance.
     *
     * @throws BusinessException If quotation is not draft or contains no items.
     */
    public function submit(Quotation $quotation): Quotation
    {
        if ($quotation->status !== QuotationStatus::Draft) {
            throw new BusinessException('لا يمكن إرسال عرض السعر إلا من حالة المسودة.');
        }

        if ($quotation->items()->count() === 0) {
            throw new BusinessException('لا يمكن إرسال عرض سعر بلا بنود.');
        }

        $quotation->update(['status' => QuotationStatus::Requested]);
        QuotationSubmitted::dispatch($quotation);

        return $quotation->load('items.variant.product');
    }

    /**
     * Set negotiated prices, validity expiration, discounts, and taxes by an administrator.
     *
     * @param  Quotation  $quotation  Requested quotation to price.
     * @param  array{valid_until?: string|null, admin_notes?: string|null, discount_amount?: float|null, tax_amount?: float|null, items?: list<array{id: int, offered_unit_price: float}>}  $data
     * @return Quotation Priced quotation instance.
     *
     * @throws BusinessException If quotation is not in Requested state or references invalid items.
     */
    public function price(Quotation $quotation, array $data): Quotation
    {
        if ($quotation->status !== QuotationStatus::Requested) {
            throw new BusinessException('لا يمكن تسعير عرض السعر إلا بعد إرساله من التاجر.');
        }

        return DB::transaction(function () use ($quotation, $data): Quotation {
            foreach ($data['items'] ?? [] as $row) {
                $item = $quotation->items()->whereKey($row['id'])->first();

                if ($item === null) {
                    throw new BusinessException('أحد بنود التسعير لا ينتمي لعرض السعر هذا.');
                }

                $item->update([
                    'offered_unit_price' => $row['offered_unit_price'],
                    'line_total' => round((float) $row['offered_unit_price'] * (float) $item->qty, 2),
                ]);
            }

            $quotation->update([
                'status' => QuotationStatus::PricedByAdmin,
                'valid_until' => $data['valid_until'] ?? $quotation->valid_until,
                'admin_notes' => $data['admin_notes'] ?? $quotation->admin_notes,
                'discount_amount' => $data['discount_amount'] ?? $quotation->discount_amount,
                'tax_amount' => $data['tax_amount'] ?? $quotation->tax_amount,
                'priced_at' => now(),
                'priced_by' => $data['priced_by'] ?? $quotation->priced_by,
                'revision' => $quotation->priced_at === null ? (int) $quotation->revision : (int) $quotation->revision + 1,
            ]);

            $this->recalculate($quotation);
            $quotation = $quotation->load('items.variant.product');
            QuotationPriced::dispatch($quotation);

            return $quotation;
        });
    }

    /**
     * Accept an administrator-priced quotation and automatically convert it into a confirmed order.
     *
     * Preserves negotiated line prices, distributes header discounts/taxes using Hare-Niemeyer,
     * and allocates inventory. Fails the conversion entirely if any item lacks available stock.
     *
     * @param  Quotation  $quotation  Priced quotation to accept.
     * @return Quotation Converted quotation with loaded relation to generated order.
     *
     * @throws BusinessException If quotation is expired, unpriced, or breaches customer credit limit.
     */
    public function accept(Quotation $quotation): Quotation
    {
        if ($quotation->status !== QuotationStatus::PricedByAdmin) {
            throw new BusinessException('لا يمكن قبول عرض السعر إلا بعد تسعير الإدارة له.');
        }

        if ($quotation->valid_until !== null && $quotation->valid_until->lt(now()->startOfDay())) {
            $quotation->update(['status' => QuotationStatus::Expired]);

            throw new BusinessException('انتهت صلاحية عرض السعر هذا.');
        }

        return DB::transaction(function () use ($quotation): Quotation {
            $quotation->loadMissing(['customer', 'items.variant.product']);
            $customer = $quotation->customer;

            // Lock customer account row to serialize concurrent order placements and prevent credit limit race conditions.
            Customer::query()->whereKey($customer->id)->lockForUpdate()->first();
            $outstanding = app(WholesalePaymentNoticeService::class)->outstandingBalance($customer->fresh());
            if ($outstanding + (float) $quotation->grand_total > (float) $customer->credit_limit) {
                throw new BusinessException(
                    'إجمالي الطلب يتجاوز حد الائتمان المتاح.',
                    [],
                    422,
                    'credit_limit_exceeded',
                );
            }

            $order = Order::create([
                'order_number' => $this->settings->generateNextNumber('order'),
                'channel' => 'wholesale',
                'customer_id' => $customer->id,
                'guest_name' => $customer->name,
                'guest_phone' => $customer->phone,
                'guest_phone_normalized' => Customer::normalizePhone((string) $customer->phone),
                'guest_email' => $customer->email,
                'status' => OrderStatus::Pending,
                'payment_method' => 'credit',
                'payment_status' => 'unpaid',
                'subtotal' => $quotation->subtotal,
                'discount_amount' => $quotation->discount_amount,
                'shipping_cost' => 0,
                'cod_fee' => 0,
                'tax_amount' => $quotation->tax_amount,
                'grand_total' => $quotation->grand_total,
            ]);

            // Apportion header-level discount and tax across items using largest remainder to preserve exact penny reconciliation.
            $weights = $quotation->items->map(fn ($item) => (float) $item->line_total)->all();
            $discountShares = ProportionalDistribution::distribute((float) $quotation->discount_amount, $weights);
            $taxShares = ProportionalDistribution::distribute((float) $quotation->tax_amount, $weights);

            foreach ($quotation->items->values() as $i => $item) {
                $order->items()->create([
                    'product_variant_id' => $item->product_variant_id,
                    'product_name_snapshot' => $item->variant->product?->name_ar ?? '',
                    'sku_snapshot' => $item->variant->sku,
                    'qty' => $item->qty,
                    'unit_price' => $item->offered_unit_price,
                    'discount_amount' => $discountShares[$i],
                    'tax_amount' => $taxShares[$i],
                    'line_total' => $item->line_total,
                ]);
            }

            OrderStatusHistory::create([
                'order_id' => $order->id,
                'from_status' => null,
                'to_status' => OrderStatus::Pending,
                'changed_by_type' => Customer::class,
                'changed_by_id' => $customer->id,
                'notes' => "أُنشئ من عرض السعر {$quotation->quotation_number}",
            ]);

            // Quotations hold zero inventory reservations; physical stock allocation occurs immediately upon conversion.
            $order->load('items');
            $this->allocation->allocate($order, performedBy: $this->systemActorId());

            $this->orders->changeStatus($order, OrderStatus::Confirmed, $customer, "قبول عرض السعر {$quotation->quotation_number}");

            $quotation->update([
                'status' => QuotationStatus::ConvertedToOrder,
                'converted_order_id' => $order->id,
            ]);

            OrderCreated::dispatch($order->fresh());
            QuotationAccepted::dispatch($quotation);

            return $quotation->load(['items.variant.product', 'convertedOrder']);
        });
    }

    /**
     * Retrieve the designated system user ID for recording customer-initiated ledger movements.
     */
    private function systemActorId(): ?int
    {
        $id = User::query()
            ->where('is_system', true)
            ->value('id');

        return $id !== null ? (int) $id : null;
    }

    /**
     * Reject a submitted or priced quotation.
     *
     * @param  Quotation  $quotation  Target quotation.
     * @return Quotation Rejected quotation instance.
     *
     * @throws BusinessException If quotation is not in Requested or PricedByAdmin state.
     */
    public function reject(Quotation $quotation): Quotation
    {
        if (! in_array($quotation->status, [QuotationStatus::Requested, QuotationStatus::PricedByAdmin], true)) {
            throw new BusinessException('لا يمكن رفض عرض السعر في حالته الحالية.');
        }

        $quotation->update(['status' => QuotationStatus::Rejected]);

        return $quotation->load('items.variant.product');
    }

    /**
     * Expire a past-due quotation.
     *
     * @param  Quotation  $quotation  Target quotation.
     * @return Quotation Expired quotation instance.
     *
     * @throws BusinessException If quotation is not in PricedByAdmin state or has not reached its valid_until date.
     */
    public function expire(Quotation $quotation): Quotation
    {
        if ($quotation->status !== QuotationStatus::PricedByAdmin) {
            throw new BusinessException('لا يمكن إنهاء صلاحية عرض السعر إلا بعد تسعيره.');
        }

        if ($quotation->valid_until !== null && $quotation->valid_until->gte(now()->startOfDay())) {
            throw new BusinessException('عرض السعر ما زال ساري الصلاحية.');
        }

        $quotation->update(['status' => QuotationStatus::Expired]);
        QuotationExpired::dispatch($quotation);

        return $quotation->load('items.variant.product');
    }

    /**
     * Move a priced quotation's validity forward.
     *
     * @throws BusinessException If the quotation is not priced or the date is in the past.
     */
    public function extendValidity(Quotation $quotation, string $validUntil): Quotation
    {
        if ($quotation->status !== QuotationStatus::PricedByAdmin) {
            throw new BusinessException('لا يمكن تمديد الصلاحية إلا لعرض مسعّر.');
        }

        $date = Carbon::parse($validUntil)->startOfDay();
        if ($date->lt(now()->startOfDay())) {
            throw new BusinessException('تاريخ الصلاحية لازم يكون النهارده أو بعد كده.');
        }

        $quotation->update(['valid_until' => $date->toDateString()]);

        return $quotation->fresh(['items.variant.product']);
    }

    /**
     * Restores a priced quotation to the snapshot taken before an AI price action.
     *
     * @param  array{valid_until: ?string, discount_amount: string, tax_amount: string, items: list<array{id: int, offered_unit_price: string}>}  $snapshot
     *
     * @throws BusinessException If the trader already accepted the quotation.
     */
    public function restorePricedSnapshot(Quotation $quotation, array $snapshot): Quotation
    {
        if ($quotation->status !== QuotationStatus::PricedByAdmin) {
            throw new BusinessException('التراجع متاح فقط لو العرض لسه مسعّر والتاجر ماقبلهوش.');
        }

        return DB::transaction(function () use ($quotation, $snapshot): Quotation {
            $quotation = Quotation::query()->lockForUpdate()->findOrFail($quotation->id);
            if ($quotation->status !== QuotationStatus::PricedByAdmin) {
                throw new BusinessException('التراجع متاح فقط لو العرض لسه مسعّر والتاجر ماقبلهوش.');
            }
            foreach ($snapshot['items'] as $row) {
                $item = $quotation->items()->whereKey($row['id'])->first();
                if ($item === null) {
                    throw new BusinessException('بند التسعير لم يعد موجودًا.');
                }
                $item->update([
                    'offered_unit_price' => $row['offered_unit_price'],
                    'line_total' => round((float) $row['offered_unit_price'] * (float) $item->qty, 2),
                ]);
            }
            $quotation->update([
                'status' => QuotationStatus::Requested,
                'valid_until' => $snapshot['valid_until'],
                'discount_amount' => $snapshot['discount_amount'],
                'tax_amount' => $snapshot['tax_amount'],
                'priced_at' => null,
                'priced_by' => null,
            ]);
            $this->recalculate($quotation);

            return $quotation->fresh(['items']);
        });
    }

    /**
     * Credit and stock problems that would otherwise appear only when the trader accepts.
     *
     * @return list<string>
     */
    public function acceptanceWarnings(Quotation $quotation): array
    {
        $quotation->loadMissing(['customer', 'items.variant']);
        $warnings = [];
        $customer = $quotation->customer;
        if ($customer !== null) {
            $outstanding = app(WholesalePaymentNoticeService::class)->outstandingBalance($customer);
            $over = round($outstanding + (float) $quotation->grand_total - (float) $customer->credit_limit, 2);
            if ($over > 0) {
                $warnings[] = 'العرض ده لو اتقبل هيعدّي حد الائتمان بـ '.number_format($over, 2, '.', ',').'. التاجر هيشوف خطأ وقت القبول.';
            }
        }

        $short = false;
        foreach ($quotation->items as $item) {
            $available = (float) StockLevel::query()
                ->where('product_variant_id', $item->product_variant_id)
                ->sum(DB::raw('COALESCE(on_hand, 0) - COALESCE(reserved, 0) - COALESCE(damaged, 0)'));
            if ($available + 0.00001 < (float) $item->qty) {
                $short = true;
                $sku = $item->variant?->sku ?? '#'.$item->product_variant_id;
                $warnings[] = "الصنف {$sku} متاح منه ".number_format($available, 2, '.', '').' والمطلوب '.number_format((float) $item->qty, 2, '.', '').'. القبول هيفشل لو مفيش توريد.';
            }
        }
        if ($short) {
            $warnings[] = 'لو المخزون مش هيتعوّض قبل القبول، قصّر مدة صلاحية العرض.';
        }

        return $warnings;
    }

    /**
     * Synchronize requested line items and initial pricing for a quotation.
     *
     * @param  Quotation  $quotation  Parent quotation instance.
     * @param  Customer  $customer  Customer instance to resolve tiered pricing.
     * @param  list<array{product_variant_id: int, qty: float, requested_target_price?: float|null}>  $items
     *
     * @throws BusinessException If any variant is non-existent or inactive.
     */
    private function syncItems(Quotation $quotation, Customer $customer, array $items): void
    {
        $variantIds = array_column($items, 'product_variant_id');
        $variants = ProductVariant::query()
            ->whereIn('id', $variantIds)
            ->where('is_active', true)
            ->get()
            ->keyBy('id');

        foreach ($items as $row) {
            $variant = $variants->get($row['product_variant_id']);

            if ($variant === null) {
                throw new BusinessException('أحد المتغيرات المطلوبة غير موجود أو غير نشط.');
            }

            $offered = $this->pricing->resolve($variant, $customer, (float) $row['qty'])['unit_price'];

            $quotation->items()->create([
                'product_variant_id' => $variant->id,
                'qty' => $row['qty'],
                'requested_target_price' => $row['requested_target_price'] ?? null,
                'offered_unit_price' => $offered,
                'line_total' => round($offered * (float) $row['qty'], 2),
            ]);
        }
    }

    /**
     * Recalculate quotation subtotal and grand total.
     *
     *
     * @throws BusinessException If discount exceeds gross total resulting in a negative total.
     */
    private function recalculate(Quotation $quotation): void
    {
        $subtotal = (float) $quotation->items()->sum('line_total');
        $grandTotal = round($subtotal - (float) $quotation->discount_amount + (float) $quotation->tax_amount, 2);

        // Grand total cannot drop below zero; negative sums indicate an excessive discount that violates accounting boundaries.
        if ($grandTotal < 0) {
            throw new BusinessException('إجمالي عرض السعر لا يمكن أن يكون سالبًا — راجع الخصم.');
        }

        $quotation->update([
            'subtotal' => $subtotal,
            'grand_total' => $grandTotal,
        ]);
    }
}<?php

declare(strict_types=1);

namespace App\Services;

use App\Enums\OrderStatus;
use App\Enums\StockBucket;
use App\Enums\StockMovementType;
use App\Exceptions\BusinessException;
use App\Models\Branch;
use App\Models\Order;
use App\Models\OrderItem;
use App\Models\StockLevel;
use App\Models\StockMovement;
use Illuminate\Database\Eloquent\Builder;
use Illuminate\Support\Collection;
use Illuminate\Support\Facades\DB;

/**
 * Allocates and reserves order inventory across branches based on proximity, stock availability, and split policies.
 */
class OrderAllocationService
{
    private const NON_ALLOCATABLE_STATUSES = [
        OrderStatus::Cancelled,
        OrderStatus::Shipped,
        OrderStatus::Delivered,
        OrderStatus::Returned,
    ];

    public function __construct(protected InventoryService $inventoryService) {}

    /**
     * Load order items and sort by variant ID to establish consistent lock ordering against deadlocks.
     */
    private function prepareOrderItemsForAllocation(Order $order): void
    {
        $order->load('items');
        $order->setRelation('items', $order->items
            ->sortBy(fn (OrderItem $item): int => (int) $item->product_variant_id)
            ->values());
    }

    /**
     * Allocates order items to branch inventory and reserves stock atomically.
     *
     * @param Order $order Placed order to allocate
     * @param int|null $forcedBranchId Manually selected branch by administrator, if any
     * @param int|null $performedBy User ID performing the allocation
     * @return Order Updated order with allocated branches
     * @throws BusinessException If order is in invalid status, already allocated, or insufficient stock
     */
    public function allocate(Order $order, ?int $forcedBranchId = null, ?int $performedBy = null): Order
    {
        return DB::transaction(function () use ($order, $forcedBranchId, $performedBy): Order {
            // Re-read order under row lock to prevent concurrent allocation attempts.
            $order = Order::query()->lockForUpdate()->findOrFail($order->id);
            $this->prepareOrderItemsForAllocation($order);
            $performedBy ??= auth()->id();

            if (in_array($order->status, self::NON_ALLOCATABLE_STATUSES, true)) {
                throw new BusinessException('التوزيع غير متاح على هذه الحالة.');
            }

            if ($this->isAllocated($order)) {
                throw new BusinessException('الطلب مُوزّع على الفروع من قبل؛ ألغِ التوزيع الحالي أولًا قبل إعادة التوزيع.');
            }

            if ($forcedBranchId !== null) {
                $branch = Branch::query()->where('is_active', true)->find($forcedBranchId);
                if ($branch === null) {
                    throw new BusinessException('الفرع المحدد غير موجود أو غير نشط.');
                }
                $this->reserveItemsFromBranch($order, $branch->id, $performedBy);
                $order->update(['allocated_branch_id' => $branch->id]);

                return $order->fresh(['items']);
            }

            // Pre-calculate aggregate branch availability to evaluate allocation rules in memory.
            $coverage = $this->branchAvailabilityMap($order);

            $cityName = $order->city?->name_ar;
            $branches = Branch::query()
                ->where('is_active', true)
                ->when($order->city_id !== null, fn (Builder $q): Builder => $q->orderByRaw('CASE WHEN city_id = ? THEN 0 ELSE 1 END', [$order->city_id]))
                // Use CASE ordering instead of DESC because Postgres places NULLs first in DESC sorting.
                ->when($cityName !== null, fn (Builder $q): Builder => $q->orderByRaw('CASE WHEN city = ? THEN 0 ELSE 1 END', [$cityName]))
                ->orderBy('id')
                ->get();

            $candidateAttempts = 0;
            foreach ($branches as $branch) {
                if ($this->canBranchFulfillFullOrder($order, $branch->id, $coverage)) {
                    if (++$candidateAttempts > 3) {
                        break;
                    }
                    try {
                        return DB::transaction(function () use ($order, $branch, $performedBy): Order {
                            $this->reserveItemsFromBranch($order, $branch->id, $performedBy);
                            $order->update(['allocated_branch_id' => $branch->id]);

                            return $order->fresh(['items']);
                        });
                    } catch (BusinessException $e) {
                        if ($e->errorCode !== 'insufficient_stock') {
                            throw $e;
                        }
                        $order->load('items');
                    }
                }
            }

            // A bounded retry recalculates coverage after a competing checkout.
            for ($attempt = 0; $attempt < 3; $attempt++) {
                $coverage = $this->branchAvailabilityMap($order);
                // Aggregate required quantity per variant so duplicate items do not choose an insufficient branch.
                $required = $this->requiredPerVariant($order);
                $plan = [];
                foreach ($order->items as $item) {
                    $variantId = (int) $item->product_variant_id;
                    if (array_key_exists($variantId, $plan)) {
                        continue;
                    }
                    $branchId = $this->bestBranchForItem($item, $coverage, $required[$variantId]);
                    if ($branchId === null) {
                        throw new BusinessException("الرصيد المتاح للصنف [{$item->sku_snapshot}] غير كافٍ لإتمام الطلب.");
                    }
                    $plan[$variantId] = $branchId;
                }
                try {
                    return DB::transaction(function () use ($order, $plan, $performedBy): Order {
                        $levels = $this->lockPlannedLevels($plan);
                        foreach ($order->items as $item) {
                            $branchId = $plan[(int) $item->product_variant_id];
                            $this->reserveItemFromBranch($order, $item, $branchId, $performedBy, $levels);
                            $item->update(['allocated_branch_id' => $branchId]);
                        }

                        return $order->fresh(['items']);
                    });
                } catch (BusinessException $e) {
                    if ($e->errorCode !== 'insufficient_stock' || $attempt === 2) {
                        throw $e;
                    }
                    $order->load('items');
                }
            }
            throw new BusinessException('تغير المخزون أثناء الحجز؛ أعد المحاولة.', [], 409);
        });
    }

    /**
     * Releases all inventory reservations tied to an allocated order and clears allocation state.
     *
     * @param Order $order Order to deallocate
     * @param int|null $performedBy User ID performing the action
     * @return Order Deallocated order instance
     * @throws BusinessException If order cannot be deallocated
     */
    public function deallocate(Order $order, ?int $performedBy = null): Order
    {
        return DB::transaction(function () use ($order, $performedBy): Order {
            $order = Order::query()->lockForUpdate()->findOrFail($order->id);
            $this->prepareOrderItemsForAllocation($order);
            $performedBy ??= auth()->id();

            if (in_array($order->status, self::NON_ALLOCATABLE_STATUSES, true)) {
                throw new BusinessException('فك التوزيع غير متاح على هذه الحالة.');
            }

            if (! $this->isAllocated($order)) {
                throw new BusinessException('الطلب غير موزّع على أي فرع؛ لا شيء لفكه.');
            }

            // Calculate net reservations from ledger movements so deallocations remain idempotent.
            $net = StockMovement::query()
                ->whereIn('reference_type', array_unique([$order->getMorphClass(), Order::class]))
                ->where('reference_id', $order->id)
                ->whereIn('type', [StockMovementType::Reserve->value, StockMovementType::ReleaseReserve->value])
                ->groupBy('product_variant_id', 'branch_id', 'location_id')
                ->selectRaw('product_variant_id, branch_id, location_id, SUM(quantity) AS net_qty')
                ->get()
                ->map(fn ($row): array => [
                    'product_variant_id' => (int) $row->product_variant_id,
                    'branch_id' => (int) $row->branch_id,
                    'location_id' => $row->location_id === null ? null : (int) $row->location_id,
                    'net_qty' => (float) $row->net_qty,
                ])
                ->filter(fn (array $row): bool => $row['net_qty'] > 1e-9)
                ->sortBy(fn (array $row): string => $row['branch_id'].':'.$row['location_id'].':'.$row['product_variant_id'])
                ->values();

            $levels = $this->inventoryService->lockLevels($net->map(fn (array $row): array => [
                'product_variant_id' => $row['product_variant_id'],
                'branch_id' => $row['branch_id'],
                'location_id' => $row['location_id'],
            ])->all());

            foreach ($net as $row) {
                $this->inventoryService->recordMovement([
                    'product_variant_id' => (int) $row['product_variant_id'],
                    'branch_id' => (int) $row['branch_id'],
                    'location_id' => $row['location_id'],
                    'type' => StockMovementType::ReleaseReserve,
                    'affected_bucket' => StockBucket::Reserved,
                    'quantity' => -1 * (float) $row['net_qty'],
                    'reference_type' => Order::class,
                    'reference_id' => $order->id,
                    'created_by' => $performedBy,
                    'notes' => "فك يدوي لتوزيع الطلب رقم {$order->order_number}",
                ], $levels->get($this->inventoryService->levelKey($row)));
            }

            $order->items()->update(['allocated_branch_id' => null]);
            $order->update(['allocated_branch_id' => null]);

            return $order->fresh(['items']);
        });
    }

    /**
     * Checks whether an order or any of its items has an allocated branch.
     *
     * @param Order $order Order to check
     * @return bool True if allocated at order level or item level
     */
    public function isAllocated(Order $order): bool
    {
        return $order->allocated_branch_id !== null
            || $order->items->contains(fn (OrderItem $item): bool => $item->allocated_branch_id !== null);
    }

    /** Lock only the branch/variant pairs selected by the coverage plan. */
    private function lockPlannedLevels(array $plan): Collection
    {
        if ($plan === []) {
            return collect();
        }
        $rows = StockLevel::query()->where(function ($query) use ($plan): void {
            foreach ($plan as $variantId => $branchId) {
                $query->orWhere(fn ($q) => $q->where('product_variant_id', $variantId)->where('branch_id', $branchId));
            }
        })->where(fn ($q) => $q->whereNull('location_id')->orWhereHas('location', fn ($q) => $q->where('is_active', true)->whereNotIn('type', ['receiving', 'damaged'])))->get();

        return $this->inventoryService->lockLevels($rows->map->getAttributes()->all());
    }

    private function branchAvailabilityMap(Order $order): array
    {
        $variantIds = $order->items
            ->map(fn (OrderItem $item): int => (int) $item->product_variant_id)
            ->unique()->values()->all();

        $rows = StockLevel::query()
            ->whereIn('product_variant_id', $variantIds)
            ->whereHas('branch', fn (Builder $q): Builder => $q->where('is_active', true))
            ->where(fn (Builder $q): Builder => $q
                ->whereNull('location_id')
                ->orWhereHas('location', fn (Builder $l): Builder => $l->where('is_active', true)->whereNotIn('type', ['receiving', 'damaged'])))
            ->groupBy('branch_id', 'product_variant_id')
            ->selectRaw('branch_id, product_variant_id, SUM(available) as total_available')
            ->get();

        $map = [];
        foreach ($rows as $row) {
            $map[(int) $row->branch_id][(int) $row->product_variant_id] = (float) $row->total_available;
        }

        return $map;
    }

    private function requiredPerVariant(Order $order): array
    {
        $required = [];
        foreach ($order->items as $item) {
            $vid = (int) $item->product_variant_id;
            $required[$vid] = ($required[$vid] ?? 0) + (int) round((float) $item->qty * 10000);
        }

        return $required;
    }

    private function canBranchFulfillFullOrder(Order $order, int $branchId, array $coverage): bool
    {
        foreach ($this->requiredPerVariant($order) as $variantId => $qty) {
            if ((int) round(($coverage[$branchId][$variantId] ?? 0) * 10000) < $qty) {
                return false;
            }
        }

        return true;
    }

    private function bestBranchForItem(OrderItem $item, array $coverage, ?int $requiredQty = null): ?int
    {
        $need = $requiredQty ?? (int) round((float) $item->qty * 10000);
        $best = null;
        $bestAvailable = 0.0;
        foreach ($coverage as $branchId => $variants) {
            $available = $variants[(int) $item->product_variant_id] ?? 0;
            if ((int) round($available * 10000) >= $need && $available > $bestAvailable) {
                $best = $branchId;
                $bestAvailable = $available;
            }
        }

        return $best;
    }

    private function reserveItemsFromBranch(Order $order, int $branchId, ?int $performedBy): void
    {
        $levels = $this->lockPlannedLevels($order->items->mapWithKeys(fn ($item) => [(int) $item->product_variant_id => $branchId])->all());
        foreach ($order->items as $item) {
            $this->reserveItemFromBranch($order, $item, $branchId, $performedBy, $levels);
            $item->update(['allocated_branch_id' => $branchId]);
        }
    }

    private function reserveItemFromBranch(Order $order, OrderItem $item, int $branchId, ?int $performedBy, Collection $levels): void
    {
        $remaining = (int) round((float) $item->qty * 10000);
        foreach ($levels->where('product_variant_id', $item->product_variant_id)->where('branch_id', $branchId)->sortByDesc('available') as $level) {
            $take = min((int) round($level->available * 10000), $remaining);
            if ($take <= 0) {
                continue;
            }
            $this->inventoryService->recordMovement([
                'product_variant_id' => (int) $item->product_variant_id, 'branch_id' => $branchId,
                'location_id' => $level->location_id, 'type' => StockMovementType::Reserve,
                'affected_bucket' => StockBucket::Reserved, 'quantity' => $take / 10000,
                'reference_type' => Order::class, 'reference_id' => $order->id,
                'created_by' => $performedBy, 'notes' => 'حجز للطلب '.$order->order_number,
            ], $level);
            $remaining -= $take;
            if ($remaining === 0) {
                break;
            }
        }
        if ($remaining > 0) {
            throw new BusinessException('الرصيد المتاح تغير أثناء الحجز.', errorCode: 'insufficient_stock');
        }
    }
}<?php

declare(strict_types=1);

namespace App\Services;

use App\Enums\CustomerStatus;
use App\Enums\PriceListType;
use App\Exceptions\BusinessException;
use App\Models\Customer;
use App\Models\PriceList;
use App\Models\PriceListItem;
use App\Models\ProductVariant;
use Brick\Math\BigDecimal;
use Brick\Math\RoundingMode;
use Carbon\Carbon;
use Illuminate\Database\Eloquent\Builder;
use Illuminate\Support\Collection;

/**
 * Central pricing engine across storefront, wholesale portal, POS, and admin backoffice.
 *
 * Evaluation hierarchy:
 * 1. Customer-specific price list (customer_specific)
 * 2. Customer group price list (customer_group)
 * 3. Channel price list (wholesale/distributor for approved accounts, otherwise retail).
 *    Wholesale/distributor channels without a matching item fall back to active retail lists.
 * 4. Channel base price (wholesale_price for wholesale/distributor, then retail_price).
 *
 * Customer group discount percentages apply on top of tier 3/4 channel outcomes without
 * overriding customer-specific or group-specific price lists.
 * Within each tier: branch-specific list first, highest qualifying min_qty, highest priority, lowest price.
 */
class PricingService
{
    private array $catalogContexts = [];

    /**
     * Resolves cache key and public visibility context for customer catalog listings.
     *
     * @return array{key: string, public_retail: bool}
     */
    public function catalogContext(?Customer $customer): array
    {
        if ($customer === null || $customer->status !== CustomerStatus::Approved) {
            return ['key' => 'retail', 'public_retail' => true];
        }

        return $this->catalogContexts[$customer->id] ??= $this->resolveCatalogContext($customer);
    }

    /**
     * Builds the unique catalog pricing context key for an approved customer.
     */
    private function resolveCatalogContext(Customer $customer): array
    {
        $customer->loadMissing('customerGroup');
        $group = $customer->customerGroup?->is_active ? $customer->customerGroup : null;
        $specific = PriceList::query()->where('type', PriceListType::CustomerSpecific)->where('customer_id', $customer->id)->exists();
        $channel = $this->channelFor($customer);
        $public = $channel === PriceListType::Retail && $group === null && ! $specific;

        return ['key' => $public ? 'retail' : $channel->value.':group:'.($group?->id ?? 'none').($specific ? ':customer:'.$customer->id : ''), 'public_retail' => $public];
    }

    /**
     * Preloads the per-customer pricing context once per listing and passes
     * it down — resolve()/tiersFor() otherwise re-query the customer group on
     * every variant (15 products x variants x calls per page).
     *
     * @return array{channel: PriceListType, eligible: bool, group: object|null}
     */
    public function contextFor(?Customer $customer, ?array $variantIds = null): array
    {
        $eligible = $customer !== null && $customer->status === CustomerStatus::Approved;
        if ($eligible) {
            $customer->loadMissing('customerGroup');
        }
        $group = $eligible && $customer->customerGroup?->is_active ? $customer->customerGroup : null;

        $channel = $this->channelFor($customer);
        $context = ['channel' => $channel, 'eligible' => $eligible, 'group' => $group];
        if ($variantIds !== null) {
            $context['items'] = $this->eligibleItems(null, PHP_FLOAT_MAX, null, Carbon::now(), $variantIds)
                ->where(function ($q) use ($channel, $eligible, $customer, $group): void {
                    $q->whereIn('price_lists.type', array_unique([$channel->value, PriceListType::Retail->value]));
                    if ($eligible) {
                        $q->orWhere(fn ($owner) => $owner->where('price_lists.type', PriceListType::CustomerSpecific)
                            ->where('price_lists.customer_id', $customer->id));
                    }
                    if ($group !== null) {
                        $q->orWhere(fn ($owner) => $owner->where('price_lists.type', PriceListType::CustomerGroup)
                            ->where('price_lists.customer_group_id', $group->id));
                    }
                })
                ->addSelect('price_lists.type as pricing_type', 'price_lists.branch_id as pricing_branch_id', 'price_lists.priority as pricing_priority')
                ->get()->groupBy('product_variant_id');
        }

        return $context;
    }

    /** Resolve storefront prices in SQL using the same owner, tier and priority rules as resolve(). */
    public function withStorePrice(Builder $variants, ?Customer $customer): Builder
    {
        $eligible = $customer !== null && $customer->status === CustomerStatus::Approved;
        $channel = $this->channelFor($customer);
        $group = $eligible ? $customer->customerGroup : null;
        $group = $group?->is_active ? $group : null;
        $factor = $this->discountFactor($group?->discount_percentage ?? '0');
        $items = $this->eligibleItems(null, 1, null, Carbon::now())
            ->where(function ($q) use ($eligible, $customer, $group, $channel): void {
                $q->whereIn('price_lists.type', array_unique([$channel->value, PriceListType::Retail->value]));
                if ($eligible) {
                    $q->orWhere(fn ($q) => $q->where('price_lists.type', PriceListType::CustomerSpecific)
                        ->where('price_lists.customer_id', $customer->id));
                }
                if ($group !== null) {
                    $q->orWhere(fn ($q) => $q->where('price_lists.type', PriceListType::CustomerGroup)
                        ->where('price_lists.customer_group_id', $group->id));
                }
            })
            ->select([])
            ->selectRaw("price_list_items.price * CASE WHEN price_lists.type IN ('customer_specific', 'customer_group') THEN 1::numeric ELSE ?::numeric END", [$factor])
            ->orderByRaw("CASE WHEN price_lists.type = 'customer_specific' THEN 0 WHEN price_lists.type = 'customer_group' THEN 1 WHEN price_lists.type = ? THEN 2 ELSE 3 END", [$channel->value]);
        $items = $this->ordered($items)->limit(1);

        // Mirror basePrice() hierarchy in SQL: wholesale channels fallback to wholesale_price before retail_price.
        $fallback = in_array($channel, [PriceListType::Wholesale, PriceListType::Distributor], true)
            ? 'COALESCE(product_variants.wholesale_price, product_variants.retail_price)'
            : 'product_variants.retail_price';

        // resolve() switches the basis to retail when a wholesale customer
        // falls back to a retail list. Preserve that effective channel in SQL.
        $baseItems = (clone $items)->select([])->selectRaw("COALESCE(CASE WHEN price_lists.type = 'retail' THEN product_variants.retail_price ELSE ".$fallback." END, price_list_items.price * CASE WHEN price_lists.type IN ('customer_specific', 'customer_group') THEN 1::numeric ELSE ?::numeric END)", [$factor]);

        return $variants->select('product_variants.*')
            ->selectRaw('ROUND(COALESCE(('.$items->toSql().'), '.$fallback.' * ?)::numeric, 2) AS store_price', [...$items->getBindings(), $factor])
            ->selectRaw('ROUND(COALESCE(('.$baseItems->toSql().'), '.$fallback.')::numeric, 2) AS store_base_price', $baseItems->getBindings());
    }

    /**
     * Resolves the effective unit price, base reference price, and pricing source for a variant.
     *
     * @param  float  $qty  Purchasing quantity used for volume tier matching.
     * @param  int|null  $branchId  Optional branch restriction for branch-specific price lists.
     * @param  array{channel: PriceListType, eligible: bool, group: object|null, items?: Collection}|null  $ctx  Preloaded pricing context.
     * @return array{unit_price: float, base_price: float, source: string, price_list_id: int|null}
     *
     * @throws BusinessException If quantity is non-positive or item has no valid price.
     */
    public function resolve(
        ProductVariant $variant,
        ?Customer $customer = null,
        float $qty = 1,
        ?int $branchId = null,
        ?array $ctx = null,
    ): array {
        if (! is_finite($qty) || $qty <= 0) {
            throw new BusinessException('كمية التسعير يجب أن تكون موجبة.');
        }
        $now = Carbon::now();

        // Reuse preloaded customer pricing context if supplied by bulk callers to prevent redundant queries.
        $ctx ??= $this->contextFor($customer);
        $baseQuery = $this->eligibleItems($variant, $qty, $branchId, $now);
        $channel = $ctx['channel'];
        $eligibleCustomer = $ctx['eligible'];
        $pick = fn (PriceListType $type, ?string $ownerField = null, ?int $ownerId = null): ?PriceListItem => $this->pickWinningItem($type, $ownerField, $ownerId, $variant, $qty, $branchId, $baseQuery, $ctx);

        // Priority 1: Customer-specific pricing.
        if ($eligibleCustomer) {
            $item = $pick(PriceListType::CustomerSpecific, 'customer_id', $customer->id);

            if ($item !== null) {
                return $this->formatResponse($item->price, PriceListType::CustomerSpecific->value, (int) $item->price_list_id, $variant, $channel);
            }
        }

        // Priority 2: Customer group pricing.
        $group = $ctx['group'];
        if ($group !== null) {
            $item = $pick(PriceListType::CustomerGroup, 'customer_group_id', $group->id);

            if ($item !== null) {
                return $this->formatResponse($item->price, PriceListType::CustomerGroup->value, (int) $item->price_list_id, $variant, $channel);
            }
        }

        // Priority 3: Customer channel price list (wholesale, distributor, or retail).
        $item = $pick($channel);

        // Wholesale/distributor channels without matched items fall back to active retail price lists.
        if ($item === null && $channel !== PriceListType::Retail) {
            $item = $pick(PriceListType::Retail);

            if ($item !== null) {
                $channel = PriceListType::Retail;
            }
        }

        if ($item !== null) {
            $channelPrice = (string) $item->price;
            $channelListId = (int) $item->price_list_id;
            $channelSource = $channel->value;
        } elseif ($this->basePrice($variant, $channel) === null) {
            // Priority 4 is impossible: unpriced item without matching price list or base price.
            throw new BusinessException('الصنف غير مُسعَّر: لا توجد قائمة أسعار مطابقة ولا سعر قطاعي للمتغير.');
        } else {
            // Priority 4: Channel base price when no price list matches.
            $channelPrice = $this->basePrice($variant, $channel);
            $channelListId = null;
            $channelSource = 'base_price';
        }

        // Apply customer group discount percentage on top of channel list/base price.
        if ($group !== null && (float) $group->discount_percentage > 0) {
            return $this->formatResponse(
                (string) BigDecimal::of($channelPrice)->multipliedBy($this->discountFactor($group->discount_percentage)),
                'customer_group_discount',
                $channelListId,
                $variant,
                $channel,
            );
        }

        return $this->formatResponse($channelPrice, $channelSource, $channelListId, $variant, $channel);
    }

    /**
     * Resolves the effective unit price with a per-layer explanation waterfall.
     *
     * @return array{final: array, layers: list<array>, notes: list<string>}
     */
    public function trace(ProductVariant $variant, ?Customer $customer = null, float $qty = 1, ?int $branchId = null, ?array $ctx = null): array
    {
        if (! is_finite($qty) || $qty <= 0) {
            throw new BusinessException('كمية التسعير يجب أن تكون موجبة.');
        }
        $now = Carbon::now();
        $ctx ??= $this->contextFor($customer);
        $baseQuery = $this->eligibleItems($variant, $qty, $branchId, $now);
        $channel = $ctx['channel'];
        $eligibleCustomer = $ctx['eligible'];
        $group = $ctx['group'];
        $layers = [];
        $notes = [];

        if ($customer !== null
            && $customer->isCommercialTier()
            && $customer->status !== CustomerStatus::Approved) {
            $notes[] = 'العميل جملة لكنه مش معتمد، فاتسعّر قطاعي.';
        }

        $pick = fn (PriceListType $type, ?string $ownerField = null, ?int $ownerId = null): ?PriceListItem => $this->pickWinningItem($type, $ownerField, $ownerId, $variant, $qty, $branchId, $baseQuery, $ctx);

        $tieNote = function (PriceListType $type, ?string $ownerField, ?int $ownerId, ?PriceListItem $winner) use ($ctx, $baseQuery, $branchId, &$notes): void {
            if ($winner === null || (isset($ctx['items']) && $branchId === null)) {
                return;
            }
            $top = $this->ordered((clone $baseQuery)->where('price_lists.type', $type)
                ->when($ownerField !== null, fn ($q) => $q->where('price_lists.'.$ownerField, $ownerId)))
                ->limit(2)->get(['price_list_items.id', 'price_list_items.min_qty', 'price_list_items.price', 'price_lists.priority', 'price_lists.branch_id']);
            if ($top->count() === 2
                && (int) $top[0]->priority === (int) $top[1]->priority
                && (float) $top[0]->min_qty === (float) $top[1]->min_qty
                && ($top[0]->branch_id === null) === ($top[1]->branch_id === null)
                && (float) $top[0]->price !== (float) $top[1]->price) {
                $notes[] = 'فيه قائمتين بنفس الأولوية، فكسبت الأرخص.';
            }
        };

        $skippedRest = function (array $names) use (&$layers): void {
            foreach ($names as $n) {
                $layers[] = ['layer' => $n, 'status' => 'skipped', 'reason' => 'طبقة أعلى كسبت.'];
            }
        };

        if (! $eligibleCustomer) {
            $layers[] = ['layer' => 'customer_specific', 'status' => 'not_eligible', 'reason' => 'العميل مش معتمد أو زائر، فقوائم العملاء الخاصة مش بتتطبق.', 'price_list_id' => null, 'price' => null, 'min_qty' => null];
            if ($customer !== null) {
                $specificId = PriceList::query()->where('type', PriceListType::CustomerSpecific)->where('customer_id', $customer->id)->orderByDesc('id')->value('id');
                if ($specificId !== null) {
                    $notes[] = "عنده قائمة خاصة رقم {$specificId}، بس العميل مش approved، فالقائمة دي مش بتتطبق.";
                }
            }
        } else {
            $item = $pick(PriceListType::CustomerSpecific, 'customer_id', $customer->id);
            if ($item !== null) {
                $tieNote(PriceListType::CustomerSpecific, 'customer_id', $customer->id, $item);
                $layers[] = ['layer' => 'customer_specific', 'status' => 'won', 'reason' => 'قائمة العميل الخاصة كسبت.', 'price_list_id' => (int) $item->price_list_id, 'price' => (float) $item->price, 'min_qty' => (float) $item->min_qty];
                $skippedRest(['customer_group', 'channel', 'retail_fallback', 'base_price']);
                $layers[] = ['layer' => 'group_discount', 'status' => 'skipped', 'reason' => 'خصم المجموعة 10% ماتطبقش لأن السعر جه من قائمة المجموعة نفسها.'];
                $final = $this->formatResponse($item->price, PriceListType::CustomerSpecific->value, (int) $item->price_list_id, $variant, $channel);

                return ['final' => $final, 'layers' => $layers, 'notes' => $notes];
            }
            $layers[] = ['layer' => 'customer_specific', 'status' => 'no_match', 'reason' => 'مفيش بند مطابق في قائمة العميل الخاصة.', 'price_list_id' => null, 'price' => null, 'min_qty' => null];
        }

        if ($group === null) {
            $layers[] = ['layer' => 'customer_group', 'status' => 'not_eligible', 'reason' => 'العميل مش في مجموعة نشطة، فقوائم المجموعات مش بتتطبق.', 'price_list_id' => null, 'price' => null, 'min_qty' => null];
        } else {
            $item = $pick(PriceListType::CustomerGroup, 'customer_group_id', $group->id);
            if ($item !== null) {
                $tieNote(PriceListType::CustomerGroup, 'customer_group_id', $group->id, $item);
                $layers[] = ['layer' => 'customer_group', 'status' => 'won', 'reason' => 'قائمة المجموعة كسبت.', 'price_list_id' => (int) $item->price_list_id, 'price' => (float) $item->price, 'min_qty' => (float) $item->min_qty];
                $skippedRest(['channel', 'retail_fallback', 'base_price']);
                $layers[] = ['layer' => 'group_discount', 'status' => 'skipped', 'reason' => 'خصم المجموعة 10% ماتطبقش لأن السعر جه من قائمة المجموعة نفسها.'];
                $final = $this->formatResponse($item->price, PriceListType::CustomerGroup->value, (int) $item->price_list_id, $variant, $channel);

                return ['final' => $final, 'layers' => $layers, 'notes' => $notes];
            }
            $layers[] = ['layer' => 'customer_group', 'status' => 'no_match', 'reason' => 'مفيش بند مطابق في قائمة المجموعة.', 'price_list_id' => null, 'price' => null, 'min_qty' => null];
        }

        $item = $pick($channel);
        $channelWon = false;
        $channelPrice = null;
        $channelListId = null;
        $channelSource = $channel->value;
        if ($item !== null) {
            $tieNote($channel, null, null, $item);
            $channelWon = true;
            $channelPrice = (string) $item->price;
            $channelListId = (int) $item->price_list_id;
            $layers[] = ['layer' => 'channel', 'status' => 'won', 'reason' => "قائمة القناة ({$channel->value}) كسبت.", 'price_list_id' => $channelListId, 'price' => (float) $item->price, 'min_qty' => (float) $item->min_qty];
        } else {
            $layers[] = ['layer' => 'channel', 'status' => 'no_match', 'reason' => "مفيش بند مطابق في قائمة القناة ({$channel->value}).", 'price_list_id' => null, 'price' => null, 'min_qty' => null];
        }

        if (! $channelWon && $channel !== PriceListType::Retail) {
            $retailItem = $pick(PriceListType::Retail);
            if ($retailItem !== null) {
                $tieNote(PriceListType::Retail, null, null, $retailItem);
                $channel = PriceListType::Retail;
                $channelWon = true;
                $channelPrice = (string) $retailItem->price;
                $channelListId = (int) $retailItem->price_list_id;
                $channelSource = $channel->value;
                $layers[] = ['layer' => 'retail_fallback', 'status' => 'won', 'reason' => 'القناة وقعت على قائمة قطاعي بديلة.', 'price_list_id' => $channelListId, 'price' => (float) $retailItem->price, 'min_qty' => (float) $retailItem->min_qty];
            } else {
                $layers[] = ['layer' => 'retail_fallback', 'status' => 'no_match', 'reason' => 'مفيش بند قطاعي بديل.', 'price_list_id' => null, 'price' => null, 'min_qty' => null];
            }
        } else {
            $layers[] = ['layer' => 'retail_fallback', 'status' => 'skipped', 'reason' => $channelWon ? 'القناة كسبت، فمش محتاج بديل قطاعي.' : 'القناة قطاعي بالفعل.', 'price_list_id' => null, 'price' => null, 'min_qty' => null];
        }

        if (! $channelWon) {
            $base = $this->basePrice($variant, $channel);
            if ($base === null) {
                throw new BusinessException('الصنف غير مُسعَّر: لا توجد قائمة أسعار مطابقة ولا سعر قطاعي للمتغير.');
            }
            $channelPrice = $base;
            $channelListId = null;
            $channelSource = 'base_price';
            $layers[] = ['layer' => 'base_price', 'status' => 'won', 'reason' => 'مفيش قوائم مطابقة، فاتسعّر بالسعر الأساسي.', 'price_list_id' => null, 'price' => (float) $base, 'min_qty' => null];
        } else {
            $layers[] = ['layer' => 'base_price', 'status' => 'skipped', 'reason' => 'قائمة كسبت، فالسعر الأساسي مش مستخدم.', 'price_list_id' => null, 'price' => null, 'min_qty' => null];
        }

        if ($group !== null && (float) $group->discount_percentage > 0) {
            $layers[] = ['layer' => 'group_discount', 'status' => 'won', 'reason' => "خصم المجموعة {$group->discount_percentage}% اتطبق على سعر القناة/الأساسي.", 'price_list_id' => $channelListId, 'price' => null, 'min_qty' => null];
            $final = $this->formatResponse(
                (string) BigDecimal::of($channelPrice)->multipliedBy($this->discountFactor($group->discount_percentage)),
                'customer_group_discount',
                $channelListId,
                $variant,
                $channel,
            );

            return ['final' => $final, 'layers' => $layers, 'notes' => $notes];
        }

        $layers[] = ['layer' => 'group_discount', 'status' => 'skipped', 'reason' => 'مفيش خصم مجموعة يتطبق.', 'price_list_id' => null, 'price' => null, 'min_qty' => null];
        $final = $this->formatResponse($channelPrice, $channelSource, $channelListId, $variant, $channel);

        return ['final' => $final, 'layers' => $layers, 'notes' => $notes];
    }

    /**
     * Returns the step-ladder volume pricing tiers applicable to a customer for a variant.
     *
     * @return list<array{min_qty: float, unit_price: float}>}
     * @return list<array{min_qty: float, unit_price: float}>
     */
    public function tiersFor(ProductVariant $variant, ?Customer $customer, ?array $ctx = null, ?int $branchId = null): array
    {
        $now = Carbon::now();
        // Reuse preloaded customer pricing context when available to prevent redundant group queries.
        $ctx ??= $this->contextFor($customer);
        $channel = $ctx['channel'];
        $eligible = $ctx['eligible'];
        $groupId = $ctx['group']?->id;

        $breakpoints = isset($ctx['items']) && $branchId === null
            ? ($ctx['items'][$variant->id] ?? collect())->pluck('min_qty')->map(fn ($v) => (float) $v)
            : $this->eligibleItems($variant, PHP_FLOAT_MAX, $branchId, $now)
                ->where(function ($q) use ($eligible, $customer, $groupId, $channel): void {
                    $q->where('price_lists.type', $channel->value)
                        ->orWhere('price_lists.type', PriceListType::Retail->value);
                    if ($eligible) {
                        $q->orWhere(fn ($q) => $q->where('price_lists.type', PriceListType::CustomerSpecific)
                            ->where('price_lists.customer_id', $customer->id));
                    }
                    if ($groupId !== null) {
                        $q->orWhere(fn ($q) => $q->where('price_lists.type', PriceListType::CustomerGroup)
                            ->where('price_lists.customer_group_id', $groupId));
                    }
                })
                ->pluck('price_list_items.min_qty')
                ->map(fn ($v) => (float) $v)
                ->unique()
                ->sort()
                ->values();

        $points = collect([1.0])->merge($breakpoints)->unique()->sort()->values();

        return $points
            ->map(fn (float $minQty) => [
                'min_qty' => $minQty,
                'unit_price' => $this->resolve($variant, $customer, max(1.0, $minQty), $branchId, $ctx)['unit_price'],
            ])
            ->values()
            ->all();
    }

    /**
     * Resolves the pricing channel enum: approved wholesale/distributor accounts use their channel; all others use Retail.
     */
    private function channelFor(?Customer $customer): PriceListType
    {
        if ($customer?->isWholesaleApproved()) {
            return PriceListType::from($customer->type->value);
        }

        return PriceListType::Retail;
    }

    private function basePrice(ProductVariant $variant, PriceListType $channel): ?string
    {
        // Wholesale channels prefer wholesale_price and fall back to retail_price when unassigned.
        if (in_array($channel, [PriceListType::Wholesale, PriceListType::Distributor], true)
            && $variant->wholesale_price !== null) {
            return (string) $variant->wholesale_price;
        }

        return $variant->retail_price === null ? null : $variant->base_price;
    }

    /**
     * Returns the base catalog reference price for a variant under the customer's channel.
     */
    public function basePriceForCustomer(ProductVariant $variant, ?Customer $customer): ?string
    {
        return $this->basePrice($variant, $this->channelFor($customer));
    }

    /**
     * Converts a percentage discount string (e.g. "15.00") into a decimal multiplication factor (0.85).
     */
    private function discountFactor(string $percentage): string
    {
        return (string) BigDecimal::of('100')->minus($percentage)->dividedBy('100', 8);
    }

    /**
     * Query scope for active price list items matching variant, quantity threshold, branch, and current time.
     */
    private function eligibleItems(?ProductVariant $variant, float $qty, ?int $branchId, Carbon $now, ?array $variantIds = null): Builder
    {
        return PriceListItem::query()
            ->select('price_list_items.*')
            ->join('price_lists', 'price_lists.id', '=', 'price_list_items.price_list_id')
            ->where('price_lists.is_active', true)
            ->when($variant !== null,
                fn ($q) => $q->where('price_list_items.product_variant_id', $variant->id),
                fn ($q) => $variantIds !== null
                    ? $q->whereIn('price_list_items.product_variant_id', $variantIds)
                    : $q->whereColumn('price_list_items.product_variant_id', 'product_variants.id'))
            ->where('price_list_items.min_qty', '<=', $qty)
            ->where(fn ($q) => $q->whereNull('price_lists.starts_at')->orWhere('price_lists.starts_at', '<=', $now))
            ->where(fn ($q) => $q->whereNull('price_lists.ends_at')->orWhere('price_lists.ends_at', '>=', $now))
            ->where(fn ($q) => $q->whereNull('price_list_items.starts_at')->orWhere('price_list_items.starts_at', '<=', $now))
            ->where(fn ($q) => $q->whereNull('price_list_items.ends_at')->orWhere('price_list_items.ends_at', '>=', $now))
            ->where(function ($q) use ($branchId): void {
                $q->whereNull('price_lists.branch_id');
                if ($branchId !== null) {
                    $q->orWhere('price_lists.branch_id', $branchId);
                }
            });
    }

    /**
     * Pick the winning price list item matching the specified type and ownership scope.
     */
    private function pickWinningItem(
        PriceListType $type,
        ?string $ownerField,
        ?int $ownerId,
        ProductVariant $variant,
        float $qty,
        ?int $branchId,
        Builder $baseQuery,
        array $ctx,
    ): ?PriceListItem {
        if (isset($ctx['items']) && $branchId === null) {
            return ($ctx['items'][$variant->id] ?? collect())
                ->filter(fn ($item) => $item->pricing_type === $type->value && (float) $item->min_qty <= $qty)
                ->sort(function ($a, $b): int {
                    return (($a->pricing_branch_id === null) <=> ($b->pricing_branch_id === null))
                        ?: ((float) $b->min_qty <=> (float) $a->min_qty)
                        ?: ((int) $b->pricing_priority <=> (int) $a->pricing_priority)
                        ?: BigDecimal::of($a->price)->compareTo(BigDecimal::of($b->price))
                        ?: ((int) $a->id <=> (int) $b->id);
                })->first();
        }

        return $this->ordered((clone $baseQuery)->where('price_lists.type', $type)
            ->when($ownerField !== null, fn ($q) => $q->where('price_lists.'.$ownerField, $ownerId)))->first();
    }

    /**
     * Sorts candidate price list items: branch-specific first, highest min_qty, highest priority, lowest price.
     */
    private function ordered(Builder $query): Builder
    {
        return $query
            ->orderByRaw('price_lists.branch_id IS NULL ASC')
            ->orderByDesc('price_list_items.min_qty')
            ->orderByDesc('price_lists.priority')
            ->orderBy('price_list_items.price')->orderBy('price_list_items.id');
    }

    /**
     * Formats rounded pricing amounts and metadata into standard pricing response payload.
     *
     * @return array{unit_price: float, base_price: float, source: string, price_list_id: int|null}
     */
    private function formatResponse(string|float $unitPrice, string $source, ?int $priceListId, ProductVariant $variant, PriceListType $channel): array
    {
        return [
            'unit_price' => (float) (string) BigDecimal::of((string) $unitPrice)->toScale(2, RoundingMode::HalfUp),
            'base_price' => (float) (string) BigDecimal::of($this->basePrice($variant, $channel) ?? (string) $unitPrice)->toScale(2, RoundingMode::HalfUp),
            'source' => $source,
            'price_list_id' => $priceListId,
        ];
    }

    /**
     * Applies charm and psychological price rounding schemes.
     */
    public static function applyRounding(float $price, string $rounding): float
    {
        if ($price <= 0) {
            return round($price, 2);
        }

        return match ($rounding) {
            'nearest_5' => round($price / 5.0) * 5.0,
            'nearest_10' => round($price / 10.0) * 10.0,
            'end_with_9' => max(9.0, floor($price / 10.0) * 10.0 + 9.0),
            'end_with_99' => max(99.0, round($price / 100.0) * 100.0 - 1.0),
            default => round($price, 2),
        };
    }
}<?php

declare(strict_types=1);

namespace App\Services;

use App\Enums\TreasuryTransactionType;
use App\Enums\TreasuryTransferStatus;
use App\Exceptions\BusinessException;
use App\Models\Branch;
use App\Models\PosShift;
use App\Models\Treasury;
use App\Models\TreasuryTransaction;
use App\Models\TreasuryTransfer;
use App\Models\User;
use Brick\Math\BigDecimal;
use Brick\Math\RoundingMode;
use Illuminate\Support\Collection;
use Illuminate\Support\Facades\DB;

/**
 * Single entry point for treasury mutations, enforcing balance integrity and audit logging.
 */
class TreasuryService
{
    public function __construct(private readonly SettingService $settings) {}

    /**
     * Creates a new treasury account and posts optional opening balance.
     *
     * @param  array<string, mixed>  $data  Treasury attributes
     * @param  User  $actor  Staff user creating the treasury
     * @param  string  $opening  Initial opening balance amount
     * @return Treasury Created treasury model
     */
    public function createAccount(array $data, User $actor, string $opening = '0.00'): Treasury
    {
        $this->assertAccountBranch($actor, isset($data['branch_id']) ? (int) $data['branch_id'] : null);

        return DB::transaction(function () use ($data, $actor, $opening): Treasury {
            $treasury = Treasury::create($data + ['current_balance' => '0.00']);
            if (bccomp($opening, '0', 2) !== 0) {
                $this->record([
                    'treasury_id' => $treasury->id,
                    'type' => TreasuryTransactionType::OpeningBalance,
                    'amount' => $opening,
                    'created_by' => $actor->id,
                    'notes' => "رصيد افتتاحي #{$treasury->code}",
                ]);
            }

            return $treasury->refresh();
        });
    }

    /**
     * Updates treasury account parameters with branch and unsettled shift validation.
     *
     * @param  Treasury  $treasury  Target treasury
     * @param  array<string, mixed>  $data  Updated attributes
     * @param  User  $actor  Staff user initiating update
     * @return Treasury Refreshed treasury model
     *
     * @throws BusinessException If type changed, unsettled shifts exist, or cross-branch move is blocked
     */
    public function updateAccount(Treasury $treasury, array $data, User $actor): Treasury
    {
        if (array_key_exists('branch_id', $data)) {
            $this->assertAccountBranch($actor, isset($data['branch_id']) ? (int) $data['branch_id'] : null);
        }

        return DB::transaction(function () use ($treasury, $data, $actor): Treasury {
            $locked = Treasury::query()->lockForUpdate()->findOrFail($treasury->id);
            app(BranchAccess::class)->assertTreasury($actor->id, $locked);
            if (isset($data['type']) && $data['type'] !== $locked->type->value) {
                throw new BusinessException('نوع الخزينة غير قابل للتغيير.');
            }
            $unsettled = $locked->shifts()->whereIn('status', ['open', 'closed_pending_approval'])->exists();
            if (array_key_exists('branch_id', $data) && $data['branch_id'] != $locked->branch_id
                && ($unsettled || bccomp($locked->current_balance, '0', 2) !== 0 || $locked->transactions()->exists())) {
                throw new BusinessException('لا يمكن نقل خزينة لها رصيد أو سجل حركات إلى فرع آخر.');
            }
            if ($unsettled && array_key_exists('is_active', $data) && ! $data['is_active']) {
                throw new BusinessException('لا يمكن تعطيل درج له وردية لم تُسوَّ.');
            }
            $locked->update($data);

            return $locked;
        });
    }

    /**
     * Deletes an unused treasury account with zero balance and no transaction history.
     *
     * @param  Treasury  $treasury  Target treasury
     * @param  User  $actor  Staff user initiating deletion
     *
     * @throws BusinessException If treasury has non-zero balance, transactions, or shifts
     */
    public function deleteAccount(Treasury $treasury, User $actor): void
    {
        DB::transaction(function () use ($treasury, $actor): void {
            $locked = Treasury::query()->lockForUpdate()->findOrFail($treasury->id);
            app(BranchAccess::class)->assertTreasury($actor->id, $locked);
            if (bccomp($locked->current_balance, '0', 2) !== 0 || $locked->transactions()->exists() || $locked->shifts()->exists()) {
                throw new BusinessException('لا يمكن حذف خزينة لها رصيد أو سجل حركات أو ورديات.');
            }
            $locked->delete();
        });
    }

    private function assertAccountBranch(User $actor, ?int $branchId): void
    {
        $branches = app(BranchAccess::class);
        if ($branchId === null) {
            $branches->assertCentralAccess($actor);
        } else {
            $branches->assertBranch($actor->id, $branchId);
        }
    }

    /**
     * Records a financial transaction and updates treasury balance under a row lock.
     *
     * @param array{
     *     treasury_id: int,
     *     shift_id?: int|null,
     *     type: TreasuryTransactionType,
     *     amount: float|string,
     *     reference_type?: string|null,
     *     reference_id?: int|null,
     *     created_by: int,
     *     notes?: string|null,
     * } $data Transaction payload
     * @return TreasuryTransaction Created transaction record
     *
     * @throws BusinessException If treasury is inactive or insufficient funds
     */
    public function record(array $data): TreasuryTransaction
    {
        return DB::transaction(function () use ($data): TreasuryTransaction {
            /** @var Treasury $treasury */
            $treasury = Treasury::query()->lockForUpdate()->findOrFail($data['treasury_id']);
            if ($treasury->branch_id !== null) {
                app(BranchAccess::class)->lockActiveBranch((int) $treasury->branch_id);
            }

            if (! $treasury->is_active && ! in_array($data['type'], [TreasuryTransactionType::ExpenseReversal, TreasuryTransactionType::CustomerReceiptReversal], true)) {
                throw new BusinessException('الخزينة غير نشطة.');
            }

            $amount = BigDecimal::of((string) $data['amount'])->toScale(2, RoundingMode::HalfUp);
            $balanceAfter = BigDecimal::of((string) $treasury->current_balance)->plus($amount)->toScale(2);

            // Bank accounts support overdrafts; physical safes and POS drawers cannot go negative.
            if ($balanceAfter->isNegative() && $treasury->type->value !== 'bank_account') {
                throw new BusinessException('رصيد الخزينة غير كافٍ لإتمام العملية.');
            }

            $transaction = TreasuryTransaction::create([
                'treasury_id' => $treasury->id,
                'shift_id' => $data['shift_id'] ?? null,
                'type' => $data['type'],
                'amount' => (string) $amount,
                'balance_after' => (string) $balanceAfter,
                'reference_type' => $data['reference_type'] ?? null,
                'reference_id' => $data['reference_id'] ?? null,
                'created_by' => $data['created_by'],
                'notes' => $data['notes'] ?? null,
                'created_at' => now(),
            ]);

            $treasury->current_balance = (string) $balanceAfter;
            $treasury->save();

            return $transaction;
        });
    }

    /**
     * Approves and executes a pending treasury transfer between two accounts.
     *
     * @param  TreasuryTransfer  $transfer  Transfer to approve
     * @param  int  $approverId  User approving the transfer
     * @return TreasuryTransfer Updated transfer record
     *
     * @throws BusinessException If transfer is not pending, self-approved, or unauthorized
     */
    public function approveTransfer(TreasuryTransfer $transfer, int $approverId): TreasuryTransfer
    {
        return DB::transaction(function () use ($transfer, $approverId): TreasuryTransfer {
            $transfer = TreasuryTransfer::query()->lockForUpdate()->findOrFail($transfer->id);
            if ($transfer->status !== TreasuryTransferStatus::Pending) {
                throw new BusinessException('يمكن اعتماد التحويلات المعلقة فقط.');
            }
            // Segregation of duties: creator cannot approve their own transfer.
            if ((int) $transfer->created_by === $approverId) {
                throw new BusinessException('يجب أن يعتمد تحويل الخزينة موظف آخر غير منشئه.');
            }
            $treasuries = $this->lockTreasuries([$transfer->from_treasury_id, $transfer->to_treasury_id], $approverId);
            app(BranchAccess::class)->lockActiveBranches($treasuries->pluck('branch_id')->filter());
            $absAmount = (string) BigDecimal::of((string) $transfer->amount)->abs()->toScale(2, RoundingMode::HalfUp);

            $this->recordTransferPair(
                $transfer->from_treasury_id,
                $transfer->to_treasury_id,
                $absAmount,
                TreasuryTransfer::class,
                $transfer->id,
                $approverId,
                "تحويل #{$transfer->transfer_number} صادر",
                "تحويل #{$transfer->transfer_number} وارد"
            );

            $transfer->update([
                'status' => TreasuryTransferStatus::Approved,
                'approved_by' => $approverId,
            ]);

            return $transfer->fresh();
        }, 3);
    }

    /**
     * Reconciles POS cash drawer variance and transfers closing cash to the branch main safe.
     *
     * @param  PosShift  $shift  Completed POS shift
     * @param  int  $approverId  Manager approving the shift settlement
     *
     * @throws BusinessException If main safe is missing or unauthorized
     */
    public function settleShiftToMainSafe(PosShift $shift, int $approverId): void
    {
        DB::transaction(function () use ($shift, $approverId): void {
            // Deterministic selection picks the oldest active safe when multiple exist.
            $mainSafe = Treasury::query()
                ->where('branch_id', $shift->branch_id)
                ->where('type', 'main_safe')
                ->where('is_active', true)
                ->orderBy('id')
                ->first();

            if ($mainSafe === null) {
                throw new BusinessException('يلزم وجود خزنة رئيسية نشطة لاعتماد الوردية وتسوية رصيد الدرج.');
            }

            $locked = $this->lockTreasuries([$shift->treasury_id, $mainSafe->id]);
            app(BranchAccess::class)->lockActiveBranches($locked->pluck('branch_id')->filter());
            $drawer = $locked->get($shift->treasury_id);
            $amount = (string) BigDecimal::of((string) $shift->actual_closing_cash)->toScale(2, RoundingMode::HalfUp);
            $difference = BigDecimal::of((string) $shift->actual_closing_cash)
                ->minus((string) $drawer->current_balance)->toScale(2);
            if (! $difference->isZero()) {
                $this->record([
                    'treasury_id' => $drawer->id, 'shift_id' => $shift->id,
                    'type' => $difference->isNegative() ? TreasuryTransactionType::CashShortage : TreasuryTransactionType::CashOverage,
                    'amount' => (string) $difference, 'reference_type' => PosShift::class,
                    'reference_id' => $shift->id, 'created_by' => $approverId,
                    'notes' => 'تسوية فرق النقدية للوردية '.$shift->shift_number,
                ]);
            }

            if (BigDecimal::of($amount)->isLessThanOrEqualTo('0')) {
                return;
            }

            $this->recordTransferPair(
                $shift->treasury_id,
                $mainSafe->id,
                $amount,
                PosShift::class,
                $shift->id,
                $approverId,
                "ترحيل إغلاق وردية #{$shift->shift_number}",
                "ترحيل إغلاق وردية #{$shift->shift_number}"
            );
        });
    }

    /**
     * Creates a pending transfer request between two treasuries.
     *
     * @param  array<string, mixed>  $data  Transfer parameters
     * @param  int  $userId  Creator identifier
     * @return TreasuryTransfer Created pending transfer
     *
     * @throws BusinessException If source equals destination or unauthorized
     */
    public function createTransfer(array $data, int $userId): TreasuryTransfer
    {
        return DB::transaction(function () use ($data, $userId): TreasuryTransfer {
            $treasuries = Treasury::query()->whereIn('id', [$data['from_treasury_id'], $data['to_treasury_id']])->get();
            foreach ($treasuries as $treasury) {
                app(BranchAccess::class)->assertTreasury($userId, $treasury);
            }
            app(BranchAccess::class)->lockActiveBranches($treasuries->pluck('branch_id')->filter());
            if ($data['from_treasury_id'] === $data['to_treasury_id']) {
                throw new BusinessException('لا يمكن التحويل من خزينة إلى نفسها.');
            }

            $number = $this->settings->generateNextNumber('treasury_transfer');

            return TreasuryTransfer::create([
                'transfer_number' => $number,
                'from_treasury_id' => $data['from_treasury_id'],
                'to_treasury_id' => $data['to_treasury_id'],
                'amount' => $data['amount'],
                'status' => TreasuryTransferStatus::Pending,
                'created_by' => $userId,
                'notes' => $data['notes'] ?? null,
            ]);
        }, 3);
    }

    /**
     * Rejects a pending treasury transfer without altering account balances.
     *
     * @param  TreasuryTransfer  $transfer  Transfer to reject
     * @param  int  $approverId  User rejecting the transfer
     * @param  string|null  $reason  Optional audit reason (kept for the AI finance tools)
     * @return TreasuryTransfer Updated transfer record
     *
     * @throws BusinessException If transfer is not pending
     */
    public function rejectTransfer(TreasuryTransfer $transfer, int $approverId, ?string $reason = null): TreasuryTransfer
    {
        return DB::transaction(function () use ($transfer, $approverId, $reason): TreasuryTransfer {
            $transfer = TreasuryTransfer::query()->lockForUpdate()->findOrFail($transfer->id);
            if ($transfer->status !== TreasuryTransferStatus::Pending) {
                throw new BusinessException('يمكن رفض التحويلات المعلقة فقط.');
            }
            // Rejections carry no financial movement, avoiding unnecessary row locking contention.
            $transfer->update(['status' => TreasuryTransferStatus::Rejected, 'approved_by' => $approverId, 'rejection_reason' => $reason]);

            return $transfer->fresh();
        }, 3);
    }

    /**
     * Acquires pessimistic locks on specified treasuries in consistent primary key order to prevent deadlocks.
     *
     * @param  list<int>  $ids  Treasury identifiers
     * @param  int|null  $userId  User to verify branch access against
     * @return Collection<int, Treasury> Locked treasuries keyed by ID
     */
    public function lockTreasuries(array $ids, ?int $userId = null): Collection
    {
        $treasuries = Treasury::query()->whereIn('id', $ids)->orderBy('id')->lockForUpdate()->get()->keyBy('id');
        if ($userId !== null) {
            foreach ($treasuries as $treasury) {
                app(BranchAccess::class)->assertTreasury($userId, $treasury);
            }
        }

        return $treasuries;
    }

    /**
     * Record matching outbound and inbound transactions for a treasury-to-treasury transfer.
     */
    private function recordTransferPair(
        int $fromTreasuryId,
        int $toTreasuryId,
        string $amount,
        string $referenceType,
        int $referenceId,
        int $createdBy,
        string $outNotes,
        string $inNotes
    ): void {
        $this->record([
            'treasury_id' => $fromTreasuryId,
            'type' => TreasuryTransactionType::TransferOut,
            'amount' => '-'.$amount,
            'reference_type' => $referenceType,
            'reference_id' => $referenceId,
            'created_by' => $createdBy,
            'notes' => $outNotes,
        ]);

        $this->record([
            'treasury_id' => $toTreasuryId,
            'type' => TreasuryTransactionType::TransferIn,
            'amount' => $amount,
            'reference_type' => $referenceType,
            'reference_id' => $referenceId,
            'created_by' => $createdBy,
            'notes' => $inNotes,
        ]);
    }
}<?php

declare(strict_types=1);

namespace App\Models;

use App\Enums\CustomerStatus;
use App\Enums\CustomerType;
use App\Models\Concerns\SerializesAccountEmail;
use App\Support\ArabicDigits;
use Illuminate\Database\Eloquent\Attributes\Fillable;
use Illuminate\Database\Eloquent\Attributes\Hidden;
use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\HasMany;
use Illuminate\Database\Eloquent\SoftDeletes;
use Illuminate\Database\UniqueConstraintViolationException;
use Illuminate\Foundation\Auth\User as Authenticatable;
use Illuminate\Notifications\Notifiable;
use Illuminate\Validation\ValidationException;
use Laravel\Sanctum\HasApiTokens;

/**
 * Customer entity representing retail shoppers and wholesale/distributor trading partners.
 */
#[Fillable([
    'name',
    'email',
    'phone',
    'whatsapp_phone',
    'whatsapp_opt_in_at',
    'preferred_contact_hours',
    'payment_terms_days',
    'credit_limit',
    'password',
    'type',
    'customer_group_id',
    'company_name',
    'tax_number',
    'commercial_register',
    'status',
    'rejection_reason',
    'suspension_reason',
    'phone_verified_at',
])]
#[Hidden(['password', 'remember_token'])]
/**
 * Customer account entity supporting retail guests, registered shoppers, and wholesale merchants.
 */
class Customer extends Authenticatable
{
    use HasApiTokens, HasFactory, Notifiable, SoftDeletes;
    use SerializesAccountEmail;

    protected static function booted(): void
    {
        static::creating(function (Customer $customer): void {
            if (! array_key_exists('status', $customer->getAttributes())) {
                // Wholesale and distributor accounts require commercial vetting before order placement.
                $customer->status = $customer->isCommercialTier()
                    ? CustomerStatus::Pending : CustomerStatus::Approved;
            }
        });
    }

    public function customerGroup(): BelongsTo
    {
        return $this->belongsTo(CustomerGroup::class);
    }

    /**
     * Check if the account has shopping and ordering privileges.
     *
     * @return bool True if active or pending; false if suspended or rejected.
     */
    public function canShop(): bool
    {
        return ! in_array($this->status, [CustomerStatus::Suspended, CustomerStatus::Rejected], true);
    }

    /**
     * Check if the account belongs to wholesale or distributor commercial tiers.
     */
    public function isCommercialTier(): bool
    {
        return in_array($this->type, [CustomerType::Wholesale, CustomerType::Distributor], true);
    }

    /**
     * Check if the account has approved commercial status (wholesale or distributor).
     */
    public function isWholesaleApproved(): bool
    {
        return $this->status === CustomerStatus::Approved && $this->isCommercialTier();
    }

    public function getEmailForPasswordReset(): string
    {
        return 'customer:'.$this->getKey();
    }

    public function setEmailAttribute(?string $email): void
    {
        $normalized = $email === null ? null : mb_strtolower(trim($email));
        // Changing email invalidates prior verification and requires re-confirming ownership.
        if (($this->attributes['email'] ?? null) !== $normalized) {
            $this->attributes['email_verified_at'] = null;
        }
        $this->attributes['email'] = $normalized;
    }

    public function setPhoneAttribute(string $phone): void
    {
        $this->attributes['phone'] = self::normalizePhone($phone);
    }

    public function setWhatsappPhoneAttribute(?string $phone): void
    {
        $trimmed = $phone === null ? '' : trim($phone);
        $this->attributes['whatsapp_phone'] = $trimmed === '' ? null : self::normalizePhone($trimmed);
    }

    /**
     * Standardize Egyptian mobile numbers into canonical local format (01xxxxxxxxx).
     *
     * Transliterates Eastern Arabic/Persian digits, strips punctuation, and normalizes country prefixes.
     *
     * @param  string  $phone  Raw phone number string.
     * @return string Canonical local phone string.
     */
    public static function normalizePhone(string $phone): string
    {
        $trimmed = preg_replace('/^\s+|\s+$/u', '', $phone) ?? trim($phone);
        // Preserve synthetic placeholder identifiers for legacy accounts without valid phones.
        if (preg_match('/^legacy-[0-9]+$/', $trimmed)) {
            return $trimmed;
        }
        // Normalize Arabic-Indic and Eastern Arabic digits into ASCII equivalents.
        $phone = ArabicDigits::normalize($trimmed);
        $phone = preg_replace('/[\s().-]+/u', '', $phone);
        if (preg_match('/^201[0125][0-9]{8}$/', $phone)) {
            return '0'.substr($phone, 2);
        }
        if (str_starts_with($phone, '+20')) {
            return '0'.substr($phone, 3);
        }
        if (str_starts_with($phone, '0020')) {
            return '0'.substr($phone, 4);
        }

        return $phone;
    }

    /**
     * Normalize an authentication identifier (email or phone number).
     *
     * @param  string|null  $identifier  Raw email or phone number.
     * @return string|null Canonical lowercase email or normalized Egyptian phone.
     */
    public static function normalizeIdentifier(?string $identifier): ?string
    {
        if ($identifier === null) {
            return null;
        }
        $trimmed = trim($identifier);
        if ($trimmed === '') {
            return '';
        }

        return str_contains($trimmed, '@')
            ? mb_strtolower($trimmed)
            : self::normalizePhone($trimmed);
    }

    /**
     * Scope query to find customer by either canonical primary phone or secondary WhatsApp phone.
     */
    public function scopeWhereAnyPhone($query, string $phone)
    {
        $normalized = self::normalizePhone($phone);

        return $query->where(fn ($q) => $q->where('phone', $normalized)->orWhere('whatsapp_phone', $normalized));
    }

    /**
     * Scope query to commercial tier accounts (wholesale and distributor).
     */
    public function scopeCommercial($query)
    {
        return $query->whereIn('type', [CustomerType::Wholesale, CustomerType::Distributor]);
    }

    /**
     * Map database unique constraint collisions on customer attributes to validation exceptions.
     *
     * @param  \Throwable  $e  Captured database or runtime exception.
     * @return \Throwable Converted ValidationException or original exception.
     */
    public static function translateUniqueViolation(\Throwable $e): \Throwable
    {
        if ($e instanceof UniqueConstraintViolationException) {
            $message = $e->getMessage();
            if (str_contains($message, 'phone')) {
                return ValidationException::withMessages(['phone' => 'رقم الموبايل مسجل بالفعل.']);
            }
            if (str_contains($message, 'email')) {
                return ValidationException::withMessages(['email' => 'البريد الإلكتروني مستخدم بالفعل.']);
            }
        }

        return $e;
    }

    public function auditLogs(): HasMany
    {
        return $this->hasMany(CustomerAuditLog::class);
    }

    public function approver(): BelongsTo
    {
        return $this->belongsTo(User::class, 'approved_by');
    }

    public function documents(): HasMany
    {
        return $this->hasMany(CustomerDocument::class);
    }

    public function addresses(): HasMany
    {
        return $this->hasMany(CustomerAddress::class);
    }

    public function returnRequests(): HasMany
    {
        return $this->hasMany(ReturnRequest::class);
    }

    protected function casts(): array
    {
        return [
            'password' => 'hashed',
            'type' => CustomerType::class,
            'status' => CustomerStatus::class,
            'credit_limit' => 'decimal:2',
            'wallet_balance' => 'decimal:2',
            'payment_terms_days' => 'integer',
            'preferred_contact_hours' => 'array',
            'approved_at' => 'datetime',
            'whatsapp_opt_in_at' => 'datetime',
            'phone_verified_at' => 'datetime',
            'email_verified_at' => 'datetime',
        ];
    }
